/**
 * TERRA BELLUM — battle head-up display.
 *
 * Three hairline rows and nothing else, because every pixel spent here is a
 * pixel the board does not get (`updateInsets` in the battle screen feeds these
 * heights straight to `BattleCamera.setInsets`):
 *
 *   1. COMMAND ROW  — both commanders, live chassis counts, the depleting 45 s
 *                     turn ring (`BATTLE.turnMs`) and the turn number.
 *   2. ORDER ROW    — the one instruction for the current phase, its detail, the
 *                     HOW-TO-PLAY key and CONCEDE.
 *   3. TICKER       — the latest narrated combat-log line; tap for the full log.
 *
 * The board's name, twist, hex and terrain used to own a permanent fourth row.
 * They are announced by the intro cinematic and the deployment brief, so they
 * now live in the combat-log sheet instead of costing 30 px a frame.
 */
import { BATTLE, TERRAIN_META } from '../../config/balance';
import type { BattleSide, BattleState, Guild } from '../../game/types';
import { clear, cssHex, el, svg as svgEl } from '../dom';
import { guildSigil, openModal } from '../components';
import { boardTwistOf } from './cinematics';

const RING_R = 15;
const RING_C = 2 * Math.PI * RING_R;
const TICKER_HISTORY = 80;

export type BannerTone = 'idle' | 'you' | 'hostile' | 'setup' | 'danger';

export interface BattleHudState {
  battle: BattleState;
  mySide: BattleSide;
  myGuild?: Guild;
  foeGuild?: Guild;
  instruction: string;
  detail: string;
  tone: BannerTone;
}

export interface BattleHudOpts {
  onConcede(): void;
  /** Fired once per second inside the final ten, then once at zero. */
  onTick(secondsLeft: number): void;
  onOpenLog(): void;
  /** The `?` key — reopens the first-battle coach on demand. */
  onOpenCoach(): void;
}

interface SideNodes {
  root: HTMLElement;
  sigil: HTMLElement;
  name: HTMLElement;
  count: HTMLElement;
}

function sideBlock(kind: 'me' | 'foe'): SideNodes {
  const sigil = el('div', { class: 'bhud__sigil' });
  const name = el('div', { class: 'bhud__name display truncate' });
  const count = el('div', { class: 'bhud__count mono tnum' });
  const root = el(
    'div',
    { class: `bhud__cmdr bhud__cmdr--${kind}` },
    sigil,
    el('div', { class: 'bhud__who' }, name),
    count,
  );
  return { root, sigil, name, count };
}

export class BattleHud {
  readonly el: HTMLElement;

  private me: SideNodes;
  private foe: SideNodes;
  private turnNo: HTMLElement;
  private ringVal: SVGCircleElement;
  private ringNum: HTMLElement;
  private ring: HTMLElement;
  private banner: HTMLElement;
  private ticker: HTMLElement;
  private cede: HTMLButtonElement;
  private helpBtn: HTMLButtonElement;

  private log: string[] = [];
  private lastTickSecond = -1;
  private lastKey = '';
  private board: { name: string; twist: string; hex: string; terrain: string; fort: number } = {
    name: '',
    twist: '',
    hex: '',
    terrain: '',
    fort: 0,
  };

  constructor(private opts: BattleHudOpts) {
    this.me = sideBlock('me');
    this.foe = sideBlock('foe');

    this.turnNo = el('div', { class: 'bhud__turn mono' });
    this.ringNum = el('div', { class: 'bhud__secs display tnum', text: '45' });

    const ringSvg = svgEl(
      `<svg class="bhud__ringsvg" viewBox="0 0 36 36" aria-hidden="true">
         <circle class="trk" cx="18" cy="18" r="${RING_R}"></circle>
         <circle class="val" cx="18" cy="18" r="${RING_R}"
                 stroke-dasharray="${RING_C.toFixed(2)}" stroke-dashoffset="0"></circle>
       </svg>`,
    );
    this.ringVal = ringSvg.querySelector('.val') as SVGCircleElement;
    this.ring = el('div', { class: 'bhud__ring' }, ringSvg, this.ringNum);

    this.cede = el(
      'button',
      {
        class: 'bhud__key bhud__key--cede',
        attrs: { type: 'button' },
        aria: { label: 'concede the engagement' },
      },
      el('span', { text: 'CONCEDE' }),
    );
    this.cede.addEventListener('click', () => this.opts.onConcede());

    this.helpBtn = el(
      'button',
      {
        class: 'bhud__key bhud__key--help',
        attrs: { type: 'button', title: 'how to play' },
        aria: { label: 'how to play' },
      },
      el('span', { text: '?' }),
    );
    this.helpBtn.addEventListener('click', () => this.opts.onOpenCoach());

    this.banner = el('div', { class: 'bhud__banner' });
    this.ticker = el('button', {
      class: 'bhud__ticker mono',
      attrs: { type: 'button' },
      aria: { label: 'open the combat log' },
    });
    this.ticker.addEventListener('click', () => this.opts.onOpenLog());

    this.el = el(
      'div',
      { class: 'bhud' },
      el('div', { class: 'bhud__veil', aria: { hidden: 'true' } }),
      el(
        'div',
        { class: 'bhud__top' },
        this.me.root,
        el('div', { class: 'bhud__clock' }, this.ring, this.turnNo),
        this.foe.root,
      ),
      el('div', { class: 'bhud__order' }, this.banner, this.helpBtn, this.cede),
      this.ticker,
    );

    this.setTimer(BATTLE.turnMs, BATTLE.turnMs, false);
  }

  // ── state ─────────────────────────────────────────────────────────────────

  sync(s: BattleHudState): void {
    const b = s.battle;
    const foeSide: BattleSide = s.mySide === 'attacker' ? 'defender' : 'attacker';
    const mine = s.mySide === 'attacker' ? b.attacker : b.defender;
    const theirs = foeSide === 'attacker' ? b.attacker : b.defender;

    const myAlive = b.units.filter((u) => u.side === s.mySide && u.alive).length;
    const myTotal = b.units.filter((u) => u.side === s.mySide).length;
    const foeAlive = b.units.filter((u) => u.side === foeSide && u.alive).length;
    const foeTotal = b.units.filter((u) => u.side === foeSide).length;

    const myColor = cssHex(mine.guildColor);
    const foeColor = cssHex(
      theirs.guildColor === mine.guildColor ? 0xff4d5e : theirs.guildColor,
    );

    const terrain = TERRAIN_META[b.terrain];
    this.board = {
      name: b.boardName,
      twist: boardTwistOf(b.boardId),
      hex: b.hexId,
      terrain: terrain.label,
      fort: b.fortLevel,
    };

    const key = [
      b.id,
      mine.playerName,
      theirs.playerName,
      myAlive,
      myTotal,
      foeAlive,
      foeTotal,
      b.turnNumber,
      b.turn,
      b.phase,
      s.instruction,
      s.detail,
      s.tone,
      s.myGuild?.id ?? '-',
      s.foeGuild?.id ?? '-',
    ].join('|');
    if (key === this.lastKey) return;
    this.lastKey = key;

    this.el.style.setProperty('--me-color', myColor);
    this.el.style.setProperty('--foe-color', foeColor);

    this.me.name.textContent = mine.playerName;
    this.me.root.setAttribute(
      'title',
      `${mine.playerName} [${mine.guildTag}] — ${s.mySide === 'attacker' ? 'ATTACK' : 'DEFENCE'}`,
    );
    this.me.count.textContent = `${myAlive}/${myTotal}`;
    this.me.count.classList.toggle('is-low', myAlive <= 1);

    this.foe.name.textContent = theirs.playerName;
    this.foe.root.setAttribute(
      'title',
      `${theirs.playerName} [${theirs.guildTag}] — ${
        theirs.ai ? 'AUTO-DEFENSE' : foeSide === 'attacker' ? 'ATTACK' : 'DEFENCE'
      }`,
    );
    this.foe.count.textContent = `${foeAlive}/${foeTotal}`;
    this.foe.count.classList.toggle('is-low', foeAlive <= 1);
    this.foe.root.classList.toggle('is-ai', theirs.ai === true);

    clear(this.me.sigil);
    if (s.myGuild) this.me.sigil.appendChild(guildSigil(s.myGuild, 20));
    clear(this.foe.sigil);
    if (s.foeGuild) this.foe.sigil.appendChild(guildSigil(s.foeGuild, 20));

    this.me.root.classList.toggle('is-active', b.turn === s.mySide && b.phase !== 'ended');
    this.foe.root.classList.toggle('is-active', b.turn === foeSide && b.phase !== 'ended');

    this.turnNo.textContent = b.turnNumber > 0 ? `T${b.turnNumber}` : 'SET';

    this.banner.className = `bhud__banner is-${s.tone}`;
    clear(this.banner);
    this.banner.appendChild(el('span', { class: 'bhud__bar', aria: { hidden: 'true' } }));
    this.banner.appendChild(el('span', { class: 'bhud__inst display', text: s.instruction }));
    if (s.detail) {
      this.banner.appendChild(el('span', { class: 'bhud__det truncate', text: s.detail }));
    }
    this.banner.setAttribute('title', s.detail ? `${s.instruction} — ${s.detail}` : s.instruction);

    this.cede.classList.toggle('is-hidden', b.phase === 'ended');
  }

  /** Append a narrated combat-log line and flash the ticker. */
  push(line: string): void {
    this.log.push(line);
    if (this.log.length > TICKER_HISTORY) this.log.splice(0, this.log.length - TICKER_HISTORY);
    this.ticker.classList.remove('is-new');
    void this.ticker.offsetWidth;
    clear(this.ticker);
    this.ticker.appendChild(el('span', { class: 'bhud__tk-dot', aria: { hidden: 'true' } }));
    this.ticker.appendChild(el('span', { class: 'bhud__tk-text truncate', text: line }));
    this.ticker.classList.add('is-new');
  }

  resetLog(): void {
    this.log.length = 0;
    clear(this.ticker);
    this.ticker.appendChild(el('span', { class: 'bhud__tk-dot', aria: { hidden: 'true' } }));
    this.ticker.appendChild(el('span', { class: 'bhud__tk-text', text: 'COMBAT LINK ESTABLISHED' }));
  }

  /** Full scrollback plus the board dossier, opened from the ticker. */
  openLog(): void {
    const body = el('div', { class: 'blog' });
    body.appendChild(
      el(
        'div',
        { class: 'blog__board' },
        el('div', { class: 'blog__bname display', text: this.board.name }),
        el('div', { class: 'blog__btwist', text: this.board.twist }),
        el('div', {
          class: 'blog__bmeta mono',
          text: `HEX ${this.board.hex} · ${this.board.terrain}${
            this.board.fort > 0 ? ` · FORT L${this.board.fort}` : ''
          }`,
        }),
      ),
    );
    if (this.log.length === 0) {
      body.appendChild(el('div', { class: 'blog__none', text: 'NOTHING LOGGED YET' }));
    }
    for (let i = this.log.length - 1; i >= 0; i--) {
      body.appendChild(
        el(
          'div',
          { class: 'blog__row mono' },
          el('span', { class: 'blog__n', text: String(i + 1).padStart(3, '0') }),
          el('span', { class: 'blog__t selectable', text: this.log[i] }),
        ),
      );
    }
    openModal({
      title: 'COMBAT LOG',
      body,
      accent: 'var(--cyan)',
      actions: [{ label: 'CLOSE', variant: 'ghost', close: true }],
    });
  }

  /**
   * Drive the depleting ring. `remaining` and `total` are in ms; `live` is false
   * during setup and hostile phases so the ring idles instead of counting down.
   */
  setTimer(remaining: number, total: number, live: boolean): void {
    const span = Math.max(1, total);
    const clamped = Math.max(0, Math.min(span, remaining));
    const frac = clamped / span;
    this.ringVal.style.strokeDashoffset = String(RING_C * (1 - frac));

    const secs = Math.ceil(clamped / 1000);
    const label = live ? String(secs) : '—';
    if (this.ringNum.textContent !== label) this.ringNum.textContent = label;

    this.ring.classList.toggle('is-idle', !live);
    this.ring.classList.toggle('is-warn', live && frac <= 0.4 && frac > 0.15);
    this.ring.classList.toggle('is-crit', live && frac <= 0.15);

    if (!live) {
      this.lastTickSecond = -1;
      return;
    }
    if (secs <= 10 && secs !== this.lastTickSecond) {
      this.lastTickSecond = secs;
      this.opts.onTick(secs);
    } else if (secs > 10) {
      this.lastTickSecond = -1;
    }
  }

  dispose(): void {
    this.log.length = 0;
  }
}
