/**
 * TERRA BELLUM — contextual action bar (GDD §7.2.4).
 *
 * Three verbs, one AP each: MOVE, ATTACK, BRACE. The bar is *contextual* in the
 * literal sense — with no chassis selected it occupies zero pixels, because a
 * permanent "NO CHASSIS SELECTED" plate was costing the board 70 px for the
 * privilege of saying nothing. The prompt to select one lives in the dice tray,
 * where the eye already is.
 *
 * When a chassis IS selected the bar is one row: identity + AP budget on the
 * left, the three verbs on the right. Every button carries its AP cost as pips
 * and, when unavailable, the exact reason why. ATTACK opens a rail of live
 * firing solutions with predicted damage — brace and cover mitigation already
 * subtracted — and a kill flag when the shot finishes the target. Damage is
 * flat (GDD §7.2), so the rail is a calculator, not a guess.
 */
import { BATTLE } from '../../config/balance';
import { UNITS } from '../../config/units';
import type { BattleUnit, UnitId, UnitType } from '../../game/types';
import { clear, el, haptic, svg as svgEl } from '../dom';
import { unitAccent, unitSilhouette } from '../components';

export type ActionMode = 'none' | 'move' | 'attack';

export interface UnitTarget {
  kind: 'unit';
  id: UnitId;
  type: UnitType;
  label: string;
  hp: number;
  maxHp: number;
  damage: number;
  mitigated: number;
  kill: boolean;
  x: number;
  y: number;
}

export interface WallTarget {
  kind: 'wall';
  x: number;
  y: number;
  damage: number;
  hp: number;
  destroyed: boolean;
}

export type AttackTarget = UnitTarget | WallTarget;

export interface Gate {
  ok: boolean;
  reason: string;
}

export interface ActionBarState {
  unit: BattleUnit | null;
  /** Original die value for the selected unit, for the AP readout. */
  dieValue: number;
  mode: ActionMode;
  move: Gate;
  attack: Gate;
  brace: Gate;
  /** How many distinct tiles a single MOVE action can reach right now. */
  reachCount: number;
  targets: AttackTarget[];
  attacksLeft: number;
  busy: boolean;
  /** Hide entirely (setup phases, hostile turn). */
  hidden: boolean;
}

export interface ActionBarOpts {
  onMode(mode: ActionMode): void;
  onBrace(): void;
  onTarget(target: AttackTarget): void;
}

function apPips(cost: number, affordable: boolean): HTMLElement {
  const wrap = el('span', { class: 'act__cost', aria: { hidden: 'true' } });
  for (let i = 0; i < cost; i++) {
    wrap.appendChild(el('i', { class: affordable ? 'appip is-on' : 'appip' }));
  }
  return wrap;
}

export class ActionBar {
  readonly el: HTMLElement;

  private head: HTMLElement;
  private buttons: HTMLElement;
  private rail: HTMLElement;
  private hint: HTMLElement;
  private state: ActionBarState | null = null;

  constructor(private opts: ActionBarOpts) {
    this.head = el('div', { class: 'act__head' });
    this.buttons = el('div', { class: 'act__btns' });
    this.rail = el('div', { class: 'act__rail scroll-x no-scrollbar' });
    this.hint = el('div', { class: 'act__hint mono' });

    this.el = el(
      'div',
      { class: 'act' },
      el('div', { class: 'act__edge', aria: { hidden: 'true' } }),
      this.head,
      this.buttons,
      this.rail,
      this.hint,
    );
  }

  sync(next: ActionBarState): void {
    this.state = next;
    // No chassis selected is not a state worth a panel — collapse to nothing and
    // give the pixels back to the board.
    this.el.classList.toggle('is-hidden', next.hidden || next.unit === null);
    if (next.hidden || !next.unit) return;

    this.renderHead(next);
    this.renderButtons(next);
    this.renderRail(next);
    this.renderHint(next);
  }

  dispose(): void {
    clear(this.rail);
    clear(this.buttons);
    clear(this.head);
  }

  // ── sections ──────────────────────────────────────────────────────────────

  private renderHead(s: ActionBarState): void {
    clear(this.head);
    if (!s.unit) return;
    const u = s.unit;
    const def = UNITS[u.type];

    const art = el('div', { class: 'act__art', style: `--accent:${unitAccent(u.type)}` });
    art.appendChild(svgEl(unitSilhouette(u.type)));

    const pips = el('div', { class: 'act__ap' });
    const total = Math.max(s.dieValue, u.ap);
    if (total === 0) {
      pips.appendChild(el('span', { class: 'act__ap-none', text: 'NO AP' }));
    } else {
      for (let i = 0; i < total; i++) {
        pips.appendChild(el('i', { class: i < u.ap ? 'appip is-on' : 'appip is-spent' }));
      }
      pips.appendChild(el('span', { class: 'act__ap-n mono tnum', text: `${u.ap}` }));
    }

    this.head.appendChild(art);
    this.head.appendChild(
      el(
        'div',
        { class: 'act__id' },
        el('div', { class: 'act__name display truncate', text: def.codename }),
        pips,
        el('div', {
          class: `act__fire mono${s.attacksLeft <= 0 ? ' is-spent' : ''}`,
          text: `${u.x}·${u.y} · FIRE ${BATTLE.maxAttacksPerTurn - s.attacksLeft}/${
            BATTLE.maxAttacksPerTurn
          }${u.braced ? ' · BRACED' : ''}`,
        }),
      ),
    );
  }

  private verb(
    label: string,
    glyph: string,
    gate: Gate,
    active: boolean,
    cost: number,
    onTap: () => void,
    busy: boolean,
  ): HTMLElement {
    const node = el('button', {
      class: `act-btn${active ? ' is-on' : ''}${gate.ok ? '' : ' is-off'}`,
      attrs: { type: 'button', disabled: !gate.ok || busy, title: gate.ok ? label : gate.reason },
      aria: { pressed: active },
    });
    node.appendChild(el('span', { class: 'act-btn__glyph', text: glyph, aria: { hidden: 'true' } }));
    node.appendChild(el('span', { class: 'act-btn__label display', text: label }));
    node.appendChild(apPips(cost, gate.ok));
    node.appendChild(
      el('span', { class: 'act-btn__why truncate', text: gate.ok ? '' : gate.reason }),
    );
    node.addEventListener('click', () => {
      if (!gate.ok || busy) return;
      haptic(9);
      onTap();
    });
    return node;
  }

  private renderButtons(s: ActionBarState): void {
    clear(this.buttons);
    if (!s.unit) return;

    this.buttons.appendChild(
      this.verb(
        'MOVE',
        '⇢',
        s.move,
        s.mode === 'move',
        1,
        () => this.opts.onMode(s.mode === 'move' ? 'none' : 'move'),
        s.busy,
      ),
    );
    this.buttons.appendChild(
      this.verb(
        'ATTACK',
        '◎',
        s.attack,
        s.mode === 'attack',
        1,
        () => this.opts.onMode(s.mode === 'attack' ? 'none' : 'attack'),
        s.busy,
      ),
    );
    this.buttons.appendChild(
      this.verb('BRACE', '⛨', s.brace, false, 1, () => this.opts.onBrace(), s.busy),
    );
  }

  private renderRail(s: ActionBarState): void {
    clear(this.rail);
    this.rail.classList.toggle('is-on', s.mode === 'attack' && s.unit !== null);
    if (s.mode !== 'attack' || !s.unit) return;

    if (s.targets.length === 0) {
      this.rail.appendChild(
        el('div', { class: 'act__none', text: 'NO FIRING SOLUTION — MOVE OR BRACE' }),
      );
      return;
    }

    for (const t of s.targets) {
      if (t.kind === 'unit') {
        const cell = el('button', {
          class: `tgt${t.kill ? ' is-kill' : ''}`,
          style: `--accent:${unitAccent(t.type)}`,
          attrs: { type: 'button', disabled: s.busy },
          aria: { label: `attack ${t.label} for ${t.damage}` },
        });
        const art = el('div', { class: 'tgt__art' });
        art.appendChild(svgEl(unitSilhouette(t.type)));
        cell.appendChild(art);
        cell.appendChild(
          el(
            'div',
            { class: 'tgt__dmg' },
            el('span', { class: 'tgt__dmg-n display tnum', text: `−${t.damage}` }),
            el('span', {
              class: `tgt__verdict${t.kill ? ' is-kill' : ''}`,
              text: t.kill ? 'KILL' : `${t.hp - t.damage} LEFT`,
            }),
          ),
        );
        cell.appendChild(el('div', { class: 'tgt__name mono truncate', text: t.label }));
        cell.appendChild(
          el(
            'div',
            { class: 'tgt__hp mono tnum' },
            el('span', { text: `${t.hp}/${t.maxHp}` }),
            t.mitigated > 0
              ? el('span', { class: 'tgt__mit mono', text: ` −${t.mitigated} MIT` })
              : el('span', { class: 'tgt__mit mono dim-2', text: ' CLEAN' }),
          ),
        );
        cell.addEventListener('click', () => {
          if (s.busy) return;
          haptic([12, 22, 12]);
          this.opts.onTarget(t);
        });
        this.rail.appendChild(cell);
      } else {
        const cell = el('button', {
          class: `tgt tgt--wall${t.destroyed ? ' is-kill' : ''}`,
          attrs: { type: 'button', disabled: s.busy },
          aria: { label: `attack wall at ${t.x} ${t.y}` },
        });
        cell.appendChild(el('div', { class: 'tgt__art tgt__art--wall', text: '▤' }));
        cell.appendChild(
          el(
            'div',
            { class: 'tgt__dmg' },
            el('span', { class: 'tgt__dmg-n display tnum', text: `−${t.damage}` }),
            el('span', {
              class: `tgt__verdict${t.destroyed ? ' is-kill' : ''}`,
              text: t.destroyed ? 'BREACH' : 'CRACK',
            }),
          ),
        );
        cell.appendChild(el('div', { class: 'tgt__name mono', text: `WALL ${t.x}·${t.y}` }));
        cell.appendChild(el('div', { class: 'tgt__hp mono tnum', text: `${t.hp} HP` }));
        cell.addEventListener('click', () => {
          if (s.busy) return;
          haptic([12, 22, 12]);
          this.opts.onTarget(t);
        });
        this.rail.appendChild(cell);
      }
    }
  }

  private renderHint(s: ActionBarState): void {
    clear(this.hint);
    if (!s.unit) return;
    if (s.mode === 'move') {
      this.hint.textContent =
        s.reachCount > 0
          ? `${s.reachCount} TILES IN REACH — TAP THE BOARD (1 AP)`
          : 'NOWHERE TO GO — THIS CHASSIS IS BOXED IN';
      return;
    }
    if (s.mode === 'attack') {
      this.hint.textContent = 'TAP A SOLUTION, OR THE TARGET ON THE BOARD';
      return;
    }
    const def = UNITS[s.unit.type];
    this.hint.textContent = `${def.name} · MOV ${def.mov} · RNG ${def.rng} · ATK ${def.atk} FLAT`;
  }
}
