/**
 * TERRA BELLUM — the battle rosters.
 *
 * Two horizontally scrolling lanes, stacked and stripped to the bone: a hostile
 * peek strip (silhouette, HP bar, HP) over the commander's own chassis strip
 * (silhouette, HP, assigned die, AP pips, brace state, selection). The lane
 * headers are gone — the HUD's command row already names both commanders and
 * carries their live chassis counts, and repeating it here cost the board 22 px.
 *
 * Every friendly chip advertises `data-drop-unit`, which is how the dice tray
 * resolves a drag-and-drop onto a chassis: the tray hit-tests the point with
 * `document.elementFromPoint` and reads that attribute back off.
 */
import { UNITS } from '../../config/units';
import { BATTLE } from '../../config/balance';
import type { BattleUnit, DieIndex, UnitId } from '../../game/types';
import { clear, el, haptic, svg as svgEl } from '../dom';
import { unitAccent, unitSilhouette } from '../components';

export interface UnitBarOpts {
  onSelect(unitId: UnitId): void;
  onEnemyTap(unitId: UnitId): void;
}

export interface UnitBarState {
  mine: BattleUnit[];
  enemy: BattleUnit[];
  selectedId?: UnitId;
  /** Units that will accept the die currently being dragged / armed. */
  dropTargets: Set<UnitId>;
  /** A die is in flight or armed — light the valid chassis up. */
  dropping: boolean;
  /** Enemy units currently valid as attack targets. */
  threatTargets: Set<UnitId>;
  /** Show AP pips (true from assignment onward). */
  showAp: boolean;
  /** The active roll, so a chip can draw spent pips as well as remaining ones. */
  dice: [number, number, number] | null;
  /** Dice docked onto a chassis during the assign phase, before AP is locked in. */
  pending: Map<UnitId, { die: DieIndex; value: number }>;
  myLabel: string;
  enemyLabel: string;
  myColor: string;
  enemyColor: string;
}

interface Cell {
  root: HTMLButtonElement;
  art: HTMLElement;
  hpFill: HTMLElement;
  hpText: HTMLElement;
  pips: HTMLElement;
  flags: HTMLElement;
  key: string;
}

/** Four-character call-sign tail, so a chip is identifiable at a glance. */
export function unitCallsign(u: BattleUnit): string {
  const tail = u.id.split(/[_:]/).pop() ?? u.id;
  return tail.slice(-4).toUpperCase();
}

/** `EXO-9 · 4A21` — used by the dice tray dock label too. */
export function unitLabel(u: BattleUnit): string {
  return `${UNITS[u.type].codename} · ${unitCallsign(u)}`;
}

function ratio(u: BattleUnit): number {
  return u.maxHp > 0 ? Math.max(0, Math.min(1, u.hp / u.maxHp)) : 0;
}

function hpClass(r: number): string {
  if (r <= 0.15) return 'is-crit';
  if (r <= 0.4) return 'is-hurt';
  return 'is-ok';
}

export class UnitBar {
  readonly el: HTMLElement;

  private enemyLane: HTMLElement;
  private myLane: HTMLElement;
  private cells = new Map<string, Cell>();
  private state: UnitBarState | null = null;

  constructor(private opts: UnitBarOpts) {
    this.enemyLane = el('div', {
      class: 'ubar__lane ubar__lane--foe scroll-x no-scrollbar',
      attrs: { role: 'group' },
    });
    this.myLane = el('div', {
      class: 'ubar__lane ubar__lane--me scroll-x no-scrollbar',
      attrs: { role: 'group' },
    });

    this.el = el('div', { class: 'ubar' }, this.enemyLane, this.myLane);
  }

  sync(next: UnitBarState): void {
    this.state = next;
    this.el.style.setProperty('--me-color', next.myColor);
    this.el.style.setProperty('--foe-color', next.enemyColor);
    this.el.classList.toggle('is-dropping', next.dropping);

    this.myLane.setAttribute('aria-label', `your chassis — ${next.myLabel}`);
    this.enemyLane.setAttribute('aria-label', `hostile chassis — ${next.enemyLabel}`);

    this.renderLane(this.myLane, next.mine, true, next);
    this.renderLane(this.enemyLane, next.enemy, false, next);
    this.prune(next);
  }

  /** Scroll the selected chassis into view. */
  revealSelected(): void {
    const id = this.state?.selectedId;
    if (!id) return;
    const cell = this.cells.get(`me:${id}`);
    cell?.root.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
  }

  dispose(): void {
    this.cells.clear();
    clear(this.myLane);
    clear(this.enemyLane);
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private renderLane(
    lane: HTMLElement,
    units: BattleUnit[],
    mine: boolean,
    s: UnitBarState,
  ): void {
    const prefix = mine ? 'me' : 'foe';
    let cursor: ChildNode | null = lane.firstChild;

    for (const u of units) {
      const key = `${prefix}:${u.id}`;
      let cell = this.cells.get(key);
      if (!cell) {
        cell = this.buildCell(u, mine);
        this.cells.set(key, cell);
      }
      if (cursor !== cell.root) {
        lane.insertBefore(cell.root, cursor);
      } else {
        cursor = cursor.nextSibling;
      }
      this.updateCell(cell, u, mine, s);
    }
  }

  private prune(s: UnitBarState): void {
    const live = new Set<string>();
    for (const u of s.mine) live.add(`me:${u.id}`);
    for (const u of s.enemy) live.add(`foe:${u.id}`);
    for (const [key, cell] of Array.from(this.cells)) {
      if (live.has(key)) continue;
      cell.root.remove();
      this.cells.delete(key);
    }
  }

  private buildCell(u: BattleUnit, mine: boolean): Cell {
    const root = el('button', {
      class: `uslug uslug--${mine ? 'me' : 'foe'}`,
      style: `--accent:${unitAccent(u.type)}`,
      attrs: { type: 'button' },
      data: mine ? { dropUnit: u.id, unitId: u.id } : { unitId: u.id },
      aria: { label: unitLabel(u) },
    });

    const art = el('div', { class: 'uslug__art' });
    art.appendChild(svgEl(unitSilhouette(u.type)));

    const hpFill = el('i', { class: 'uslug__hpfill' });
    const hpTrack = el('div', { class: 'uslug__hptrack' }, hpFill);
    const hpText = el('span', { class: 'uslug__hp mono tnum' });
    const pips = el('div', { class: 'uslug__pips' });
    const flags = el('div', { class: 'uslug__flags' });

    root.appendChild(el('span', { class: 'uslug__ring', aria: { hidden: 'true' } }));
    root.appendChild(art);
    root.appendChild(
      el(
        'div',
        { class: 'uslug__meta' },
        el('span', { class: 'uslug__code', text: UNITS[u.type].codename }),
        hpText,
      ),
    );
    root.appendChild(hpTrack);
    if (mine) root.appendChild(pips);
    root.appendChild(flags);

    root.addEventListener('click', () => {
      haptic(8);
      if (mine) this.opts.onSelect(u.id);
      else this.opts.onEnemyTap(u.id);
    });

    return { root, art, hpFill, hpText, pips, flags, key: '' };
  }

  private updateCell(cell: Cell, u: BattleUnit, mine: boolean, s: UnitBarState): void {
    const r = ratio(u);
    const docked = s.pending.get(u.id);
    const key = [
      u.hp,
      u.maxHp,
      u.alive ? 1 : 0,
      u.braced ? 1 : 0,
      u.ap,
      u.die ?? -1,
      u.attacksThisTurn,
      s.selectedId === u.id ? 1 : 0,
      s.dropTargets.has(u.id) ? 1 : 0,
      s.threatTargets.has(u.id) ? 1 : 0,
      s.dropping ? 1 : 0,
      s.showAp ? 1 : 0,
      docked ? `${docked.die}:${docked.value}` : '-',
    ].join('|');
    if (cell.key === key) return;
    cell.key = key;

    cell.root.classList.toggle('is-dead', !u.alive);
    cell.root.classList.toggle('is-sel', s.selectedId === u.id);
    cell.root.classList.toggle('is-drop', mine && s.dropping && s.dropTargets.has(u.id));
    cell.root.classList.toggle('is-blocked', mine && s.dropping && !s.dropTargets.has(u.id));
    cell.root.classList.toggle('is-threat', !mine && s.threatTargets.has(u.id));
    cell.root.disabled = !u.alive;

    cell.hpFill.style.width = `${(r * 100).toFixed(1)}%`;
    cell.hpFill.className = `uslug__hpfill ${hpClass(r)}`;
    cell.hpText.textContent = u.alive ? `${u.hp}/${u.maxHp}` : 'K.I.A.';

    clear(cell.pips);
    cell.root.classList.toggle('is-docked', mine && (docked !== undefined || u.die !== undefined));
    if (mine && s.showAp && u.die !== undefined) {
      const budget = Math.max(u.ap, 0);
      const dieValue = s.dice ? s.dice[u.die] : budget;
      const total = Math.max(dieValue, budget);
      if (total === 0) {
        cell.pips.appendChild(el('span', { class: 'uslug__zero', text: '0 AP · SKIP' }));
      } else {
        for (let i = 0; i < total; i++) {
          cell.pips.appendChild(el('i', { class: i < budget ? 'appip is-on' : 'appip' }));
        }
      }
      cell.pips.appendChild(el('span', { class: 'uslug__die mono', text: `D${u.die + 1}` }));
    } else if (mine && docked) {
      if (docked.value === 0) {
        cell.pips.appendChild(el('span', { class: 'uslug__zero', text: '0 AP · SKIP' }));
      } else {
        for (let i = 0; i < docked.value; i++) {
          cell.pips.appendChild(el('i', { class: 'appip is-on' }));
        }
      }
      cell.pips.appendChild(el('span', { class: 'uslug__die mono', text: `D${docked.die + 1}` }));
    } else if (mine && u.alive && s.dice !== null) {
      // A live roll with nothing docked here: say so, rather than leave a blank
      // row a newcomer has to interpret. Wrecks are exempt — "NO DIE" under a
      // K.I.A. chip is noise, and the chip itself collapses to a stub so the
      // dead do not push the living out of the lane.
      cell.pips.appendChild(el('span', { class: 'uslug__idle', text: 'NO DIE' }));
    }

    clear(cell.flags);
    if (u.braced) cell.flags.appendChild(el('span', { class: 'uflag uflag--brace', text: '⛨' }));
    if (mine && u.alive && u.attacksThisTurn >= BATTLE.maxAttacksPerTurn) {
      cell.flags.appendChild(el('span', { class: 'uflag uflag--spent', text: 'NO FIRE' }));
    }
    if (!u.alive) cell.flags.appendChild(el('span', { class: 'uflag uflag--dead', text: '✕' }));
  }
}
