/**
 * TERRA BELLUM — battle camera (GDD §12.3: "low camera angle fitting the full
 * board in portrait").
 *
 * The framing distance is SOLVED, not guessed: the board's corner volume is
 * projected against the viewport's safe band (the dice tray eats the bottom of
 * a portrait phone) and the distance is bisected until every corner is inside.
 * The board can never overflow, at any aspect ratio, at any board size.
 */
import * as THREE from 'three';
import { BATTLE_VIEW } from '../../config/visual';
import { TILE_PITCH, tileWorldX, tileWorldZ } from './tiles';

interface Tween {
  t: number;
  d: number;
  fn: (k: number) => void;
  resolve: () => void;
}

const easeOutCubic = (k: number): number => 1 - Math.pow(1 - k, 3);
const easeInOutCubic = (k: number): number =>
  k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;

const _dir = new THREE.Vector3();
const _right = new THREE.Vector3();
const _up = new THREE.Vector3();
const _fwd = new THREE.Vector3();
const _corner = new THREE.Vector3();
const _rel = new THREE.Vector3();
const _eye = new THREE.Vector3();
const _look = new THREE.Vector3();
const WORLD_UP = new THREE.Vector3(0, 1, 0);

/** How far the camera may drift toward the acting unit, in world units. */
const FOCUS_DRIFT = TILE_PITCH * 0.55;

export interface SafeInsets {
  top: number;
  bottom: number;
  side: number;
}

export class BattleCamera {
  readonly camera: THREE.PerspectiveCamera;

  /** Board centre (world). Focus drift rides on top of this. */
  private home = new THREE.Vector3();
  private target = new THREE.Vector3();
  private desiredTarget = new THREE.Vector3();
  private aimShift = new THREE.Vector3();

  private azimuth = 0;
  private desiredAzimuth = 0;
  private polar: number = BATTLE_VIEW.camera.polar;
  private desiredPolar: number = BATTLE_VIEW.camera.polar;

  private fitDistance: number = BATTLE_VIEW.camera.distance;
  /**
   * User zoom and cinematic dolly are SEPARATE multipliers on purpose.
   *
   * They used to be one `distanceScale`, which meant every punch-in, slump and
   * pull-back overwrote whatever the player had zoomed to. Keeping them apart
   * lets a cinematic dolly ride on top of the player's framing and hand it back
   * untouched afterwards.
   */
  private zoom = 1;
  private desiredZoom = 1;
  private cine = 1;
  private desiredCine = 1;
  private roll = 0;
  private desiredRoll = 0;

  private boardW = 0;
  private boardH = 0;
  private contentH = 1.6;
  private aspect = 0.46;
  private insets: SafeInsets = { top: 0.1, bottom: 0.26, side: 0.06 };

  private tweens: Tween[] = [];
  private introRunning = false;

  // last orientation the framing was solved for
  private fitAz = NaN;
  private fitPolar = NaN;
  private fitTarget = new THREE.Vector3(NaN, NaN, NaN);

  constructor(aspect = 0.46) {
    this.aspect = aspect;
    this.camera = new THREE.PerspectiveCamera(
      BATTLE_VIEW.camera.fov,
      aspect,
      BATTLE_VIEW.camera.near,
      BATTLE_VIEW.camera.far,
    );
    this.camera.position.set(0, 8, 12);
    this.apply();
  }

  // ── framing ───────────────────────────────────────────────────────────────

  setBoard(w: number, h: number, contentHeight = 1.6): void {
    this.boardW = w;
    this.boardH = h;
    this.contentH = contentHeight;
    this.home.set(0, 0, 0);
    this.desiredTarget.copy(this.home);
    this.target.copy(this.home);
    this.refit();
  }

  setInsets(insets: Partial<SafeInsets>): void {
    this.insets = { ...this.insets, ...insets };
    this.refit();
  }

  resize(aspect: number): void {
    if (!Number.isFinite(aspect) || aspect <= 0) return;
    this.aspect = aspect;
    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();
    this.refit();
  }

  /**
   * Bisect the smallest distance at which every board corner sits inside the
   * viewport's safe band, for the CURRENT orbit orientation and focus drift.
   * Re-solved whenever the rig moves, so orbiting to peek around an obstacle
   * eases the camera back instead of clipping the board.
   */
  private refit(): void {
    if (this.boardW <= 0 || this.boardH <= 0) return;
    const margin = TILE_PITCH * BATTLE_VIEW.camera.fitMargin;
    const halfX = (this.boardW * TILE_PITCH) / 2 + margin;
    const halfZ = (this.boardH * TILE_PITCH) / 2 + margin;
    const topY = this.contentH * BATTLE_VIEW.camera.fitContent;

    const tanV = Math.tan((this.camera.fov * Math.PI) / 360);
    const tanH = tanV * this.aspect;
    // The vertical band is ASYMMETRIC — a slim HUD on top, a tall dice tray
    // below — and `aimShift` already re-centres the camera on it, so the usable
    // half-extent is what the two insets leave between them: 1 - top - bottom.
    // Treating it as symmetric (1 - 2·max) double-counts the larger inset: with
    // a tray at 0.5 it collapses to the 0.18 floor and the board renders as a
    // postage stamp with the mechs too small to read. `side` IS symmetric, so
    // the horizontal limit keeps its doubling.
    const limY = Math.max(0.18, 1 - this.insets.top - this.insets.bottom);
    const limX = Math.max(0.18, 1 - 2 * this.insets.side);

    const sp = Math.sin(this.polar);
    _dir.set(Math.sin(this.azimuth) * sp, Math.cos(this.polar), Math.cos(this.azimuth) * sp);

    const fits = (d: number): boolean => {
      _eye.copy(this.target).addScaledVector(_dir, d);
      _fwd.copy(this.target).sub(_eye).normalize();
      _right.copy(_fwd).cross(WORLD_UP).normalize();
      _up.copy(_right).cross(_fwd).normalize();
      for (let i = 0; i < 8; i++) {
        _corner.set(i & 1 ? halfX : -halfX, i & 2 ? topY : 0, i & 4 ? halfZ : -halfZ);
        _rel.copy(_corner).sub(_eye);
        const z = _rel.dot(_fwd);
        if (z <= this.camera.near) return false;
        if (Math.abs(_rel.dot(_right)) > limX * tanH * z) return false;
        if (Math.abs(_rel.dot(_up)) > limY * tanV * z) return false;
      }
      return true;
    };

    let lo = 1;
    let hi = Math.max(BATTLE_VIEW.camera.distance, 4);
    let guard = 0;
    while (!fits(hi) && guard++ < 24) hi *= 1.5;
    for (let i = 0; i < 24; i++) {
      const mid = (lo + hi) / 2;
      if (fits(mid)) hi = mid;
      else lo = mid;
    }
    this.fitDistance = hi;

    // re-centre the board inside the asymmetric safe band (dice tray at bottom)
    const shift = (this.insets.bottom - this.insets.top) * hi * tanV;
    _eye.copy(this.target).addScaledVector(_dir, hi);
    _fwd.copy(this.target).sub(_eye).normalize();
    _right.copy(_fwd).cross(WORLD_UP).normalize();
    _up.copy(_right).cross(_fwd).normalize();
    this.aimShift.copy(_up).multiplyScalar(-shift);
  }

  // ── interaction ───────────────────────────────────────────────────────────

  /**
   * Orbit drag in CSS pixels.
   *
   * Azimuth is UNCLAMPED — the player can walk all the way around the board and
   * look at their line from the enemy's side. It was pinned to ±0.62 rad, which
   * is a 35° wobble, not a camera. Polar is still clamped, but to the full
   * useful range: near-overhead down to a grazing angle that never dips under
   * the board plane.
   */
  orbitBy(dxPx: number, dyPx: number): void {
    if (this.introRunning) return;
    this.desiredAzimuth -= dxPx * 0.0064;
    this.desiredPolar = THREE.MathUtils.clamp(
      this.desiredPolar + dyPx * 0.0045,
      BATTLE_VIEW.camera.minPolar,
      BATTLE_VIEW.camera.maxPolar,
    );
  }

  /**
   * Multiply the framing distance. `factor` < 1 moves in, > 1 moves out.
   *
   * Rides on top of the solved fit distance rather than replacing it, so the
   * zoom range means the same thing on a 6×6 board as on an 8×8 one.
   */
  zoomBy(factor: number): void {
    if (this.introRunning) return;
    if (!Number.isFinite(factor) || factor <= 0) return;
    this.desiredZoom = THREE.MathUtils.clamp(
      this.desiredZoom * factor,
      BATTLE_VIEW.camera.minZoom,
      BATTLE_VIEW.camera.maxZoom,
    );
  }

  /** True once the player has moved the camera off the default framing. */
  get isOffDefault(): boolean {
    return (
      Math.abs(this.desiredAzimuth) > 0.02 ||
      Math.abs(this.desiredPolar - BATTLE_VIEW.camera.polar) > 0.02 ||
      Math.abs(this.desiredZoom - 1) > 0.02
    );
  }

  /** Back to the solved play view: square on, default angle, no zoom. */
  recenter(): void {
    this.desiredAzimuth = 0;
    this.desiredPolar = BATTLE_VIEW.camera.polar;
    this.desiredZoom = 1;
    this.desiredTarget.copy(this.home);
  }

  /** Smooth focus drift onto the acting unit (tile coordinates). */
  focus(x: number, y: number): void {
    if (this.boardW <= 0) return;
    const wx = tileWorldX(x, this.boardW);
    const wz = tileWorldZ(y, this.boardH);
    // never drift far enough to push the board off-screen
    this.desiredTarget.set(
      THREE.MathUtils.clamp(wx * 0.34, -FOCUS_DRIFT, FOCUS_DRIFT),
      0,
      THREE.MathUtils.clamp(wz * 0.34, -FOCUS_DRIFT, FOCUS_DRIFT),
    );
  }

  clearFocus(): void {
    this.desiredTarget.copy(this.home);
  }

  /** Slight dolly-in while an attack resolves. */
  punchIn(amount = 0.1, holdMs = 260): Promise<void> {
    this.desiredCine = 1 - amount;
    return this.tween(holdMs, () => undefined).then(() => {
      this.desiredCine = 1;
    });
  }

  /** The 0-0-0 slump: the camera loses the will to hold itself up. */
  slump(amount: number): void {
    this.desiredPolar = THREE.MathUtils.clamp(
      BATTLE_VIEW.camera.polar + 0.42 * amount,
      BATTLE_VIEW.camera.minPolar,
      BATTLE_VIEW.camera.maxPolar,
    );
    this.desiredCine = 1 + 0.16 * amount;
    this.desiredRoll = 0.055 * amount;
  }

  pullBack(amount: number): void {
    this.desiredCine = 1 + amount;
  }

  // ── cinematics ────────────────────────────────────────────────────────────

  /** Battle-start sweep: a wide grazing orbit that settles into the play view. */
  intro(ms = 2400): Promise<void> {
    this.introRunning = true;
    const startAz = -0.95;
    const startPolar = BATTLE_VIEW.camera.polar + 0.62;
    const startScale = 2.05;
    this.azimuth = startAz;
    this.desiredAzimuth = startAz;
    this.polar = THREE.MathUtils.clamp(
      startPolar,
      BATTLE_VIEW.camera.minPolar,
      BATTLE_VIEW.camera.maxPolar,
    );
    this.desiredPolar = this.polar;
    this.zoom = 1;
    this.desiredZoom = 1;
    this.cine = startScale;
    this.desiredCine = startScale;
    this.apply();
    const openPolar = this.polar;
    return this.tween(ms, (k) => {
      const e = easeInOutCubic(k);
      const s = easeOutCubic(Math.min(1, k * 1.15));
      this.desiredAzimuth = startAz * (1 - e);
      this.azimuth = this.desiredAzimuth;
      this.desiredPolar = openPolar + (BATTLE_VIEW.camera.polar - openPolar) * e;
      this.polar = this.desiredPolar;
      this.desiredCine = startScale + (1 - startScale) * s;
      this.cine = this.desiredCine;
    }).then(() => {
      this.introRunning = false;
      this.recenter();
    });
  }

  private tween(ms: number, fn: (k: number) => void): Promise<void> {
    return new Promise<void>((resolve) => {
      this.tweens.push({ t: 0, d: Math.max(1, ms), fn, resolve });
    });
  }

  // ── frame ─────────────────────────────────────────────────────────────────

  update(dt: number): void {
    for (let i = this.tweens.length - 1; i >= 0; i--) {
      const tw = this.tweens[i];
      tw.t += dt * 1000;
      const k = Math.min(1, tw.t / tw.d);
      tw.fn(k);
      if (k >= 1) {
        this.tweens.splice(i, 1);
        tw.resolve();
      }
    }

    const kSlow = 1 - Math.exp(-dt * 4.2);
    const kFast = 1 - Math.exp(-dt * 7.5);
    this.azimuth += (this.desiredAzimuth - this.azimuth) * kFast;
    this.polar += (this.desiredPolar - this.polar) * kFast;
    this.zoom += (this.desiredZoom - this.zoom) * kFast;
    this.cine += (this.desiredCine - this.cine) * kSlow;
    this.roll += (this.desiredRoll - this.roll) * kSlow;
    this.target.lerp(this.desiredTarget, kSlow);

    // Azimuth is unclamped, so keep the numbers bounded during a long spin.
    // Current and desired shift by the same whole turn, leaving the easing
    // delta — and therefore the motion — completely untouched.
    if (this.azimuth > Math.PI || this.azimuth < -Math.PI) {
      const turns = Math.round(this.azimuth / (Math.PI * 2));
      this.azimuth -= turns * Math.PI * 2;
      this.desiredAzimuth -= turns * Math.PI * 2;
      this.fitAz = NaN; // force a re-solve at the wrapped orientation
    }

    // re-solve framing only when the rig has actually moved
    if (
      Math.abs(this.azimuth - this.fitAz) > 0.0015 ||
      Math.abs(this.polar - this.fitPolar) > 0.0015 ||
      this.target.distanceToSquared(this.fitTarget) > 1e-5
    ) {
      this.fitAz = this.azimuth;
      this.fitPolar = this.polar;
      this.fitTarget.copy(this.target);
      this.refit();
    }
    this.apply();
  }

  private apply(): void {
    const d = this.fitDistance * this.zoom * this.cine;
    const sp = Math.sin(this.polar);
    _dir.set(Math.sin(this.azimuth) * sp, Math.cos(this.polar), Math.cos(this.azimuth) * sp);
    _eye.copy(this.target).addScaledVector(_dir, d).add(this.aimShift);
    this.camera.position.copy(_eye);
    _look.copy(this.target).add(this.aimShift);
    this.camera.up.set(Math.sin(this.roll), Math.cos(this.roll), 0);
    this.camera.lookAt(_look);
    this.camera.updateMatrixWorld();
  }

  reset(): void {
    this.tweens.length = 0;
    this.introRunning = false;
    this.azimuth = 0;
    this.desiredAzimuth = 0;
    this.polar = BATTLE_VIEW.camera.polar;
    this.desiredPolar = this.polar;
    this.zoom = 1;
    this.desiredZoom = 1;
    this.cine = 1;
    this.desiredCine = 1;
    this.roll = 0;
    this.desiredRoll = 0;
    this.target.copy(this.home);
    this.desiredTarget.copy(this.home);
    this.apply();
  }
}
