/**
 * TERRA BELLUM — procedural battle chassis (GDD §5, §12.3).
 *
 * Every unit type is assembled from primitives into a distinct, readable
 * silhouette — no external models. Parts are merged per material role so a
 * full 16-unit board costs ~4 draw calls per mech, and every unit's HUD is
 * drawn into ONE shared canvas atlas rendered as a single instanced quad mesh.
 */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { BattleSide, BattleState, BattleUnit, UnitType } from '../../game/types';
import { UNITS } from '../../config/units';
import { BATTLE_VIEW, PALETTE } from '../../config/visual';
import {
  BattleBoard,
  HOVER_H,
  disposeHull,
  makeHullMaterial,
  tileHash,
  tileWorldX,
  tileWorldZ,
} from './tiles';

type Role = 'plate' | 'trim' | 'glass';
const ROLES: Role[] = ['plate', 'trim', 'glass'];

const cssHex = (n: number): string => '#' + (n >>> 0).toString(16).padStart(6, '0');

interface XForm {
  p?: [number, number, number];
  r?: [number, number, number];
  s?: [number, number, number];
}

function xf(g: THREE.BufferGeometry, t?: XForm): THREE.BufferGeometry {
  if (t?.s) g.scale(t.s[0], t.s[1], t.s[2]);
  if (t?.r) {
    if (t.r[0]) g.rotateX(t.r[0]);
    if (t.r[1]) g.rotateY(t.r[1]);
    if (t.r[2]) g.rotateZ(t.r[2]);
  }
  if (t?.p) g.translate(t.p[0], t.p[1], t.p[2]);
  return g;
}

const box = (w: number, h: number, d: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.BoxGeometry(w, h, d), t);
const cyl = (rt: number, rb: number, h: number, seg: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.CylinderGeometry(rt, rb, h, seg, 1), t);
const cone = (r: number, h: number, seg: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.ConeGeometry(r, h, seg, 1), t);
const sphere = (r: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.SphereGeometry(r, 10, 7), t);
const torus = (r: number, tube: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.TorusGeometry(r, tube, 4, 14), t);
const octa = (r: number, t?: XForm): THREE.BufferGeometry =>
  xf(new THREE.OctahedronGeometry(r, 0), t);

// ─────────────────────────────────────────────────────────────────────────────
// Rig — collects primitives per role and per section, then bakes merged buffers
// ─────────────────────────────────────────────────────────────────────────────

type Section = 'body' | 'head';

class Rig {
  private bins: Record<Section, Record<Role, THREE.BufferGeometry[]>> = {
    body: { plate: [], trim: [], glass: [] },
    head: { plate: [], trim: [], glass: [] },
  };
  section: Section = 'body';
  headPivot: THREE.Vector3 | null = null;
  height = 0.6;
  hover = 0;

  add(role: Role, g: THREE.BufferGeometry): void {
    this.bins[this.section][role].push(g);
  }

  bake(): BakedMech {
    const out: BakedMech = { body: {}, head: {}, headPivot: this.headPivot, height: this.height, hover: this.hover };
    for (const section of ['body', 'head'] as Section[]) {
      for (const role of ROLES) {
        const parts = this.bins[section][role];
        if (!parts.length) continue;
        if (section === 'head' && this.headPivot) {
          const p = this.headPivot;
          for (const g of parts) g.translate(-p.x, -p.y, -p.z);
        }
        const flat: THREE.BufferGeometry[] = [];
        for (const g of parts) flat.push(g.index ? g.toNonIndexed() : g);
        const merged = mergeGeometries(flat, false);
        for (let i = 0; i < flat.length; i++) {
          if (flat[i] !== parts[i]) flat[i].dispose();
          parts[i].dispose();
        }
        merged.computeVertexNormals();
        out[section][role] = merged;
      }
    }
    return out;
  }
}

interface BakedMech {
  body: Partial<Record<Role, THREE.BufferGeometry>>;
  head: Partial<Record<Role, THREE.BufferGeometry>>;
  headPivot: THREE.Vector3 | null;
  height: number;
  hover: number;
}

