  r.add('plate', cyl(0.24, 0.27, 0.15, 6, { r: [0, Math.PI / 6, 0], p: [0, 0.47, 0] }));
  r.add('trim', torus(0.25, 0.014, { r: [Math.PI / 2, 0, 0], p: [0, 0.51, 0] }));
  r.add('plate', box(0.3, 0.03, 0.03, { p: [0, 0.535, 0.15] }));
  r.add('trim', box(0.24, 0.014, 0.014, { p: [0, 0.535, 0.166] }));

  r.headPivot = new THREE.Vector3(0, 0.545, 0);
  r.section = 'head';
  r.add('plate', cyl(0.125, 0.15, 0.14, 8, { p: [0, 0.615, 0] }));
