/**
 * TERRA BELLUM — pre-battle staging (GDD §6, §7.1).
 *
 * Three consecutive jobs, each with its own face:
 *
 *  1. SIDE PICK      — an L1+ fort defender claims the south or north line.
 *  2. OBSTACLE PLACE — an L2 fort defender seals 2–4 neutral tiles.
 *  3. DEPLOY         — units are dragged out of the roster onto the back two
 *                      rows, with AUTO-DEPLOY and READY.
 *
 * The board itself is a 3D scene, so the panel carries a DOM mini-board: a real
 * drag target on a phone, and a legend for every twist tile the template ships.
 * Tapping tiles on the 3D board drives exactly the same handlers.
 */
import { BATTLE, FORTS, FORT_RULES, TERRAIN_META } from '../../config/balance';
import { UNITS } from '../../config/units';
import type {
  BattleSide,
  BattleState,
  BattleUnit,
  TileKind,
  UnitId,
} from '../../game/types';
import { deployRowsFor, tileKey } from '../../game/battle/rules';
import { obstacleSpots } from '../../game/battle/engine';
import { clear, el, haptic, svg as svgEl } from '../dom';
import { unitAccent, unitSilhouette } from '../components';
import { boardBlurbOf, boardTwistOf } from './cinematics';

export type DeployMode = 'side_pick' | 'obstacle_place' | 'deploy' | 'wait';

const TILE_GLYPH: Record<TileKind, string> = {
  floor: '',
  obstacle: '▧',
  rough: '≋',
  cover: '⬖',
  hazard: '☣',
  teleport: '◉',
  destructible: '▤',
  elevation: '▲',
  unstable: '⌗',
};

const TILE_NAME: Record<TileKind, string> = {
  floor: 'DECK',
  obstacle: 'OBSTACLE',
  rough: 'ROUGH',
  cover: 'COVER',
  hazard: 'VENT',
  teleport: 'PHASE PAD',
  destructible: 'WALL',
  elevation: 'HIGH GROUND',
  unstable: 'UNSTABLE',
};

function tileRule(kind: TileKind): string {
  switch (kind) {
    case 'obstacle':
      return 'Blocks movement and line of sight.';
    case 'rough':
      return 'Tracked hulls may not end a move here.';
    case 'cover':
      return `+${BATTLE.coverDefense} defense for infantry.`;
    case 'hazard':
      return `${BATTLE.hazardDamage} damage to anything standing here at turn end.`;
    case 'teleport':
      return 'Paired. Entering one relocates you to its partner.';
    case 'destructible':
      return `${BATTLE.wallHp} HP wall. Blocks sight until it is shot down.`;
    case 'elevation':
      return `+${BATTLE.elevationRange} range while occupied.`;
    case 'unstable':
      return `Collapses into an obstacle after ${BATTLE.unstableCrossings} crossings.`;
    case 'floor':
      return 'Open deck plating.';
    default: {
      const never: never = kind;
      return String(never);
    }
  }
}

export interface DeployPanelState {
  mode: DeployMode;
  battle: BattleState;
  mySide: BattleSide;
  /** Local, uncommitted layout: unit id → tile. */
  placements: Map<UnitId, { x: number; y: number }>;
  /** Roster chassis picked up for the tap-then-tap flow. */
  held: UnitId | null;
  busy: boolean;
  waitTitle: string;
  waitDetail: string;
}

export interface DeployPanelOpts {
  onPickSide(bottom: BattleSide): void;
  onPlaceObstacle(x: number, y: number): void;
  /** Leave the obstacle step with barricades still in hand. */
  onFinishObstacles(): void;
  /** A chassis was dropped (or tapped) onto a tile. */
  onPlaceUnit(unitId: UnitId, x: number, y: number): void;
  onHold(unitId: UnitId | null): void;
  onAutoDeploy(): void;
  onReady(): void;
}

export class DeployPanel {
  readonly el: HTMLElement;

  private body: HTMLElement;
  private state: DeployPanelState | null = null;
  private ghost: HTMLElement | null = null;
  private dragUnit: UnitId | null = null;
  private dragging = false;
  private dragStart = { x: 0, y: 0 };
  private pointerId = -1;
  private lastKey = '';

  constructor(private opts: DeployPanelOpts) {
    this.body = el('div', { class: 'dep__body' });
    this.el = el(
      'div',
      { class: 'dep' },
      el('div', { class: 'dep__glow', aria: { hidden: 'true' } }),
      this.body,
    );
  }

  sync(next: DeployPanelState): void {
    const s = next;
    this.state = s;
    const layout = [...s.placements.entries()]
      .map(([id, p]) => `${id}@${p.x},${p.y}`)
      .sort()
      .join(';');
    const key = [
      s.mode,
      s.battle.id,
      s.battle.phase,
      s.battle.bottomSide,
      s.battle.obstaclesToPlace,
      s.mySide,
      s.held ?? '-',
      s.busy ? 1 : 0,
      s.waitTitle,
      s.waitDetail,
      s.battle.units.filter((u) => u.alive).length,
      layout,
    ].join('|');
    if (key === this.lastKey) return;
    this.lastKey = key;

    this.el.classList.toggle('is-hidden', false);
    clear(this.body);

    switch (s.mode) {
      case 'side_pick':
        this.renderSidePick(s);
        return;
      case 'obstacle_place':
        this.renderObstacles(s);
        return;
      case 'deploy':
        this.renderDeploy(s);
        return;
      case 'wait':
        this.renderWait(s);
        return;
      default: {
        const never: never = s.mode;
        throw new Error(`unhandled deploy mode ${String(never)}`);
      }
    }
  }

  dispose(): void {
    this.killGhost();
    clear(this.body);
  }

  // ── shared pieces ─────────────────────────────────────────────────────────

  private fortNotes(b: BattleState): HTMLElement | null {
    if (b.fortLevel <= 0) return null;
    const list = el('div', { class: 'dep__forts' });
    list.appendChild(
      el('div', { class: 'dep__forts-head mono', text: `DEFENDER FORTIFICATION — LEVEL ${b.fortLevel}` }),
    );
    for (const lvl of [1, 2, 3] as const) {
      if (b.fortLevel < lvl) continue;
      const spec = FORTS[lvl];
      list.appendChild(
        el(
          'div',
          { class: 'dep__fort' },
          el('span', { class: 'dep__fort-l mono', text: `L${lvl}` }),
          el('span', { class: 'dep__fort-n display', text: spec.label }),
          el('span', { class: 'dep__fort-e', text: spec.battleEffect }),
        ),
      );
    }
    if (b.fortLevel >= 3) {
      list.appendChild(
        el('div', {
          class: 'dep__fort-note',
          text: `Every defending chassis carries +${FORT_RULES.defenderHpBonus} HP into this engagement.`,
        }),
      );
    }
    return list;
  }

  private boardBrief(b: BattleState): HTMLElement {
    const meta = TERRAIN_META[b.terrain];
    return el(
      'div',
      { class: 'dep__brief' },
      el('div', { class: 'dep__brief-name display', text: b.boardName }),
      el('div', { class: 'dep__brief-twist', text: boardTwistOf(b.boardId) }),
      el('div', { class: 'dep__brief-blurb', text: boardBlurbOf(b.boardId) }),
      el('div', {
        class: 'dep__brief-meta mono',
        text: `${b.w}×${b.h} · ${meta.label} · HEX ${b.hexId}`,
      }),
    );
  }

  private legend(b: BattleState): HTMLElement | null {
    const kinds = new Set<TileKind>();
    for (const row of b.grid) {
      for (const t of row) {
        if (t.kind !== 'floor') kinds.add(t.kind);
      }
    }
    if (kinds.size === 0) return null;
    const wrap = el('div', { class: 'dep__legend' });
    for (const k of kinds) {
      wrap.appendChild(
        el(
          'div',
          { class: `dep__leg dep__leg--${k}` },
          el('span', { class: 'dep__leg-g', text: TILE_GLYPH[k] || '·' }),
          el(
            'span',
            { class: 'dep__leg-t' },
            el('b', { text: TILE_NAME[k] }),
            el('span', { text: ` ${tileRule(k)}` }),
          ),
        ),
      );
    }
    return wrap;
  }

  /**
   * DOM mini-board. `interactive` decides which cells accept a tap, and the
   * unit overlay is drawn from the local placement map so the layout the player
   * is editing is always the layout they see.
   */
  private miniBoard(
    s: DeployPanelState,
    opts: {
      unitsAt: Map<string, BattleUnit>;
      validCell?: (x: number, y: number) => boolean;
      onCell?: (x: number, y: number) => void;
      showZones: boolean;
      draggable: boolean;
    },
  ): HTMLElement {
    const b = s.battle;
    const myRows = new Set(deployRowsFor(b, s.mySide));
    const foeRows = new Set(deployRowsFor(b, s.mySide === 'attacker' ? 'defender' : 'attacker'));

    const grid = el('div', {
      class: 'mboard',
      style: `--cols:${b.w};--rows:${b.h}`,
    });

    for (let y = 0; y < b.h; y++) {
      for (let x = 0; x < b.w; x++) {
        const tile = b.grid[y][x];
        const valid = opts.validCell ? opts.validCell(x, y) : false;
        const classes = ['mcell', `mcell--${tile.kind}`];
        if (opts.showZones && myRows.has(y)) classes.push('is-mine');
        if (opts.showZones && foeRows.has(y)) classes.push('is-foe');
        if (valid) classes.push('is-valid');
        if (tile.kind === 'unstable' && tile.collapsed) classes.push('is-collapsed');
        if (tile.placed) classes.push('is-placed');

        const cell = el(
          opts.onCell ? 'button' : 'div',
          {
            class: classes.join(' '),
            data: { cell: `${x},${y}` },
            attrs: opts.onCell ? { type: 'button' } : undefined,
            aria: { label: `tile ${x} ${y} ${TILE_NAME[tile.kind]}` },
          },
        );
        const glyph = TILE_GLYPH[tile.kind];
        if (glyph) cell.appendChild(el('span', { class: 'mcell__g', text: glyph }));

        const occupant = opts.unitsAt.get(`${x},${y}`);
        if (occupant) {
          const token = el('span', {
            class: `mcell__u ${occupant.side === s.mySide ? 'is-me' : 'is-foe'}`,
            style: `--accent:${unitAccent(occupant.type)}`,
          });
          token.appendChild(svgEl(unitSilhouette(occupant.type)));
          if (s.held === occupant.id) token.classList.add('is-held');
          cell.appendChild(token);
        }

        if (opts.onCell) {
          const handler = opts.onCell;
          cell.addEventListener('click', () => {
            haptic(8);
            handler(x, y);
          });
        }
        grid.appendChild(cell);
      }
    }

    const frame = el(
      'div',
      { class: `mboard-frame${opts.draggable ? ' is-drop' : ''}` },
      el('div', { class: 'mboard-frame__label mono', text: 'TACTICAL PREVIEW' }),
      grid,
      el(
        'div',
        { class: 'mboard-frame__axis mono' },
        el('span', { text: opts.showZones ? 'YOUR LINE' : `${b.w}×${b.h}` }),
        el('span', { text: 'HOSTILE LINE' }),
      ),
    );
    return frame;
  }

  private unitsAtOf(s: DeployPanelState, useLocal: boolean): Map<string, BattleUnit> {
    const out = new Map<string, BattleUnit>();
    for (const u of s.battle.units) {
      if (!u.alive) continue;
      let x = u.x;
      let y = u.y;
      if (useLocal && u.side === s.mySide) {
        const p = s.placements.get(u.id);
        if (!p) continue;
        x = p.x;
        y = p.y;
      }
      if (x < 0 || y < 0) continue;
      out.set(`${x},${y}`, u);
    }
    return out;
  }

  // ── phase 1: side pick ────────────────────────────────────────────────────

  private renderSidePick(s: DeployPanelState): void {
    const b = s.battle;
    const head = el(
      'div',
      { class: 'dep__head' },
      el('div', { class: 'dep__step mono', text: 'STEP 1 OF ' + (b.obstaclesToPlace > 0 ? '3' : '2') }),
      el('div', { class: 'dep__title display', text: 'CLAIM YOUR GROUND' }),
      el('div', {
        class: 'dep__lede',
        text: 'Your fortification lets you choose which end of the board you hold. Pick the line that suits your chassis, not the one that looks safe.',
      }),
    );
    this.body.appendChild(head);
    this.body.appendChild(this.boardBrief(b));

    const options = el('div', { class: 'dep__sides' });
    const choices: { bottom: BattleSide; label: string; sub: string }[] = [
      { bottom: s.mySide, label: 'SOUTH LINE', sub: 'You deploy on the near rows, closest to the camera.' },
      {
        bottom: s.mySide === 'attacker' ? 'defender' : 'attacker',
        label: 'NORTH LINE',
        sub: 'You deploy on the far rows, across the board.',
      },
    ];

    for (const c of choices) {
      const mineBottom = c.bottom === s.mySide;
      const card = el('button', {
        class: `sidecard${b.bottomSide === c.bottom ? ' is-current' : ''}`,
        attrs: { type: 'button', disabled: s.busy },
      });
      card.appendChild(el('span', { class: 'sidecard__label display', text: c.label }));

      const dia = el('span', { class: 'sidecard__dia', aria: { hidden: 'true' } });
      for (let i = 0; i < 6; i++) {
        const band = i < 2 ? 'top' : i > 3 ? 'bottom' : 'mid';
        const isMine = (band === 'bottom' && mineBottom) || (band === 'top' && !mineBottom);
        const isFoe = band !== 'mid' && !isMine;
        dia.appendChild(
          el('i', { class: isMine ? 'is-me' : isFoe ? 'is-foe' : '' }),
        );
      }
      card.appendChild(dia);
      card.appendChild(el('span', { class: 'sidecard__sub', text: c.sub }));
      card.addEventListener('click', () => {
        if (s.busy) return;
        haptic([10, 24, 10]);
        this.opts.onPickSide(c.bottom);
      });
      options.appendChild(card);
    }
    this.body.appendChild(options);

    const forts = this.fortNotes(b);
    if (forts) this.body.appendChild(forts);
    const legend = this.legend(b);
    if (legend) this.body.appendChild(legend);
  }

  // ── phase 2: obstacles ────────────────────────────────────────────────────

  private renderObstacles(s: DeployPanelState): void {
    const b = s.battle;
    const left = b.obstaclesToPlace;

    this.body.appendChild(
      el(
        'div',
        { class: 'dep__head' },
        el('div', { class: 'dep__step mono', text: 'STEP 2 OF 3' }),
        el('div', { class: 'dep__title display', text: 'SEAL THE APPROACH' }),
        el('div', {
          class: 'dep__lede',
          text: 'Your Bastion ships prefabricated barricades. Drop them on open neutral deck — never inside a deployment band, and never in a pattern that cuts the board in half.',
        }),
      ),
    );

    const counter = el(
      'div',
      { class: 'dep__counter' },
      el('span', { class: 'dep__counter-n display tnum', text: String(left) }),
      el('span', { class: 'dep__counter-k', text: left === 1 ? 'BARRICADE REMAINING' : 'BARRICADES REMAINING' }),
    );
    const pips = el('span', { class: 'dep__counter-pips' });
    for (let i = 0; i < FORT_RULES.bonusObstaclesMax; i++) {
      pips.appendChild(el('i', { class: i < left ? 'is-on' : '' }));
    }
    counter.appendChild(pips);
    this.body.appendChild(counter);

    // The engine's own legality test, so a highlighted tile is always a tile
    // the engine will accept — including the "would this cut the board in half"
    // rule, which the panel has no business re-deriving.
    const spots = obstacleSpots(b);
    const legal = new Set(spots.map((p) => tileKey(p.x, p.y)));
    const validCell = (x: number, y: number): boolean => legal.has(tileKey(x, y));

    this.body.appendChild(
      this.miniBoard(s, {
        unitsAt: this.unitsAtOf(s, false),
        validCell,
        onCell: (x, y) => {
          if (s.busy) return;
          if (!validCell(x, y)) {
            haptic([30, 20, 30]);
            return;
          }
          this.opts.onPlaceObstacle(x, y);
        },
        showZones: true,
        draggable: false,
      }),
    );

    // Always reachable. Some boards have no legal barricade tile at all, and
    // sealing one lane can be what makes the rest illegal, so the defender must
    // be able to walk away from an allowance they cannot spend.
    const stuck = spots.length === 0;
    const actions = el('div', { class: 'dep__actions dep__actions--single' });
    const done = el(
      'button',
      { class: 'dep-btn dep-btn--go', attrs: { type: 'button', disabled: s.busy } },
      el('span', { class: 'display', text: stuck ? 'NO LANE TO SEAL' : 'BARRICADES SET' }),
      el('span', {
        class: 'dep-btn__sub mono',
        text: stuck
          ? 'THIS BOARD HAS NO LEGAL POSITION — CONTINUE'
          : `CONTINUE TO DEPLOYMENT — ${left} IN HAND`,
      }),
    );
    done.addEventListener('click', () => {
      if (s.busy) return;
      haptic([8, 22, 8]);
      this.opts.onFinishObstacles();
    });
    actions.appendChild(done);
    this.body.appendChild(actions);

    const legend = this.legend(b);
    if (legend) this.body.appendChild(legend);
  }

  // ── phase 3: deployment ───────────────────────────────────────────────────

  private renderDeploy(s: DeployPanelState): void {
    const b = s.battle;
    const roster = b.units.filter((u) => u.side === s.mySide && u.alive);
    const placedCount = roster.filter((u) => s.placements.has(u.id)).length;
    const ready = placedCount === roster.length;

    this.body.appendChild(
      el(
        'div',
        { class: 'dep__head' },
        el('div', {
          class: 'dep__step mono',
          text: b.fortLevel >= 2 ? 'STEP 3 OF 3' : b.fortLevel >= 1 ? 'STEP 2 OF 2' : 'DEPLOYMENT',
        }),
        el('div', { class: 'dep__title display', text: 'SET THE LINE' }),
        el('div', {
          class: 'dep__lede',
          text: `Drag a chassis onto your back ${BATTLE.deployRows} rows, or tap it and then tap a tile. Armour forward, guns behind it.`,
        }),
      ),
    );

    const unitsAt = this.unitsAtOf(s, true);
    const zoneRows = new Set(deployRowsFor(b, s.mySide));
    const validCell = (x: number, y: number): boolean => {
      if (!zoneRows.has(y)) return false;
      const t = b.grid[y][x];
      if (t.kind === 'obstacle') return false;
      if (t.kind === 'destructible' && (t.hp ?? 0) > 0) return false;
      if (t.kind === 'unstable' && t.collapsed) return false;
      return true;
    };

    this.body.appendChild(
      this.miniBoard(s, {
        unitsAt,
        validCell: s.held ? validCell : undefined,
        onCell: (x, y) => {
          if (s.busy) return;
          const held = s.held;
          if (!held) {
            const occupant = unitsAt.get(`${x},${y}`);
            if (occupant && occupant.side === s.mySide) this.opts.onHold(occupant.id);
            return;
          }
          if (!validCell(x, y)) {
            haptic([30, 20, 30]);
            return;
          }
          this.opts.onPlaceUnit(held, x, y);
        },
        showZones: true,
        draggable: true,
      }),
    );

    // roster strip
    const strip = el('div', { class: 'dep__roster scroll-x no-scrollbar' });
    for (const u of roster) {
      const placed = s.placements.get(u.id);
      const chip = el('div', {
        class: `dchip${s.held === u.id ? ' is-held' : ''}${placed ? ' is-placed' : ' is-loose'}`,
        style: `--accent:${unitAccent(u.type)}`,
        data: { unitId: u.id },
        attrs: { role: 'button', tabindex: 0 },
        aria: { label: `${UNITS[u.type].name}${placed ? ` at ${placed.x} ${placed.y}` : ' unplaced'}` },
      });
      const art = el('span', { class: 'dchip__art' });
      art.appendChild(svgEl(unitSilhouette(u.type)));
      chip.appendChild(art);
      chip.appendChild(el('span', { class: 'dchip__code', text: UNITS[u.type].codename }));
      chip.appendChild(
        el('span', {
          class: 'dchip__pos mono tnum',
          text: placed ? `${placed.x}·${placed.y}` : 'UNPLACED',
        }),
      );
      chip.appendChild(
        el('span', {
          class: 'dchip__hp mono tnum',
          text: `${u.hp}/${u.maxHp}`,
        }),
      );
      this.attachChipDrag(chip, u.id);
      strip.appendChild(chip);
    }
    this.body.appendChild(
      el('div', { class: 'dep__roster-head mono', text: `ROSTER — ${placedCount}/${roster.length} PLACED` }),
    );
    this.body.appendChild(strip);

    const actions = el('div', { class: 'dep__actions' });
    const auto = el(
      'button',
      { class: 'dep-btn', attrs: { type: 'button', disabled: s.busy } },
      el('span', { class: 'display', text: 'AUTO-DEPLOY' }),
      el('span', { class: 'dep-btn__sub mono', text: 'ARMOUR FORWARD, ARTILLERY BEHIND' }),
    );
    auto.addEventListener('click', () => {
      if (s.busy) return;
      haptic([8, 22, 8]);
      this.opts.onAutoDeploy();
    });

    const go = el(
      'button',
      {
        class: 'dep-btn dep-btn--go',
        attrs: { type: 'button', disabled: s.busy || !ready },
      },
      el('span', { class: 'display', text: 'READY' }),
      el('span', {
        class: 'dep-btn__sub mono',
        text: ready ? 'LOCK THE LINE AND BEGIN' : `${roster.length - placedCount} CHASSIS STILL LOOSE`,
      }),
    );
    go.addEventListener('click', () => {
      if (s.busy || !ready) return;
      haptic([12, 30, 12]);
      this.opts.onReady();
    });

    actions.appendChild(auto);
    actions.appendChild(go);
    this.body.appendChild(actions);

    const forts = this.fortNotes(b);
    if (forts) this.body.appendChild(forts);
    const legend = this.legend(b);
    if (legend) this.body.appendChild(legend);
  }

  // ── waiting on the other commander ────────────────────────────────────────

  private renderWait(s: DeployPanelState): void {
    this.body.appendChild(
      el(
        'div',
        { class: 'dep__wait' },
        el('div', { class: 'dep__wait-ring', aria: { hidden: 'true' } }, el('i'), el('i'), el('i')),
        el('div', { class: 'dep__title display', text: s.waitTitle }),
        el('div', { class: 'dep__lede', text: s.waitDetail }),
      ),
    );
    this.body.appendChild(this.boardBrief(s.battle));
    this.body.appendChild(
      this.miniBoard(s, {
        unitsAt: this.unitsAtOf(s, false),
        showZones: true,
        draggable: false,
      }),
    );
    const legend = this.legend(s.battle);
    if (legend) this.body.appendChild(legend);
  }

  // ── roster drag ───────────────────────────────────────────────────────────

  private attachChipDrag(chip: HTMLElement, unitId: UnitId): void {
    chip.addEventListener('pointerdown', (ev: PointerEvent) => {
      if (this.pointerId !== -1) return;
      if (this.state?.busy) return;
      ev.preventDefault();
      this.pointerId = ev.pointerId;
      this.dragUnit = unitId;
      this.dragging = false;
      this.dragStart = { x: ev.clientX, y: ev.clientY };
      try {
        chip.setPointerCapture(ev.pointerId);
      } catch {
        /* ignore */
      }
    });

    chip.addEventListener('pointermove', (ev: PointerEvent) => {
      if (ev.pointerId !== this.pointerId || this.dragUnit === null) return;
      const dist = Math.hypot(ev.clientX - this.dragStart.x, ev.clientY - this.dragStart.y);
      if (!this.dragging && dist > 8) {
        this.dragging = true;
        this.beginGhost(this.dragUnit, ev.clientX, ev.clientY);
        this.opts.onHold(this.dragUnit);
      }
      if (this.dragging) this.moveGhost(ev.clientX, ev.clientY);
    });

    const end = (ev: PointerEvent): void => {
      if (ev.pointerId !== this.pointerId) return;
      try {
        chip.releasePointerCapture(ev.pointerId);
      } catch {
        /* ignore */
      }
      this.pointerId = -1;
      const unit = this.dragUnit;
      this.dragUnit = null;
      if (unit === null) return;

      if (this.dragging) {
        this.dragging = false;
        this.killGhost();
        const cell = this.cellAt(ev.clientX, ev.clientY);
        if (cell) this.opts.onPlaceUnit(unit, cell.x, cell.y);
        return;
      }
      const held = this.state?.held ?? null;
      this.opts.onHold(held === unit ? null : unit);
    };

    chip.addEventListener('pointerup', end);
    chip.addEventListener('pointercancel', (ev: PointerEvent) => {
      if (ev.pointerId !== this.pointerId) return;
      this.pointerId = -1;
      this.dragUnit = null;
      this.dragging = false;
      this.killGhost();
    });

    chip.addEventListener('keydown', (ev: KeyboardEvent) => {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      ev.preventDefault();
      const held = this.state?.held ?? null;
      this.opts.onHold(held === unitId ? null : unitId);
    });
  }

  private cellAt(x: number, y: number): { x: number; y: number } | null {
    const node = document.elementFromPoint(x, y);
    const cell = node instanceof Element ? node.closest('[data-cell]') : null;
    if (!(cell instanceof HTMLElement)) return null;
    const raw = cell.dataset.cell;
    if (!raw) return null;
    const [cx, cy] = raw.split(',').map((n) => Number.parseInt(n, 10));
    if (!Number.isInteger(cx) || !Number.isInteger(cy)) return null;
    return { x: cx, y: cy };
  }

  private beginGhost(unitId: UnitId, x: number, y: number): void {
    const unit = this.state?.battle.units.find((u) => u.id === unitId);
    if (!unit) return;
    const ghost = el('div', {
      class: 'deploy-ghost',
      style: `--accent:${unitAccent(unit.type)}`,
    });
    ghost.appendChild(svgEl(unitSilhouette(unit.type)));
    document.body.appendChild(ghost);
    this.ghost = ghost;
    this.moveGhost(x, y);
    haptic(8);
  }

  private moveGhost(x: number, y: number): void {
    if (!this.ghost) return;
    this.ghost.style.transform = `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;
  }

  private killGhost(): void {
    if (!this.ghost) return;
    this.ghost.remove();
    this.ghost = null;
  }
}
