/**
 * TERRA BELLUM — Battle scene (Three.js scene B, GDD §7 / §12.3).
 *
 * The tactical board floats on a dark orbital platform over the planet surface
 * far below: light shafts, drifting embers, a holographic sensor grid running
 * off past the board edge, and terrain-tinted ambient colour taken from
 * TERRAIN_META for the contested hex.
 *
 * This class owns the Stage, the camera rig, the board, the mechs and the FX
 * pools, and exposes the whole battle layer as five methods to the UI.
 */
import * as THREE from 'three';
import type { BattleEvent, BattleSide, BattleState, Terrain } from '../../game/types';
import type { ViewState } from '../../game/store';
import { TERRAIN_META } from '../../config/balance';
import { BATTLE_VIEW, FX, PALETTE } from '../../config/visual';
import { Stage } from '../core/stage';
import { makeGlowSpriteMaterial, makeTokenMaterial } from '../core/materials';
import { InstancedBatch, armyChevronGeometry, billboardQuadGeometry } from '../core/geometry';
import {
  BattleBoard,
  PLATE_H,
  TILE_PITCH,
  setHullEnvironment,
  updateHulls,
} from './tiles';
import { MechInstances, type MechView } from './mechs';
import { BattleFx, type FxHost } from './fx';
import { BattleCamera, type SafeInsets } from './battleCamera';

type TapHandler = (x: number, y: number) => void;
type UnitHandler = (unitId: string) => void;

export interface BattleHighlights {
  moves: { x: number; y: number }[];
  attacks: { x: number; y: number }[];
  selected?: { x: number; y: number };
  path?: { x: number; y: number }[];
}

// ─────────────────────────────────────────────────────────────────────────────
// Dressing shaders
// ─────────────────────────────────────────────────────────────────────────────

const STAR_VERT = /* glsl */ `
attribute float aSize;
attribute float aTwinkle;
uniform float uTime;
uniform float uScale;
varying float vA;
void main() {
  vA = 0.55 + 0.45 * sin(uTime * 0.9 + aTwinkle * 6.2831);
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale / max(1.0, -mv.z);
}
`;

const STAR_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform vec3 uColor;
uniform float uDrain;
varying float vA;
void main() {
  vec2 p = gl_PointCoord - 0.5;
  float a = clamp(1.0 - length(p) * 2.0, 0.0, 1.0);
  a = pow(a, 2.2) * vA;
  if (a < 0.01) discard;
  vec3 c = uColor;
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3(lum), uDrain);
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const PLANET_VERT = /* glsl */ `
varying vec2 vUv;
varying vec3 vW;
void main() {
  vUv = uv;
  vec4 wp = modelMatrix * vec4(position, 1.0);
  vW = wp.xyz;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const PLANET_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
uniform vec3 uColor;
uniform vec3 uAccent;
varying vec2 vUv;
varying vec3 vW;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p); vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0)), f.x), f.y);
}
float fbm(vec2 p) {
  float v = 0.0; float a = 0.5;
  for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; }
  return v;
}

void main() {
  vec2 uv = (vUv - 0.5) * 2.0;
  float r = length(uv);
  if (r > 1.0) discard;
  vec2 p = uv * 3.4;
  float land = fbm(p + 12.0);
  float craters = smoothstep(0.44, 0.62, fbm(p * 2.6 - 4.0));
  float bands = 0.5 + 0.5 * sin(p.y * 1.7 + fbm(p) * 3.0 + uTime * 0.015);

  vec3 col = uColor * (0.35 + land * 0.7);
  col = mix(col, uColor * 0.42, craters * 0.55);
  col += uAccent * bands * 0.06;
  // city lights on the dark side
  float lights = step(0.965, hash(floor(p * 26.0)));
  col += uAccent * lights * 0.5 * smoothstep(0.25, 0.9, r);
  // terminator + limb haze
  float term = smoothstep(-0.2, 0.85, uv.x * 0.7 + uv.y * 0.4);
  col *= mix(0.14, 1.0, term);
  col += uAccent * pow(smoothstep(0.72, 1.0, r), 2.4) * 0.55;
  float edge = 1.0 - smoothstep(0.96, 1.0, r);

  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, vec3(lum) * 0.8, uDrain);
  gl_FragColor = vec4(col, edge);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const SHAFT_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const SHAFT_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
uniform vec3 uColor;
uniform float uPhase;
varying vec2 vUv;
void main() {
  float down = 1.0 - vUv.y;
  float edge = 1.0 - abs(vUv.x - 0.5) * 2.0;
  float shimmer = 0.72 + 0.28 * sin(vUv.y * 9.0 - uTime * 0.9 + uPhase);
  float a = pow(down, 1.7) * pow(clamp(edge, 0.0, 1.0), 0.9) * 0.2 * shimmer;
  if (a < 0.004) discard;
  vec3 c = uColor;
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3(lum) * 0.8, uDrain);
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const GRID_VERT = /* glsl */ `
attribute float aFade;
varying float vF;
void main() {
  vF = aFade;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const GRID_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform vec3 uColor;
uniform float uTime;
uniform float uDrain;
varying float vF;
void main() {
  float pulse = 0.7 + 0.3 * sin(uTime * 0.8);
  float a = vF * 0.5 * pulse;
  if (a < 0.004) discard;
  vec3 c = uColor;
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3(lum) * 0.8, uDrain);
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

// ─────────────────────────────────────────────────────────────────────────────

const _ndc = new THREE.Vector2();
const _colorA = new THREE.Color();
const _colorB = new THREE.Color();

export class BattleScene {
  private container: HTMLElement;
  private stage: Stage;
  private scene = new THREE.Scene();
  private cam: BattleCamera;
  private board: BattleBoard;
  private mechs: MechInstances;
  private fx: BattleFx;
  private raycaster = new THREE.Raycaster();

  private low: boolean;
  private state: BattleState | null = null;
  private viewState: ViewState | null = null;
  private terrain: Terrain = 'plains';
  private boardKey = '';

  private tapCb: TapHandler | null = null;
  private unitCb: UnitHandler | null = null;

  private dressing = new THREE.Group();
  private platform: THREE.Group | null = null;
  private glowBatch: InstancedBatch | null = null;
  private sideBatch: InstancedBatch | null = null;
  private shafts: THREE.ShaderMaterial[] = [];
  private planetMat: THREE.ShaderMaterial | null = null;
  private gridMat: THREE.ShaderMaterial | null = null;
  private starMat: THREE.ShaderMaterial | null = null;
  private disposables: { dispose(): void }[] = [];
  private lights: THREE.Light[] = [];

  private elapsed = 0;
  private emberTimer = 0;
  private running = false;
  /** Input is only gated while the opening sweep is actually playing. */
  private introDone = true;

  /** Every live pointer on the canvas, so pinch-to-zoom can see both fingers. */
  private readonly pointers = new Map<number, { x: number; y: number }>();
  private primaryId = -1;
  private downX = 0;
  private downY = 0;
  private lastX = 0;
  private lastY = 0;
  private downAt = 0;
  private dragged = false;
  private pinchSpan = 0;
  private lastTapAt = 0;
  private resizeObserver: ResizeObserver | null = null;

  constructor(container: HTMLElement) {
    this.container = container;
    this.stage = new Stage(container);
    this.low = String(this.stage.quality) === 'low';

    const aspect = this.aspect();
    this.cam = new BattleCamera(aspect);
    this.scene.add(this.cam.camera);

    this.board = new BattleBoard({ low: this.low });
    this.mechs = new MechInstances(this.board, { low: this.low });
    this.scene.add(this.board.group);
    this.scene.add(this.mechs.group);

    const host: FxHost = {
      shake: (amount: number) => this.stage.shake(amount),
      low: this.low,
    };
    this.fx = new BattleFx({
      scene: this.scene,
      board: this.board,
      mechs: this.mechs,
      camera: this.cam,
      host,
    });

    this.scene.fog = new THREE.FogExp2(PALETTE.void, 0.0135);
    this.scene.add(this.dressing);
    this.buildDressing();
    this.applyTerrain('plains');

    this.stage.setScene(this.scene, this.cam.camera);
    this.attachInput();
    this.observeResize();
    this.applyViewport();

    this.board.setReveal(1);
    this.running = true;
    this.stage.start((dt, elapsed) => this.tick(dt, elapsed));
  }

  // ── public API ────────────────────────────────────────────────────────────

  sync(state: BattleState, view: ViewState): void {
    this.state = state;
    this.viewState = view;

    if (view.lowSpec && !this.low) {
      this.low = true;
      this.board.setLow(true);
      this.mechs.setLow(true);
    }

    if (state.terrain !== this.terrain) this.applyTerrain(state.terrain);

    this.board.sync(state);
    this.mechs.sync(state);

    const key = `${state.w}x${state.h}`;
    if (key !== this.boardKey) {
      this.boardKey = key;
      this.buildPlatform(state.w, state.h);
      this.cam.setBoard(state.w, state.h, 1.9);
      this.applyViewport();
    }

    const bottomIsAttacker = state.bottomSide === 'attacker';
    const bottomColor = bottomIsAttacker ? state.attacker.guildColor : state.defender.guildColor;
    let topColor = bottomIsAttacker ? state.defender.guildColor : state.attacker.guildColor;
    if (topColor === bottomColor) topColor = bottomColor === PALETTE.cyan ? PALETTE.crimson : PALETTE.cyan;
    const deploying =
      state.phase === 'deploy' || state.phase === 'side_pick' || state.phase === 'obstacle_place';
    this.board.setDeployZones(bottomColor, topColor, deploying);
  }

  setHighlights(h: BattleHighlights): void {
    this.board.setHighlights(h);
  }

  /**
   * Fractions of the viewport covered by DOM chrome (the dice tray eats the
   * bottom of a portrait phone). The board is framed inside what is left.
   */
  setSafeInsets(insets: Partial<SafeInsets>): void {
    this.cam.setInsets(insets);
  }

  /** Back to the solved play view. Also reachable by double-tapping the board. */
  recenterCamera(): void {
    this.cam.recenter();
  }

  /** True once the player has orbited or zoomed away from the default framing. */
  get cameraMoved(): boolean {
    return this.cam.isOffDefault;
  }

  /** Drift the camera onto a tile (used when the UI selects a unit). */
  focusTile(x: number, y: number): void {
    this.cam.focus(x, y);
  }

  onTileTap(cb: TapHandler): void {
    this.tapCb = cb;
  }

  onUnitTap(cb: UnitHandler): void {
    this.unitCb = cb;
  }

  /** Animate one battle-log event. Unknown / non-visual events resolve at once. */
  playEvent(e: BattleEvent): Promise<void> {
    switch (e.t) {
      case 'move':
        return this.fx.moveUnit(e.unitId, e.path.length ? e.path : [e.to]);
      case 'teleport':
        return this.fx.teleport(e.unitId, e.from, e.to);
      case 'attack':
        return this.fx
          .attack(e.unitId, e.targetId, e.damage, e.killed)
          .then(() => (e.killed ? this.fx.destroy(e.targetId) : undefined));
      case 'attack_wall':
        return this.fx.attackWall(e.unitId, e.x, e.y, e.destroyed);
      case 'brace':
        return this.fx.brace(e.unitId);
      case 'hazard':
        return this.fx
          .hazardTick(e.unitId, e.damage)
          .then(() => (e.killed ? this.fx.destroy(e.unitId) : undefined));
      case 'collapse':
        return this.fx.collapse(e.x, e.y);
      case 'triple_zero':
        return this.fx.tripleZero(e.side);
      case 'concede':
        return this.fx.defeatFlourish(e.side);
      case 'battle_end': {
        const loser: BattleSide = e.winner === 'attacker' ? 'defender' : 'attacker';
        void this.fx.defeatFlourish(loser);
        return this.fx.victoryFlourish(e.winner);
      }
      case 'deploy':
        return this.playDeploy(e);
      case 'turn_start':
        this.cam.clearFocus();
        return Promise.resolve();
      case 'obstacles_placed': {
        for (const t of e.tiles) this.board.pulseTile(t.x, t.y, 1);
        return Promise.resolve();
      }
      default:
        return Promise.resolve();
    }
  }

  async playEvents(events: BattleEvent[]): Promise<void> {
    for (const e of events) {
      await this.playEvent(e);
    }
  }

  /** Cinematic battle-start sweep + board power-up. */
  async intro(): Promise<void> {
    this.introDone = false;
    this.board.setReveal(0);
    for (const view of this.mechs.all()) view.setOpacity(0);
    const sweep = this.cam.intro(2300);
    await this.animate(1500, (k) => {
      this.board.setReveal(k);
    });
    await this.animate(600, (k) => {
      for (const view of this.mechs.all()) view.setOpacity(k);
    });
    for (const view of this.mechs.all()) view.setOpacity(1);
    this.board.setReveal(1);
    await sweep;
    this.introDone = true;
  }

  dispose(): void {
    this.running = false;
    this.stage.stop();
    this.detachInput();
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.fx.dispose();
    this.mechs.dispose();
    this.board.dispose();
    for (const l of this.lights) this.scene.remove(l);
    this.lights.length = 0;
    this.disposeDressing();
    for (const d of this.disposables) d.dispose();
    this.disposables.length = 0;
    this.scene.clear();
    this.stage.dispose();
  }

  // ── frame ─────────────────────────────────────────────────────────────────

  private tick(dtRaw: number, elapsed: number): void {
    if (!this.running) return;
    const dt = Math.min(0.05, Math.max(0, Number.isFinite(dtRaw) ? dtRaw : 0));
    this.elapsed = elapsed;

    const scale = this.fx.dtScale;
    this.cam.update(dt);
    this.board.update(dt * scale, this.elapsed);
    this.mechs.update(dt * scale, this.elapsed, this.cam.camera);
    this.fx.update(dt, this.elapsed);

    const drain = this.fx.drain;
    updateHulls(this.elapsed, drain);
    this.board.setDrain(drain);
    this.mechs.setDrain(drain);
    if (this.planetMat) this.planetMat.uniforms.uDrain.value = drain;
    if (this.gridMat) this.gridMat.uniforms.uDrain.value = drain;
    if (this.starMat) this.starMat.uniforms.uDrain.value = drain;
    for (const s of this.shafts) {
      s.uniforms.uTime.value = this.elapsed;
      s.uniforms.uDrain.value = drain;
    }
    if (this.planetMat) this.planetMat.uniforms.uTime.value = this.elapsed;
    if (this.gridMat) this.gridMat.uniforms.uTime.value = this.elapsed;
    if (this.starMat) this.starMat.uniforms.uTime.value = this.elapsed;

    // ambient embers + hazard vents
    this.emberTimer -= dt * scale;
    if (this.emberTimer <= 0) {
      this.emberTimer = this.low ? 0.34 : 0.13;
      const r = Math.max(this.board.width, this.board.height) * TILE_PITCH * 0.85;
      this.fx.emitAmbientEmber(
        (Math.random() - 0.5) * r * 2,
        -1.4 + Math.random() * 1.2,
        (Math.random() - 0.5) * r * 2,
      );
      const st = this.state;
      if (st && !this.low) {
        for (let y = 0; y < st.h; y++) {
          for (let x = 0; x < st.w; x++) {
            if (st.grid[y][x].kind === 'hazard' && Math.random() < 0.55) {
              this.fx.emitHazardEmber(x, y);
            }
          }
        }
      }
    }
    // NOTE: Stage.tick() drives updateAllMaterials() for the shared core
    // material registry immediately after this callback returns.
  }

  private animate(ms: number, fn: (k: number) => void): Promise<void> {
    return new Promise<void>((resolve) => {
      const start = performance.now();
      const step = (): void => {
        const k = Math.min(1, (performance.now() - start) / ms);
        fn(k);
        if (k >= 1 || !this.running) resolve();
        else requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });
  }

  private async playDeploy(e: Extract<BattleEvent, { t: 'deploy' }>): Promise<void> {
    const views = e.units
      .map((u) => this.mechs.get(u.id))
      .filter((v): v is MechView => v !== undefined);
    if (!views.length) return;
    for (const v of views) v.animating = true;
    await this.animate(420, (k) => {
      const e2 = 1 - Math.pow(1 - k, 3);
      for (const v of views) {
        v.snapTo(this.board);
        v.root.position.y += (1 - e2) * 2.4;
        v.setOpacity(Math.min(1, k * 1.6));
      }
    });
    for (const v of views) {
      v.setOpacity(1);
      v.animating = false;
      v.snapTo(this.board);
      this.fx.emitAmbientEmber(v.root.position.x, v.root.position.y, v.root.position.z);
    }
    this.stage.shake(FX.shakeSmall);
  }

  // ── scene dressing ────────────────────────────────────────────────────────

  private buildDressing(): void {
    // lights (my shaders are self-lit, these serve any shared core materials)
    const hemi = new THREE.HemisphereLight(0x7fc6ff, 0x0a1020, 0.55);
    const key = new THREE.DirectionalLight(0xbfe6ff, 1.1);
    key.position.set(5, 9, 4);
    const fill = new THREE.DirectionalLight(0x4a6bd0, 0.5);
    fill.position.set(-6, 3, -7);
    const amb = new THREE.AmbientLight(0x101a2c, 0.6);
    this.lights = [hemi, key, fill, amb];
    for (const l of this.lights) this.scene.add(l);

    // starfield
    {
      const count = this.low ? 700 : 1600;
      const pos = new Float32Array(count * 3);
      const size = new Float32Array(count);
      const tw = new Float32Array(count);
      for (let i = 0; i < count; i++) {
        const th = Math.random() * Math.PI * 2;
        const ph = Math.acos(2 * Math.random() - 1);
        const r = 150;
        pos[i * 3] = Math.sin(ph) * Math.cos(th) * r;
        pos[i * 3 + 1] = Math.cos(ph) * r * 0.7 + 20;
        pos[i * 3 + 2] = Math.sin(ph) * Math.sin(th) * r;
        size[i] = 0.09 + Math.random() * 0.3;
        tw[i] = Math.random();
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
      geo.setAttribute('aTwinkle', new THREE.BufferAttribute(tw, 1));
      const mat = new THREE.ShaderMaterial({
        vertexShader: STAR_VERT,
        fragmentShader: STAR_FRAG,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        uniforms: {
          uTime: { value: 0 },
          uScale: { value: 420 },
          uDrain: { value: 0 },
          uColor: { value: new THREE.Color(PALETTE.white) },
        },
      });
      this.starMat = mat;
      const stars = new THREE.Points(geo, mat);
      stars.frustumCulled = false;
      stars.renderOrder = -10;
      this.dressing.add(stars);
      this.disposables.push(geo, mat);
    }

    // the planet, far below
    {
      const geo = new THREE.PlaneGeometry(190, 190);
      geo.rotateX(-Math.PI / 2);
      const mat = new THREE.ShaderMaterial({
        vertexShader: PLANET_VERT,
        fragmentShader: PLANET_FRAG,
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
        fog: false,
        uniforms: {
          uTime: { value: 0 },
          uDrain: { value: 0 },
          uColor: { value: new THREE.Color(TERRAIN_META.plains.color) },
          uAccent: { value: new THREE.Color(TERRAIN_META.plains.accent) },
        },
      });
      this.planetMat = mat;
      const planet = new THREE.Mesh(geo, mat);
      planet.position.y = -46;
      planet.renderOrder = -8;
      planet.frustumCulled = false;
      this.dressing.add(planet);
      this.disposables.push(geo, mat);
    }

    // holographic sensor grid running off past the board
    {
      const pts: number[] = [];
      const fades: number[] = [];
      const span = 17;
      const step = TILE_PITCH;
      const push = (x1: number, z1: number, x2: number, z2: number): void => {
        const f1 = Math.max(0, 1 - Math.hypot(x1, z1) / span);
        const f2 = Math.max(0, 1 - Math.hypot(x2, z2) / span);
        pts.push(x1, -0.62, z1, x2, -0.62, z2);
        fades.push(f1 * f1, f2 * f2);
      };
      for (let i = -Math.round(span / step); i <= Math.round(span / step); i++) {
        push(i * step, -span, i * step, span);
        push(-span, i * step, span, i * step);
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
      geo.setAttribute('aFade', new THREE.Float32BufferAttribute(fades, 1));
      const mat = new THREE.ShaderMaterial({
        vertexShader: GRID_VERT,
        fragmentShader: GRID_FRAG,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        uniforms: {
          uColor: { value: new THREE.Color(PALETTE.cyanDeep) },
          uTime: { value: 0 },
          uDrain: { value: 0 },
        },
      });
      this.gridMat = mat;
      const grid = new THREE.LineSegments(geo, mat);
      grid.frustumCulled = false;
      grid.renderOrder = -4;
      this.dressing.add(grid);
      this.disposables.push(geo, mat);
    }

    // volumetric-looking light shafts
    {
      const count = this.low ? 2 : 4;
      for (let i = 0; i < count; i++) {
        const a = (i / count) * Math.PI * 2 + 0.7;
        const geo = new THREE.CylinderGeometry(0.5, 2.6, 13, 10, 1, true);
        const mat = new THREE.ShaderMaterial({
          vertexShader: SHAFT_VERT,
          fragmentShader: SHAFT_FRAG,
          transparent: true,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          side: THREE.DoubleSide,
          fog: false,
          uniforms: {
            uTime: { value: 0 },
            uDrain: { value: 0 },
            uPhase: { value: i * 1.7 },
            uColor: { value: new THREE.Color(PALETTE.cyan) },
          },
        });
        const shaft = new THREE.Mesh(geo, mat);
        shaft.position.set(Math.cos(a) * 4.6, 6.2, Math.sin(a) * 4.6);
        shaft.rotation.z = Math.cos(a) * 0.16;
        shaft.rotation.x = -Math.sin(a) * 0.16;
        shaft.renderOrder = -2;
        shaft.frustumCulled = false;
        this.shafts.push(mat);
        this.dressing.add(shaft);
        this.disposables.push(geo, mat);
      }

      // one instanced glow pool for every shaft footprint
      const glowMat = makeGlowSpriteMaterial(PALETTE.cyan, 1.7);
      const batch = new InstancedBatch(this.dressing, billboardQuadGeometry(1), glowMat, count, [
        { name: 'iColor', size: 3, fill: [1, 1, 1] },
        { name: 'iAux', size: 3, fill: [1, 1, 0] },
      ]);
      batch.setRenderOrder(-3);
      batch.begin();
      const m = new THREE.Matrix4();
      for (let i = 0; i < count; i++) {
        const a = (i / count) * Math.PI * 2 + 0.7;
        m.makeTranslation(Math.cos(a) * 4.6, -0.5, Math.sin(a) * 4.6);
        const idx = batch.add(m);
        batch.set(idx, 'iColor', 1, 1, 1);
        batch.set(idx, 'iAux', 5.2, 0.34, i * 0.21);
      }
      batch.end();
      this.glowBatch = batch;
      this.disposables.push(glowMat);
    }
  }

  private buildPlatform(w: number, h: number): void {
    if (this.sideBatch) {
      this.sideBatch.dispose();
      this.sideBatch = null;
    }
    if (this.platform) {
      this.dressing.remove(this.platform);
      this.platform.traverse((o) => {
        if (o instanceof THREE.Mesh) o.geometry.dispose();
      });
      this.platform = null;
    }
    const group = new THREE.Group();
    const radius = Math.max(w, h) * TILE_PITCH * 0.7;

    const slabGeo = new THREE.CylinderGeometry(radius, radius * 0.86, 0.8, 8, 1);
    slabGeo.rotateY(Math.PI / 8);
    const slabMat = new THREE.MeshStandardMaterial({
      color: PALETTE.abyss,
      roughness: 0.85,
      metalness: 0.35,
      emissive: PALETTE.void,
    });
    const slab = new THREE.Mesh(slabGeo, slabMat);
    slab.position.y = -0.42;
    group.add(slab);
    this.disposables.push(slabMat);

    const rimGeo = new THREE.TorusGeometry(radius * 0.995, 0.035, 4, 8);
    rimGeo.rotateX(Math.PI / 2);
    rimGeo.rotateY(Math.PI / 8);
    const rimMat = new THREE.MeshBasicMaterial({ color: PALETTE.cyan, transparent: true, opacity: 0.85 });
    const rim = new THREE.Mesh(rimGeo, rimMat);
    rim.position.y = -0.04;
    group.add(rim);
    this.disposables.push(rimMat);

    const keelGeo = new THREE.ConeGeometry(radius * 0.8, 2.6, 8, 1);
    keelGeo.rotateY(Math.PI / 8);
    const keelMat = new THREE.MeshStandardMaterial({
      color: PALETTE.void,
      roughness: 1,
      metalness: 0.1,
    });
    const keel = new THREE.Mesh(keelGeo, keelMat);
    keel.rotation.x = Math.PI;
    keel.position.y = -2.05;
    group.add(keel);
    this.disposables.push(keelMat);

    this.platform = group;
    this.dressing.add(group);

    // side bearing chevrons — attacker / defender baseline markers
    const st = this.state;
    const bottomIsAttacker = st ? st.bottomSide === 'attacker' : true;
    const markerColors: number[] = [
      bottomIsAttacker
        ? (st?.attacker.guildColor ?? PALETTE.crimson)
        : (st?.defender.guildColor ?? PALETTE.cyan),
      bottomIsAttacker
        ? (st?.defender.guildColor ?? PALETTE.cyan)
        : (st?.attacker.guildColor ?? PALETTE.crimson),
    ];
    const tokenMat = makeTokenMaterial(PALETTE.white, { emissive: 1.35 });
    const sides = new InstancedBatch(group, armyChevronGeometry(0.34), tokenMat, 2, [
      { name: 'iColor', size: 3, fill: [1, 1, 1] },
      { name: 'iAux', size: 3, fill: [1, 0, 0] },
    ]);
    sides.begin();
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const s = new THREE.Vector3(1, 1, 1);
    for (let i = 0; i < 2; i++) {
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), i === 0 ? 0 : Math.PI);
      m.compose(
        new THREE.Vector3(0, PLATE_H * 0.1, (i === 0 ? 1 : -1) * (radius * 0.86)),
        q,
        s,
      );
      const idx = sides.add(m);
      _colorA.setHex(markerColors[i], THREE.SRGBColorSpace);
      sides.set(idx, 'iColor', _colorA.r, _colorA.g, _colorA.b);
      sides.set(idx, 'iAux', 1, 0, 0.5);
    }
    sides.end();
    this.sideBatch = sides;
    this.disposables.push(tokenMat);
  }

  private applyTerrain(terrain: Terrain): void {
    this.terrain = terrain;
    const meta = TERRAIN_META[terrain];
    _colorA.setHex(meta.color, THREE.SRGBColorSpace);
    _colorB.setHex(meta.accent, THREE.SRGBColorSpace);

    const ambient = _colorA.clone().multiplyScalar(0.34).lerp(new THREE.Color(PALETTE.abyss), 0.4);
    const keyCol = _colorB.clone().lerp(new THREE.Color(PALETTE.white), 0.55).multiplyScalar(0.95);
    const fillCol = _colorA.clone().multiplyScalar(0.55);
    setHullEnvironment({ ambient, key: keyCol, fill: fillCol, rim: _colorB.clone() });

    if (this.planetMat) {
      (this.planetMat.uniforms.uColor.value as THREE.Color).setHex(meta.color, THREE.SRGBColorSpace);
      (this.planetMat.uniforms.uAccent.value as THREE.Color).setHex(meta.accent, THREE.SRGBColorSpace);
    }
    if (this.gridMat) {
      (this.gridMat.uniforms.uColor.value as THREE.Color)
        .setHex(meta.accent, THREE.SRGBColorSpace)
        .multiplyScalar(0.75);
    }
    for (const s of this.shafts) {
      (s.uniforms.uColor.value as THREE.Color).setHex(meta.accent, THREE.SRGBColorSpace);
    }
    if (this.scene.fog instanceof THREE.FogExp2) {
      this.scene.fog.color.setHex(meta.color, THREE.SRGBColorSpace).multiplyScalar(0.16);
    }
  }

  private disposeDressing(): void {
    if (this.glowBatch) {
      this.glowBatch.dispose();
      this.glowBatch = null;
    }
    if (this.sideBatch) {
      this.sideBatch.dispose();
      this.sideBatch = null;
    }
    this.dressing.traverse((o) => {
      if (o instanceof THREE.Mesh || o instanceof THREE.Points || o instanceof THREE.LineSegments) {
        o.geometry.dispose();
      }
    });
    this.scene.remove(this.dressing);
    this.dressing.clear();
    this.shafts.length = 0;
    this.platform = null;
  }

  // ── viewport & input ──────────────────────────────────────────────────────

  private aspect(): number {
    const w = this.container.clientWidth || 390;
    const h = this.container.clientHeight || 844;
    return w / Math.max(1, h);
  }

  private applyViewport(): void {
    const h = this.container.clientHeight || 844;
    this.cam.resize(this.aspect());
    const dpr = Math.min(typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1, 2);
    // gl_PointSize is in framebuffer pixels: size_px = worldSize * uScale / depth
    const scale = (h * dpr * 0.5) / Math.tan((BATTLE_VIEW.camera.fov * Math.PI) / 360);
    this.fx.setPointScale(scale);
    if (this.starMat) this.starMat.uniforms.uScale.value = scale;
  }

  private observeResize(): void {
    if (typeof ResizeObserver === 'undefined') return;
    this.resizeObserver = new ResizeObserver(() => {
      this.stage.resize();
      this.applyViewport();
    });
    this.resizeObserver.observe(this.container);
  }

  /** Distance between the two active fingers, in CSS pixels. */
  private pinchDistance(): number {
    const pts = [...this.pointers.values()];
    if (pts.length < 2) return 0;
    return Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
  }

  /**
   * Pointer capture is a nice-to-have, never a precondition.
   *
   * `setPointerCapture` throws NotFoundError whenever the id is not an active
   * pointer — a pointer already released, a detached element, a synthesised
   * event. Unguarded, that exception aborted the rest of the handler, so the
   * gesture never got its start coordinates and the camera silently ignored the
   * drag. Losing capture costs a little tracking accuracy; losing the handler
   * costs the whole interaction.
   */
  private capture(id: number, on: boolean): void {
    try {
      if (on) this.container.setPointerCapture?.(id);
      else this.container.releasePointerCapture?.(id);
    } catch {
      /* capture is optional */
    }
  }

  private onDown = (ev: PointerEvent): void => {
    this.pointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    this.capture(ev.pointerId, true);

    if (this.pointers.size >= 2) {
      // A second finger means this gesture is a pinch. Mark it dragged so the
      // lift never resolves as a tap on whatever was under the fingers.
      this.pinchSpan = this.pinchDistance();
      this.dragged = true;
      return;
    }

    this.primaryId = ev.pointerId;
    this.downX = ev.clientX;
    this.downY = ev.clientY;
    this.lastX = ev.clientX;
    this.lastY = ev.clientY;
    this.downAt = performance.now();
    this.dragged = false;
  };

  private onMove = (ev: PointerEvent): void => {
    const rec = this.pointers.get(ev.pointerId);
    if (!rec) return;
    rec.x = ev.clientX;
    rec.y = ev.clientY;

    if (this.pointers.size >= 2) {
      const span = this.pinchDistance();
      // Fingers spreading means zoom IN, which is a shorter camera distance.
      if (this.pinchSpan > 0 && span > 0) this.cam.zoomBy(this.pinchSpan / span);
      this.pinchSpan = span;
      return;
    }

    if (ev.pointerId !== this.primaryId) return;
    const dx = ev.clientX - this.lastX;
    const dy = ev.clientY - this.lastY;
    this.lastX = ev.clientX;
    this.lastY = ev.clientY;
    if (!this.dragged) {
      const total = Math.hypot(ev.clientX - this.downX, ev.clientY - this.downY);
      if (total > 9) this.dragged = true;
    }
    if (this.dragged) this.cam.orbitBy(dx, dy);
  };

  private onUp = (ev: PointerEvent): void => {
    if (!this.pointers.delete(ev.pointerId)) return;
    this.capture(ev.pointerId, false);

    if (this.pointers.size > 0) {
      // One finger lifted out of a pinch. Re-seed the survivor as the orbit
      // pointer so the camera does not jump, and keep the gesture "dragged".
      const [id, pt] = [...this.pointers.entries()][0];
      this.primaryId = id;
      this.lastX = pt.x;
      this.lastY = pt.y;
      this.pinchSpan = this.pinchDistance();
      this.dragged = true;
      return;
    }

    this.pinchSpan = 0;
    const wasPrimary = ev.pointerId === this.primaryId;
    this.primaryId = -1;
    if (!wasPrimary) return;

    const held = performance.now() - this.downAt;
    if (this.dragged || held > 600) return;

    // Double tap re-frames the board. Free look has no natural way home, and
    // hunting for the original angle by hand is worse than not having free look.
    const now = performance.now();
    if (now - this.lastTapAt < 300) {
      this.lastTapAt = 0;
      this.cam.recenter();
      return;
    }
    this.lastTapAt = now;
    this.handleTap(ev.clientX, ev.clientY);
  };

  private onCancel = (ev: PointerEvent): void => {
    this.pointers.delete(ev.pointerId);
    if (this.pointers.size === 0) {
      this.primaryId = -1;
      this.pinchSpan = 0;
      this.dragged = false;
    }
  };

  /** Wheel and trackpad zoom, for the desktop and IDE builds. */
  private onWheel = (ev: WheelEvent): void => {
    ev.preventDefault();
    // Trackpads send many small deltas and wheels a few large ones; the
    // exponential keeps both feeling like one continuous gesture.
    const delta = Math.max(-240, Math.min(240, ev.deltaY));
    this.cam.zoomBy(Math.exp(delta * 0.0018));
  };

  private handleTap(clientX: number, clientY: number): void {
    if (this.viewState?.cinematic) return;
    if (this.fx.busy || !this.introDone) return;
    const rect = this.container.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return;
    _ndc.set(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -(((clientY - rect.top) / rect.height) * 2 - 1),
    );
    this.raycaster.setFromCamera(_ndc, this.cam.camera);

    const unitId = this.mechs.unitAt(this.raycaster);
    if (unitId && this.unitCb) {
      this.unitCb(unitId);
      return;
    }
    const tile = this.board.tileAt(this.raycaster);
    if (tile && this.tapCb) this.tapCb(tile.x, tile.y);
  }

  private attachInput(): void {
    const el = this.container;
    el.style.touchAction = 'none';
    el.addEventListener('pointerdown', this.onDown);
    el.addEventListener('pointermove', this.onMove);
    el.addEventListener('pointerup', this.onUp);
    el.addEventListener('pointercancel', this.onCancel);
    el.addEventListener('wheel', this.onWheel, { passive: false });
  }

  private detachInput(): void {
    const el = this.container;
    el.removeEventListener('pointerdown', this.onDown);
    el.removeEventListener('pointermove', this.onMove);
    el.removeEventListener('pointerup', this.onUp);
    el.removeEventListener('pointercancel', this.onCancel);
    el.removeEventListener('wheel', this.onWheel);
    this.pointers.clear();
  }
}
