  private async runTeleport(
    unitId: string,
    from: { x: number; y: number },
    to: { x: number; y: number },
  ): Promise<void> {
    const view = this.mechs.get(unitId);
    if (!view) return;
    view.animating = true;
    const violet = _tmpColor.setHex(PALETTE.violet, THREE.SRGBColorSpace).clone();

    this.board.worldOf(from.x, from.y, _a);
    this.ring(_a, violet, 1.6, 520, 3);
    this.flash(_a, violet, 1.1, 420, 2);
    await this.anim(280, (k) => {
      view.setOpacity(1 - k);
      view.body.scale.set(1 - k * 0.4, 1 + k * 1.2, 1 - k * 0.4);
      view.body.position.y = k * 0.35;
    });
    view.body.scale.set(1, 1, 1);
    view.body.position.y = 0;

    view.tx = to.x;
    view.ty = to.y;
    view.snapTo(this.board);
    this.cam.focus(to.x, to.y);
    this.board.worldOf(to.x, to.y, _b);
    this.ring(_b, violet, 1.7, 560, 3);
    this.flash(_b, violet, 1.3, 460, 2);
    this.burst(_b, violet, 14, 1.9, 0.6, 0.06, -1.2);

    await this.anim(300, (k) => {
      view.setOpacity(k);
      view.body.scale.set(0.6 + k * 0.4, 1.6 - k * 0.6, 0.6 + k * 0.4);
      view.body.position.y = (1 - k) * 0.3;
    });
    view.setOpacity(1);
    view.body.scale.set(1, 1, 1);
    view.body.position.y = 0;
    view.animating = false;
  }

