  /**
   * GDD §7.2 — the triple-zero humiliation. Colour drains out of the world,
   * rain falls, every mech powers down with a puff of steam, and the camera
   * gives up on the whole situation.
   */
  tripleZero(side?: BattleSide): Promise<void> {
    return this.track(this.runTripleZero(side));
  }

  private async runTripleZero(side?: BattleSide): Promise<void> {
    const ms = FX.tripleZeroMs;
    this.grade.visible = true;
    const affected: MechView[] = [];
    for (const view of this.mechs.all()) {
      if (view.dead) continue;
      if (side && view.side !== side) continue;
      affected.push(view);
    }

    // steam puffs — the sound of hydraulics giving up
    let vented = false;

    this.cam.slump(0);
    await this.anim(ms * 0.24, (k) => {
      this.drain = k * 0.94;
      this.gradeMat.uniforms.uAmount.value = k * 0.85;
      for (const v of affected) v.powerDown(k);
      this.cam.slump(k * 0.55);
      if (!vented && k > 0.55) {
        vented = true;
        for (const v of affected) {
          _a.copy(v.root.position);
          for (let i = 0; i < 10; i++) {
            this.smoke.spawn({
              x: _a.x + (Math.random() - 0.5) * 0.34,
              y: _a.y + v.height * 0.28,
              z: _a.z + (Math.random() - 0.5) * 0.34,
              vx: (Math.random() - 0.5) * 0.9,
              vy: 0.14 + Math.random() * 0.2,
              vz: (Math.random() - 0.5) * 0.9,
              ttl: 1.6,
              size: 0.13,
              grow: 3.4,
              drag: 1.5,
              color: this.colDust,
            });
          }
        }
      }
    });

    await this.anim(ms * 0.5, (k) => {
      this.cam.slump(0.55 + k * 0.45);
      for (const v of affected) v.powerDown(1);
    });

    await this.anim(ms * 0.26, (k) => {
      const e = 1 - k;
      this.drain = 0.94 * e;
      this.gradeMat.uniforms.uAmount.value = 0.85 * e;
      for (const v of affected) v.powerDown(e);
      this.cam.slump(e);
    });

    this.drain = 0;
    this.gradeMat.uniforms.uAmount.value = 0;
    this.grade.visible = false;
    for (const v of affected) v.powerDown(0);
    this.cam.slump(0);
  }

  /** Drop everything in flight (screen change / battle teardown). */
  reset(): void {
    for (const j of this.jobs) j.done();
    this.jobs.length = 0;
    this.stopT = 0;
    this.busyCount = 0;
    this.drain = 0;
    this.gradeMat.uniforms.uAmount.value = 0;
    this.grade.visible = false;
    this.sparks.clear();
    this.smoke.clear();
    this.dust.clear();
    this.embers.clear();
    this.flashes.clear();
    this.rings.clear();
    this.decals.clear();
    this.beams.clear();
    this.numbers.clear();
  }

  dispose(): void {
    this.reset();
    for (const p of [this.sparks, this.smoke, this.dust, this.embers]) {
      this.scene.remove(p.points);
      p.dispose();
    }
    for (const p of [this.flashes, this.rings, this.decals, this.beams, this.numbers]) {
      this.scene.remove(p.mesh);
      p.dispose();
    }
    this.numberAtlas.dispose();
    this.cam.camera.remove(this.grade);
    this.grade.geometry.dispose();
    this.gradeMat.dispose();
  }
