/**
 * TERRA BELLUM — the Battle screen (GDD §7, §12.3).
 *
 * Orchestrates the whole tactical layer:
 *
 *   side_pick → obstacle_place → deploy → rolling → assign → acting → ended
 *
 * Each phase gets its own focused UI plus one unambiguous instruction banner.
 * New `BattleState.log` entries are played through `BattleScene.playEvent` in a
 * strictly serialised queue (one animation at a time, never overlapping), which
 * is also what makes a hostile turn watchable: their roll tumbles, their dice
 * dock onto their chassis, then their units act, all under a THEIR TURN banner.
 *
 * The turn clock (`BATTLE.turnMs`) drives a depleting ring that runs amber
 * then crimson, ticks audibly through the last ten seconds, and auto-passes on
 * expiry. Damage previews are computed client-side from the pure rules module;
 * the backend stays authoritative for every mutation.
 */
import '../../styles/battle.css';

import { BATTLE } from '../../config/balance';
import { UNITS } from '../../config/units';
import type { IBackend } from '../../backend/IBackend';
import type {
  BattleEvent,
  BattleSide,
  BattleState,
  BattleUnit,
  DieIndex,
  GameState,
  Guild,
  Result,
  UnitId,
} from '../../game/types';
import { emitFx, game, view } from '../../game/store';
import { describeEvent } from '../../game/battle/replay';
import { autoDeploy, hasDeployed, obstacleSpots } from '../../game/battle/engine';
import {
  battleDistance,
  canAttack,
  computeDamage,
  deployRowsFor,
  effectiveRange,
  hasLineOfSight,
  reachableTiles,
  tileKey,
} from '../../game/battle/rules';
import { makeRng } from '../../game/rng';
import { BattleScene, type BattleHighlights } from '../../render/battle/BattleScene';
import type { Screen } from '../screen';
import { Disposer, el, haptic } from '../dom';
import { toast } from '../components';
import { DiceTray, type DiceTrayState, type TrayMode } from '../battle/diceTray';
import { UnitBar, unitLabel } from '../battle/unitBar';
import { ActionBar, type ActionMode, type AttackTarget } from '../battle/actionBar';
import { BattleHud, type BannerTone } from '../battle/battleHud';
import { DeployPanel, type DeployMode } from '../battle/deployPanel';
import { Cinematics } from '../battle/cinematics';
import { coachSeen, openBattleCoach } from '../battle/coach';

// ─────────────────────────────────────────────────────────────────────────────
// Small helpers
// ─────────────────────────────────────────────────────────────────────────────

const wait = (ms: number): Promise<void> =>
  new Promise<void>((r) => window.setTimeout(r, Math.max(0, ms)));

function reduced(): boolean {
  return document.body.classList.contains('reduce-motion');
}

function other(side: BattleSide): BattleSide {
  return side === 'attacker' ? 'defender' : 'attacker';
}

/** Turn-clock cue. Silent until the player has touched the screen once. */
class TickCue {
  private ctx: AudioContext | null = null;
  private armed = false;

  arm(): void {
    if (this.armed) return;
    this.armed = true;
    const w = window as Window & { AudioContext?: typeof AudioContext };
    const Ctor = w.AudioContext;
    if (!Ctor) return;
    try {
      this.ctx = new Ctor();
    } catch {
      this.ctx = null;
    }
  }

  private blip(freq: number, ms: number, gain: number, type: OscillatorType): void {
    const ctx = this.ctx;
    if (!ctx) return;
    try {
      if (ctx.state === 'suspended') void ctx.resume();
      const t0 = ctx.currentTime;
      const osc = ctx.createOscillator();
      const amp = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, t0);
      amp.gain.setValueAtTime(0.0001, t0);
      amp.gain.exponentialRampToValueAtTime(gain, t0 + 0.01);
      amp.gain.exponentialRampToValueAtTime(0.0001, t0 + ms / 1000);
      osc.connect(amp);
      amp.connect(ctx.destination);
      osc.start(t0);
      osc.stop(t0 + ms / 1000 + 0.03);
    } catch {
      /* audio is a garnish, never a dependency */
    }
  }

  tick(secondsLeft: number): void {
    if (secondsLeft <= 0) {
      this.blip(180, 260, 0.09, 'sawtooth');
      return;
    }
    const urgent = secondsLeft <= 5;
    this.blip(urgent ? 1180 : 820, urgent ? 70 : 46, urgent ? 0.075 : 0.04, 'square');
  }

  dispose(): void {
    try {
      void this.ctx?.close();
    } catch {
      /* ignore */
    }
    this.ctx = null;
    this.armed = false;
  }
}

// ─────────────────────────────────────────────────────────────────────────────

export function createBattleScreen(backend: IBackend): Screen {
  // ── DOM skeleton ──────────────────────────────────────────────────────────
  const sceneHost = el('div', { class: 'battle__scene' });
  const setupHost = el('div', { class: 'battle__setup scroll no-scrollbar' });
  const lower = el('div', { class: 'battle__lower' });
  const turnFlag = el('div', { class: 'turnflag', aria: { hidden: 'true' } });

  const root = el(
    'div',
    { class: 'screen battle-screen' },
    sceneHost,
    el('div', { class: 'battle__vignette', aria: { hidden: 'true' } }),
    el('div', { class: 'battle__scan', aria: { hidden: 'true' } }),
    turnFlag,
  );

  // ── mutable screen state ──────────────────────────────────────────────────
  let scene: BattleScene | null = null;
  let live: GameState | null = null;
  let pushedAt = 0;
  let battleId = '';
  let mySide: BattleSide = 'attacker';

  let played = 0;
  let queue: Promise<void> = Promise.resolve();
  let queueDepth = 0;

  let selectedUnitId: UnitId | null = null;
  let mode: ActionMode = 'none';
  let busy = false;
  let autoPassing = false;
  let outcomeShown = false;
  let introRun = false;
  let coachOffered = false;
  let mounted = false;

  /** What the playback cursor has revealed, as opposed to what the server knows. */
  let shownDice: [number, number, number] | null = null;
  let shownAssign: Partial<Record<DieIndex, UnitId>> = {};

  let armedDie: DieIndex | null = null;
  let dragDie: DieIndex | null = null;

  let placements = new Map<UnitId, { x: number; y: number }>();
  let placementKey = '';
  let heldUnitId: UnitId | null = null;

  const cue = new TickCue();
  const disposer = new Disposer();

  // ── component wiring ──────────────────────────────────────────────────────

  const hud: BattleHud = new BattleHud({
    onConcede: () => openConcede(),
    onTick: (secs) => cue.tick(secs),
    onOpenLog: () => hud.openLog(),
    onOpenCoach: () => {
      openBattleCoach({ manual: true });
    },
  });

  const tray = new DiceTray({
    onRoll: () => void call(backend.rollDice(), 'ROLL REJECTED'),
    onConfirm: () => void call(backend.confirmAssignments(), 'CONFIRM REJECTED'),
    onEndTurn: () => void call(backend.endTurn(), 'END TURN REJECTED'),
    onAssign: (die, unitId) => void call(backend.assignDie(die, unitId), 'ASSIGN REJECTED'),
    onUnassign: (die) => void call(backend.unassignDie(die), 'UNASSIGN REJECTED'),
    onArmedChange: (die) => {
      armedDie = die;
      render();
    },
    onDragChange: (die) => {
      dragDie = die;
      render();
    },
    resolveDrop: (x, y) => {
      const node = document.elementFromPoint(x, y);
      const chip = node instanceof Element ? node.closest('[data-drop-unit]') : null;
      if (!(chip instanceof HTMLElement)) return null;
      const id = chip.dataset.dropUnit;
      if (!id) return null;
      return dropTargets().has(id) ? id : null;
    },
    labelOf: (unitId) => {
      const u = currentBattle()?.units.find((x) => x.id === unitId);
      return u ? unitLabel(u) : unitId.slice(-4).toUpperCase();
    },
  });

  const unitBar = new UnitBar({
    onSelect: (unitId) => handleFriendlyTap(unitId),
    onEnemyTap: (unitId) => handleHostileTap(unitId),
  });

  const actionBar = new ActionBar({
    onMode: (next) => {
      mode = next;
      render();
    },
    onBrace: () => {
      const id = selectedUnitId;
      if (!id) return;
      void call(backend.brace(id), 'BRACE REJECTED');
    },
    onTarget: (t) => fireAt(t),
  });

  const deployPanel = new DeployPanel({
    onPickSide: (bottom) => void call(backend.pickSide(bottom), 'SIDE PICK REJECTED'),
    onPlaceObstacle: (x, y) => void call(backend.placeObstacle(x, y), 'BARRICADE REJECTED'),
    onFinishObstacles: () => void call(backend.finishObstacles(), 'CANNOT LEAVE STAGING'),
    onPlaceUnit: (unitId, x, y) => placeUnit(unitId, x, y),
    onHold: (unitId) => {
      heldUnitId = unitId;
      render();
    },
    onAutoDeploy: () => {
      const b = currentBattle();
      if (!b) return;
      placements = autoArrange(b);
      heldUnitId = null;
      haptic([8, 20, 8]);
      render();
    },
    onReady: () => {
      const list = [...placements.entries()].map(([unitId, p]) => ({ unitId, x: p.x, y: p.y }));
      void call(backend.commitDeployment(list), 'DEPLOYMENT REJECTED');
    },
  });

  const cine = new Cinematics();

  setupHost.appendChild(deployPanel.el);
  lower.appendChild(unitBar.el);
  lower.appendChild(actionBar.el);
  lower.appendChild(tray.el);
  root.appendChild(hud.el);
  root.appendChild(setupHost);
  root.appendChild(lower);
  root.appendChild(cine.el);

  // ── state access ──────────────────────────────────────────────────────────

  function currentBattle(): BattleState | undefined {
    return live?.battle;
  }

  function nowMs(): number {
    if (!live) return Date.now();
    return live.now + (performance.now() - pushedAt);
  }

  function resolveSide(b: BattleState, s: GameState): BattleSide {
    if (b.attacker.playerId === s.meId && !b.attacker.ai) return 'attacker';
    if (b.defender.playerId === s.meId && !b.defender.ai) return 'defender';
    if (b.attacker.playerId === s.meId) return 'attacker';
    return 'defender';
  }

  function guildOf(id: string | undefined): Guild | undefined {
    if (!id || !live) return undefined;
    return live.guilds[id];
  }

  function myUnits(b: BattleState): BattleUnit[] {
    return b.units.filter((u) => u.side === mySide);
  }

  function foeUnits(b: BattleState): BattleUnit[] {
    return b.units.filter((u) => u.side === other(mySide));
  }

  function selectedUnit(b: BattleState): BattleUnit | null {
    if (!selectedUnitId) return null;
    return b.units.find((u) => u.id === selectedUnitId && u.alive) ?? null;
  }

  function assignedUnitIds(b: BattleState): Set<UnitId> {
    const out = new Set<UnitId>();
    const src = b.turn === mySide ? b.assignments : shownAssign;
    for (const die of [0, 1, 2] as DieIndex[]) {
      const id = src[die];
      if (id !== undefined) out.add(id);
    }
    return out;
  }

  /** Chassis that will accept the die currently armed or dragged. */
  function dropTargets(): Set<UnitId> {
    const b = currentBattle();
    const out = new Set<UnitId>();
    if (!b || b.phase !== 'assign' || b.turn !== mySide) return out;
    const taken = assignedUnitIds(b);
    for (const u of myUnits(b)) {
      if (u.alive && !taken.has(u.id)) out.add(u.id);
    }
    return out;
  }

  // ── backend calls ─────────────────────────────────────────────────────────

  async function call<T>(p: Promise<Result<T>>, context: string): Promise<T | null> {
    busy = true;
    render();
    let res: Result<T>;
    try {
      res = await p;
    } catch (error: unknown) {
      busy = false;
      render();
      toast({ title: context, body: String(error), kind: 'bad' });
      return null;
    }
    busy = false;
    if (!res.ok) {
      haptic([30, 40, 30]);
      toast({ title: context, body: res.error, kind: 'bad' });
      render();
      return null;
    }
    render();
    return res.value;
  }

  // ── event playback queue ──────────────────────────────────────────────────

  function enqueue(task: () => Promise<void>): void {
    queueDepth++;
    queue = queue
      .then(task)
      .catch((error: unknown) => {
        console.error('[terra-bellum] battle playback', error);
      })
      .then(() => {
        queueDepth--;
        if (queueDepth === 0) settle();
      });
  }

  function settle(): void {
    if (!mounted) return;
    render();
    const b = currentBattle();
    if (b && b.phase === 'ended' && !outcomeShown) {
      outcomeShown = true;
      showOutcome(b);
    }
  }

  async function present(e: BattleEvent): Promise<void> {
    hud.push(describeEvent(e));

    switch (e.t) {
      case 'battle_start':
        return;

      case 'roll': {
        shownDice = e.dice;
        shownAssign = {};
        render();
        await tray.rollAnimation(e.dice);
        render();
        return;
      }

      case 'triple_zero': {
        const mine = e.side === mySide;
        await tray.tripleZero();
        emitFx({
          type: 'triple_zero',
          payload: {
            body: mine
              ? 'Zero, zero, zero. The turn is forfeit and your guild has been told.'
              : `${e.playerName} rolled 0-0-0. Their whole turn is gone.`,
          },
        });
        const scenePower = scene ? scene.playEvent(e) : Promise.resolve();
        await cine.tripleZero(mine, e.playerName);
        await scenePower;
        tray.clearTripleZero();
        render();
        return;
      }

      case 'assign': {
        if (e.side === mySide) {
          render();
          return;
        }
        shownAssign = { ...shownAssign, [e.die]: e.unitId };
        render();
        await wait(reduced() ? 30 : 340);
        return;
      }

      case 'turn_start': {
        shownDice = null;
        shownAssign = {};
        autoPassing = false;
        selectedUnitId = null;
        mode = 'none';
        armedDie = null;
        tray.disarm();
        render();
        if (scene) await scene.playEvent(e);
        const mine = e.side === mySide;
        await flashTurn(
          mine ? 'YOUR TURN' : 'THEIR TURN',
          mine ? `TURN ${e.turn} — THE BOARD IS YOURS` : `TURN ${e.turn} — HOSTILE COMMAND ACTING`,
          mine ? 'you' : 'hostile',
        );
        return;
      }

      case 'attack': {
        emitFx({ type: e.killed ? 'unit_destroyed' : 'attack' });
        if (scene) await scene.playEvent(e);
        render();
        return;
      }

      case 'battle_end': {
        if (scene) await scene.playEvent(e);
        emitFx({
          type: 'battle_end',
          payload: {
            title: e.winner === mySide ? 'FIELD HELD' : 'FIELD LOST',
            body: `${e.reason.toUpperCase()} — ${currentBattle()?.boardName ?? ''}`,
            won: e.winner === mySide,
          },
        });
        return;
      }

      case 'deploy':
      case 'move':
      case 'teleport':
      case 'attack_wall':
      case 'brace':
      case 'hazard':
      case 'collapse':
      case 'obstacles_placed':
      case 'side_pick':
      case 'concede':
      case 'timeout_pass':
      case 'turn_end': {
        if (scene) await scene.playEvent(e);
        render();
        return;
      }

      default: {
        const never: never = e;
        throw new Error(`unhandled battle event ${JSON.stringify(never)}`);
      }
    }
  }

  async function flashTurn(title: string, detail: string, tone: 'you' | 'hostile'): Promise<void> {
    turnFlag.className = `turnflag is-${tone}`;
    turnFlag.replaceChildren(
      el('span', { class: 'turnflag__bar', aria: { hidden: 'true' } }),
      el('span', { class: 'turnflag__t display', text: title }),
      el('span', { class: 'turnflag__d mono', text: detail }),
    );
    void turnFlag.offsetWidth;
    turnFlag.classList.add('is-on');
    haptic(tone === 'you' ? [14, 30, 14] : 12);
    await wait(reduced() ? 140 : 1000);
    turnFlag.classList.remove('is-on');
    await wait(reduced() ? 20 : 260);
  }

  // ── deployment helpers ────────────────────────────────────────────────────

  function cloneBattle(b: BattleState): BattleState {
    return {
      ...b,
      grid: b.grid.map((row) => row.map((t) => ({ ...t }))),
      units: b.units.map((u) => ({ ...u })),
      assignments: { ...b.assignments },
      log: [],
      missedTimers: { ...b.missedTimers },
    };
  }

  function autoArrange(b: BattleState): Map<UnitId, { x: number; y: number }> {
    const clone = cloneBattle(b);
    autoDeploy(clone, mySide, makeRng(b.seed).fork(`ui-auto:${Date.now()}`));
    const out = new Map<UnitId, { x: number; y: number }>();
    for (const u of clone.units) {
      if (u.side !== mySide || !u.alive) continue;
      if (u.x < 0 || u.y < 0) continue;
      out.set(u.id, { x: u.x, y: u.y });
    }
    return out;
  }

  function seedPlacements(b: BattleState): void {
    const next = new Map<UnitId, { x: number; y: number }>();
    for (const u of b.units) {
      if (u.side !== mySide || !u.alive) continue;
      if (u.x < 0 || u.y < 0) continue;
      next.set(u.id, { x: u.x, y: u.y });
    }
    placements = next.size > 0 ? next : autoArrange(b);
  }

  function deployableTile(b: BattleState, x: number, y: number): boolean {
    const rows = new Set(deployRowsFor(b, mySide));
    if (!rows.has(y)) return false;
    const t = b.grid[y]?.[x];
    if (!t) return false;
    if (t.kind === 'obstacle') return false;
    if (t.kind === 'destructible' && (t.hp ?? 0) > 0) return false;
    if (t.kind === 'unstable' && t.collapsed === true) return false;
    return true;
  }

  function placeUnit(unitId: UnitId, x: number, y: number): void {
    const b = currentBattle();
    if (!b || b.phase !== 'deploy') return;
    if (!deployableTile(b, x, y)) {
      haptic([30, 20, 30]);
      toast({ title: 'INVALID TILE', body: 'That tile is outside your deployment band.', kind: 'warn' });
      return;
    }
    const unit = b.units.find((u) => u.id === unitId);
    if (!unit) return;
    if (unit.type && UNITS[unit.type].traits.includes('no_rough_end') && b.grid[y][x].kind === 'rough') {
      haptic([30, 20, 30]);
      toast({
        title: 'ROUGH GROUND',
        body: `${UNITS[unit.type].name} cannot settle on rough ground.`,
        kind: 'warn',
      });
      return;
    }

    const from = placements.get(unitId);
    let occupantId: UnitId | null = null;
    for (const [id, p] of placements) {
      if (id !== unitId && p.x === x && p.y === y) {
        occupantId = id;
        break;
      }
    }
    const next = new Map(placements);
    next.set(unitId, { x, y });
    if (occupantId) {
      if (from) next.set(occupantId, from);
      else next.delete(occupantId);
    }
    placements = next;
    heldUnitId = null;
    haptic([10, 20, 10]);
    render();
  }

  // ── selection & board input ───────────────────────────────────────────────

  function handleFriendlyTap(unitId: UnitId): void {
    const b = currentBattle();
    if (!b) return;
    const u = b.units.find((x) => x.id === unitId);
    if (!u || !u.alive) return;

    if (b.phase === 'deploy' && !hasDeployed(b, mySide)) {
      heldUnitId = heldUnitId === unitId ? null : unitId;
      render();
      return;
    }

    if (b.phase === 'assign' && b.turn === mySide) {
      const die = armedDie;
      if (die !== null) {
        if (dropTargets().has(unitId)) {
          armedDie = null;
          tray.disarm();
          void call(backend.assignDie(die, unitId), 'ASSIGN REJECTED');
        } else {
          haptic([30, 20, 30]);
          toast({ title: 'ONE DIE PER CHASSIS', body: 'That chassis already has a die.', kind: 'warn' });
        }
        return;
      }
    }

    selectedUnitId = selectedUnitId === unitId ? null : unitId;
    if (selectedUnitId === null) mode = 'none';
    else if (mode === 'attack' && !canFireAtAnything(b, u)) mode = 'none';
    scene?.focusTile(u.x, u.y);
    unitBar.revealSelected();
    render();
  }

  function handleHostileTap(unitId: UnitId): void {
    const b = currentBattle();
    if (!b) return;
    const target = b.units.find((x) => x.id === unitId);
    if (!target) return;

    const attacker = selectedUnit(b);
    if (
      mode === 'attack' &&
      attacker &&
      b.phase === 'acting' &&
      b.turn === mySide &&
      target.alive &&
      canAttack(b, attacker, target) &&
      attacker.ap > 0 &&
      attacker.attacksThisTurn < BATTLE.maxAttacksPerTurn
    ) {
      void call(backend.attack(attacker.id, target.id), 'ATTACK REJECTED');
      return;
    }
    scene?.focusTile(target.x, target.y);
    haptic(6);
  }

  function handleTileTap(x: number, y: number): void {
    const b = currentBattle();
    if (!b) return;

    if (b.phase === 'obstacle_place' && mySide === 'defender') {
      void call(backend.placeObstacle(x, y), 'BARRICADE REJECTED');
      return;
    }

    if (b.phase === 'deploy' && !hasDeployed(b, mySide)) {
      if (heldUnitId) {
        placeUnit(heldUnitId, x, y);
        return;
      }
      const occupant = [...placements.entries()].find(([, p]) => p.x === x && p.y === y);
      if (occupant) {
        heldUnitId = occupant[0];
        render();
      }
      return;
    }

    if (b.phase !== 'acting' || b.turn !== mySide) return;
    const u = selectedUnit(b);
    if (!u) return;

    if (mode === 'move') {
      if (u.ap <= 0) return;
      const reach = reachableTiles(b, u, 1);
      if (!reach.has(tileKey(x, y))) {
        haptic([26, 18, 26]);
        return;
      }
      void call(backend.moveUnit(u.id, x, y), 'MOVE REJECTED');
      return;
    }

    if (mode === 'attack') {
      const t = b.grid[y]?.[x];
      if (
        t &&
        t.kind === 'destructible' &&
        (t.hp ?? 0) > 0 &&
        battleDistance(u.x, u.y, x, y) <= effectiveRange(b, u) &&
        hasLineOfSight(b, u.x, u.y, x, y)
      ) {
        void call(backend.attackTile(u.id, x, y), 'ATTACK REJECTED');
      }
    }
  }

  function canFireAtAnything(b: BattleState, u: BattleUnit): boolean {
    return b.units.some((t) => t.alive && t.side !== u.side && canAttack(b, u, t));
  }

  function fireAt(t: AttackTarget): void {
    const b = currentBattle();
    const u = b ? selectedUnit(b) : null;
    if (!b || !u) return;
    if (t.kind === 'unit') void call(backend.attack(u.id, t.id), 'ATTACK REJECTED');
    else void call(backend.attackTile(u.id, t.x, t.y), 'ATTACK REJECTED');
  }

  // ── concede & outcome ─────────────────────────────────────────────────────

  function openConcede(): void {
    const b = currentBattle();
    if (!b || b.phase === 'ended') return;
    cine.concede(b, mySide, {
      onConfirm: () => void call(backend.concede(), 'CONCEDE REJECTED'),
      onCancel: () => render(),
    });
  }

  function showOutcome(b: BattleState): void {
    const won = b.winner === mySide;
    const lines: string[] = [];
    if (won) {
      lines.push(
        mySide === 'attacker' ? `HEX ${b.hexId} SEIZED` : `HEX ${b.hexId} HELD`,
      );
      lines.push('SURVIVORS KEEP THEIR CURRENT HP');
      if (b.endReason === 'concede') lines.push('THE HOSTILE ARMY WITHDREW ONE HEX');
    } else if (b.endReason === 'concede' || b.endReason === 'timeout') {
      lines.push('YOUR ARMY RETREATS ONE HEX');
      lines.push('EVERY SURVIVOR DROPS TO HALF HP');
    } else {
      lines.push('YOUR ARMY WAS DESTROYED');
      lines.push('NO SALVAGE — A WIPE RETURNS NOTHING');
    }

    const footnote =
      b.endReason === 'timeout'
        ? `Three missed turn timers is a disconnect and resolves as a concession.`
        : undefined;

    cine.outcome(b, mySide, { lines, footnote }, () => {
      render();
    });
  }

  // ── rendering ─────────────────────────────────────────────────────────────

  function trayMode(b: BattleState): TrayMode {
    if (b.phase === 'side_pick' || b.phase === 'obstacle_place' || b.phase === 'deploy') {
      return 'hidden';
    }
    if (b.phase === 'ended') return 'hidden';
    if (b.turn !== mySide) return 'enemy';
    if (b.phase === 'rolling') return 'await_roll';
    if (b.phase === 'assign') return 'assign';
    return 'acting';
  }

  function deployMode(b: BattleState): DeployMode | null {
    switch (b.phase) {
      case 'side_pick':
        return mySide === 'defender' ? 'side_pick' : 'wait';
      case 'obstacle_place':
        return mySide === 'defender' ? 'obstacle_place' : 'wait';
      case 'deploy':
        return hasDeployed(b, mySide) ? 'wait' : 'deploy';
      default:
        return null;
    }
  }

  function banner(b: BattleState): { text: string; detail: string; tone: BannerTone } {
    const mine = b.turn === mySide;
    switch (b.phase) {
      case 'side_pick':
        return mySide === 'defender'
          ? { text: 'CLAIM YOUR LINE', detail: 'Your fortification lets you choose an end of the board.', tone: 'setup' }
          : { text: 'DEFENDER IS CHOOSING GROUND', detail: 'Their fortification earns them the first decision.', tone: 'hostile' };
      case 'obstacle_place':
        return mySide === 'defender'
          ? {
              text: `SEAL ${b.obstaclesToPlace} TILE${b.obstaclesToPlace === 1 ? '' : 'S'}`,
              detail: 'Tap open neutral deck. Deployment bands are off limits.',
              tone: 'setup',
            }
          : { text: 'DEFENDER IS SEALING THE APPROACH', detail: 'Their Bastion is dropping barricades onto neutral ground.', tone: 'hostile' };
      case 'deploy':
        return hasDeployed(b, mySide)
          ? { text: 'LINE LOCKED', detail: 'Waiting on the hostile deployment.', tone: 'idle' }
          : { text: 'SET YOUR LINE', detail: `Place every chassis on your back ${BATTLE.deployRows} rows.`, tone: 'setup' };
      case 'rolling':
        return mine
          ? { text: 'ROLL THE DICE', detail: 'Three dice, 0–4 each. You assign them after you see them.', tone: 'you' }
          : { text: 'THEIR TURN', detail: 'Hostile command is rolling.', tone: 'hostile' };
      case 'assign':
        return mine
          ? { text: 'ASSIGN ACTION POINTS', detail: 'One die per chassis. Every die you leave loose is wasted.', tone: 'you' }
          : { text: 'THEIR TURN', detail: 'Hostile command is committing its dice.', tone: 'hostile' };
      case 'acting':
        return mine
          ? { text: 'SPEND YOUR ACTIONS', detail: 'Move, attack or brace — one action point each.', tone: 'you' }
          : { text: 'THEIR TURN', detail: 'Hostile chassis are acting.', tone: 'hostile' };
      case 'ended':
        return b.winner === mySide
          ? { text: 'FIELD HELD', detail: 'The engagement is resolved.', tone: 'you' }
          : { text: 'FIELD LOST', detail: 'The engagement is resolved.', tone: 'danger' };
      case 'intro':
        return { text: 'ESTABLISHING LINK', detail: 'Synchronising the tactical grid.', tone: 'idle' };
      default: {
        const never: never = b.phase;
        throw new Error(`unhandled phase ${String(never)}`);
      }
    }
  }

  function attackTargets(b: BattleState, u: BattleUnit): AttackTarget[] {
    const out: AttackTarget[] = [];
    for (const t of b.units) {
      if (!t.alive || t.side === u.side) continue;
      if (!canAttack(b, u, t)) continue;
      const { damage, mitigated } = computeDamage(b, u, t);
      out.push({
        kind: 'unit',
        id: t.id,
        type: t.type,
        label: unitLabel(t),
        hp: t.hp,
        maxHp: t.maxHp,
        damage,
        mitigated,
        kill: damage >= t.hp,
        x: t.x,
        y: t.y,
      });
    }
    const range = effectiveRange(b, u);
    const wallDamage = UNITS[u.type].atk;
    for (let y = 0; y < b.h; y++) {
      for (let x = 0; x < b.w; x++) {
        const t = b.grid[y][x];
        if (t.kind !== 'destructible' || (t.hp ?? 0) <= 0) continue;
        if (battleDistance(u.x, u.y, x, y) > range) continue;
        if (!hasLineOfSight(b, u.x, u.y, x, y)) continue;
        out.push({
          kind: 'wall',
          x,
          y,
          damage: wallDamage,
          hp: t.hp ?? 0,
          destroyed: wallDamage >= (t.hp ?? 0),
        });
      }
    }
    out.sort((a, bb) => {
      const ak = a.kind === 'unit' && a.kill ? 0 : 1;
      const bk = bb.kind === 'unit' && bb.kill ? 0 : 1;
      if (ak !== bk) return ak - bk;
      return bb.damage - a.damage;
    });
    return out;
  }

  function highlights(b: BattleState): BattleHighlights {
    const h: BattleHighlights = { moves: [], attacks: [] };

    if (b.phase === 'deploy' && !hasDeployed(b, mySide)) {
      for (let y = 0; y < b.h; y++) {
        for (let x = 0; x < b.w; x++) {
          if (deployableTile(b, x, y)) h.moves.push({ x, y });
        }
      }
      const held = heldUnitId ? placements.get(heldUnitId) : undefined;
      if (held) h.selected = { x: held.x, y: held.y };
      return h;
    }

    if (b.phase === 'obstacle_place' && mySide === 'defender') {
      // Straight from the engine, so the 3D board never lights up a tile that
      // would be refused for cutting the board in half.
      for (const spot of obstacleSpots(b)) h.attacks.push(spot);
      return h;
    }

    // A die in the hand lights up every chassis that can still take one.
    const armed = dragDie !== null ? dragDie : armedDie;
    if (armed !== null && b.phase === 'assign' && b.turn === mySide) {
      const targets = dropTargets();
      for (const u of myUnits(b)) {
        if (u.alive && targets.has(u.id)) h.moves.push({ x: u.x, y: u.y });
      }
      return h;
    }

    const u = selectedUnit(b);
    if (!u) return h;
    h.selected = { x: u.x, y: u.y };

    if (b.phase === 'acting' && b.turn === mySide) {
      if (mode === 'move' && u.ap > 0) {
        for (const node of reachableTiles(b, u, 1).values()) {
          h.moves.push({ x: node.x, y: node.y });
        }
      } else if (mode === 'attack') {
        for (const t of attackTargets(b, u)) h.attacks.push({ x: t.x, y: t.y });
      }
    }
    return h;
  }

  /** The battle as the player should currently see it (local deploy edits win). */
  function presented(b: BattleState): BattleState {
    if (b.phase !== 'deploy' || placements.size === 0 || hasDeployed(b, mySide)) return b;
    return {
      ...b,
      units: b.units.map((u) => {
        if (u.side !== mySide) return u;
        const p = placements.get(u.id);
        return p ? { ...u, x: p.x, y: p.y } : u;
      }),
    };
  }

  function render(): void {
    if (!mounted) return;
    const b = currentBattle();
    if (!b) return;

    const mineTurn = b.turn === mySide;
    const rollingSide = b.turn;
    const livingOnTurn = b.units.filter((u) => u.side === rollingSide && u.alive).length;

    // HUD
    const bn = banner(b);
    hud.sync({
      battle: b,
      mySide,
      myGuild: guildOf(mySide === 'attacker' ? b.attacker.guildId : b.defender.guildId),
      foeGuild: guildOf(mySide === 'attacker' ? b.defender.guildId : b.attacker.guildId),
      instruction: bn.text,
      detail: bn.detail,
      tone: bn.tone,
    });

    // Setup panel
    const dm = deployMode(b);
    setupHost.classList.toggle('is-on', dm !== null);
    lower.classList.toggle('is-setup', dm !== null);
    if (dm !== null) {
      if (dm === 'deploy') {
        const key = `${b.id}|${b.bottomSide}`;
        if (placementKey !== key) {
          placementKey = key;
          seedPlacements(b);
        }
      }
      deployPanel.sync({
        mode: dm,
        battle: b,
        mySide,
        placements,
        held: heldUnitId,
        busy,
        waitTitle:
          b.phase === 'side_pick'
            ? 'DEFENDER IS CHOOSING GROUND'
            : b.phase === 'obstacle_place'
              ? 'DEFENDER IS SEALING TILES'
              : 'LINE LOCKED',
        waitDetail:
          b.phase === 'deploy'
            ? 'Your deployment is committed. Waiting on the hostile line.'
            : 'Their fortification buys them the first move of the engagement.',
      });
    }

    // Dice tray
    const trayState: DiceTrayState = {
      mode: trayMode(b),
      dice: shownDice,
      assignments: mineTurn ? b.assignments : shownAssign,
      livingUnits: livingOnTurn,
      ownerLabel: mineTurn
        ? 'YOU'
        : (mySide === 'attacker' ? b.defender.playerName : b.attacker.playerName).toUpperCase(),
      busy,
    };
    tray.sync(trayState);

    // Rosters
    const pending = new Map<UnitId, { die: DieIndex; value: number }>();
    if (shownDice) {
      const src = mineTurn ? b.assignments : shownAssign;
      for (const die of [0, 1, 2] as DieIndex[]) {
        const id = src[die];
        if (id !== undefined) pending.set(id, { die, value: shownDice[die] });
      }
    }
    const sel = selectedUnit(b);
    const threats = new Set<UnitId>();
    if (sel && mode === 'attack' && b.phase === 'acting' && mineTurn) {
      for (const t of attackTargets(b, sel)) {
        if (t.kind === 'unit') threats.add(t.id);
      }
    }
    const foeName = mySide === 'attacker' ? b.defender : b.attacker;
    const meName = mySide === 'attacker' ? b.attacker : b.defender;
    unitBar.sync({
      mine: myUnits(b),
      enemy: foeUnits(b),
      selectedId: selectedUnitId ?? heldUnitId ?? undefined,
      dropTargets: dropTargets(),
      dropping: (dragDie !== null || armedDie !== null) && b.phase === 'assign' && mineTurn,
      threatTargets: threats,
      showAp: b.phase === 'acting' || b.phase === 'assign',
      dice: shownDice,
      pending,
      myLabel: `${meName.playerName} [${meName.guildTag}]`,
      enemyLabel: `${foeName.playerName} [${foeName.guildTag}]`,
      myColor: `#${(meName.guildColor >>> 0).toString(16).padStart(6, '0')}`,
      enemyColor: `#${((foeName.guildColor === meName.guildColor ? 0xff4d5e : foeName.guildColor) >>> 0)
        .toString(16)
        .padStart(6, '0')}`,
    });
    unitBar.el.classList.toggle('is-hidden', dm !== null || b.phase === 'ended');

    // Action bar
    const acting = b.phase === 'acting' && mineTurn;
    const reach = sel && acting ? reachableTiles(b, sel, 1).size : 0;
    const targets = sel && acting ? attackTargets(b, sel) : [];
    const attacksLeft = sel ? Math.max(0, BATTLE.maxAttacksPerTurn - sel.attacksThisTurn) : 0;
    actionBar.sync({
      unit: sel,
      dieValue: sel && sel.die !== undefined && b.dice ? b.dice[sel.die] : (sel?.ap ?? 0),
      mode,
      move: !acting
        ? { ok: false, reason: 'NOT YOUR ACTION PHASE' }
        : !sel
          ? { ok: false, reason: 'NO CHASSIS' }
          : sel.ap <= 0
            ? { ok: false, reason: 'NO ACTION POINTS' }
            : reach === 0
              ? { ok: false, reason: 'BOXED IN' }
              : { ok: true, reason: '' },
      attack: !acting
        ? { ok: false, reason: 'NOT YOUR ACTION PHASE' }
        : !sel
          ? { ok: false, reason: 'NO CHASSIS' }
          : sel.ap <= 0
            ? { ok: false, reason: 'NO ACTION POINTS' }
            : sel.attacksThisTurn >= BATTLE.maxAttacksPerTurn
              ? { ok: false, reason: `FIRE LIMIT ${BATTLE.maxAttacksPerTurn}/TURN` }
              : targets.length === 0
                ? { ok: false, reason: 'NO FIRING SOLUTION' }
                : { ok: true, reason: '' },
      brace: !acting
        ? { ok: false, reason: 'NOT YOUR ACTION PHASE' }
        : !sel
          ? { ok: false, reason: 'NO CHASSIS' }
          : sel.ap <= 0
            ? { ok: false, reason: 'NO ACTION POINTS' }
            : sel.braced
              ? { ok: false, reason: 'ALREADY BRACED' }
              : { ok: true, reason: '' },
      reachCount: reach,
      targets,
      attacksLeft,
      busy,
      hidden: dm !== null || b.phase === 'ended' || !mineTurn,
    });

    // 3D layer — only while nothing is mid-animation, so a queued move is never
    // snapped to its destination before its animation has played.
    if (scene && queueDepth === 0) {
      scene.sync(presented(b), view.get());
      scene.setHighlights(highlights(b));
    }
    updateInsets();
  }

  // ── viewport insets so the whole grid stays visible ───────────────────────

  function updateInsets(): void {
    if (!scene) return;
    const h = root.clientHeight || 844;
    const top = hud.el.offsetHeight || 0;
    const bottom = setupHost.classList.contains('is-on')
      ? setupHost.offsetHeight || 0
      : lower.offsetHeight || 0;
    scene.setSafeInsets({
      top: Math.min(0.42, top / h + 0.02),
      bottom: Math.min(0.62, bottom / h + 0.02),
      // At the default framing on a portrait phone it is the board's WIDTH that
      // binds the fit solve, not the vertical band — so this number, not the
      // chrome heights, is what decides how big the board reads. 0.05 a side
      // was 10% of the viewport spent on nothing, on top of the camera's own
      // `fitMargin`. The chrome is drawn over the board's top and bottom, never
      // its flanks, so the sides do not need the same slack.
      side: 0.03,
    });
  }

  // ── state pump ────────────────────────────────────────────────────────────

  function onState(s: GameState): void {
    live = s;
    pushedAt = performance.now();
    const b = s.battle;
    if (!b) return;

    if (b.id !== battleId) {
      battleId = b.id;
      played = 0;
      outcomeShown = false;
      introRun = false;
      coachOffered = false;
      shownDice = null;
      shownAssign = {};
      selectedUnitId = null;
      heldUnitId = null;
      placementKey = '';
      placements = new Map();
      mode = 'none';
      armedDie = null;
      dragDie = null;
      autoPassing = false;
      cine.clear();
      hud.resetLog();
      tray.clearTripleZero();
      mySide = resolveSide(b, s);

      if (scene) {
        scene.sync(b, view.get());
        scene.setHighlights({ moves: [], attacks: [] });
      }

      // Joining a battle already in progress (reload / late attach): skip the
      // backlog rather than replay ten minutes of animation.
      if (b.log.length > 4) {
        for (const e of b.log) hud.push(describeEvent(e));
        played = b.log.length;
        introRun = true;
      }
    }

    mySide = resolveSide(b, s);

    if (!introRun) {
      introRun = true;
      enqueue(async () => {
        const sweep = scene ? scene.intro() : Promise.resolve();
        await Promise.all([cine.intro(b, mySide), sweep]);
      });
    }

    // First-battle coach (GDD §13 step 8). Offered during DEPLOYMENT, never
    // during a turn: the battle cannot advance past deployment without this
    // player, so there is no clock running behind the reading. Queued, so it
    // lands after the intro cinematic rather than over the top of it.
    if (!coachOffered && b.phase === 'deploy' && !hasDeployed(b, mySide) && !coachSeen()) {
      coachOffered = true;
      enqueue(
        () =>
          new Promise<void>((resolve) => {
            const handle = openBattleCoach({ manual: false, onClose: () => resolve() });
            if (!handle) resolve();
          }),
      );
    }

    if (b.log.length > played) {
      const fresh = b.log.slice(played);
      played = b.log.length;
      for (const e of fresh) enqueue(() => present(e));
    }

    render();
  }

  // ── screen contract ───────────────────────────────────────────────────────

  return {
    el: root,

    mount(): void {
      if (mounted) return;
      mounted = true;
      outcomeShown = false;

      scene = new BattleScene(sceneHost);
      scene.onTileTap((x, y) => handleTileTap(x, y));
      scene.onUnitTap((id) => {
        const b = currentBattle();
        if (!b) return;
        const u = b.units.find((x) => x.id === id);
        if (!u) return;
        if (u.side === mySide) handleFriendlyTap(id);
        else handleHostileTap(id);
      });

      disposer.listen(root, 'pointerdown', () => cue.arm(), { once: true });
      disposer.add(game.subscribe((s) => {
        if (s) onState(s);
      }));
      disposer.add(view.subscribe(() => render()));

      if (typeof ResizeObserver !== 'undefined') {
        const ro = new ResizeObserver(() => updateInsets());
        ro.observe(lower);
        ro.observe(setupHost);
        ro.observe(hud.el);
        disposer.add(() => ro.disconnect());
      }
      disposer.listen(window, 'resize', () => updateInsets());

      battleId = '';
      const s = game.get();
      if (s) onState(s);
      updateInsets();
    },

    unmount(): void {
      if (!mounted) return;
      mounted = false;
      disposer.dispose();
      cine.clear();
      tray.clearTripleZero();
      scene?.dispose();
      scene = null;
      live = null;
      battleId = '';
      played = 0;
      queue = Promise.resolve();
      queueDepth = 0;
      selectedUnitId = null;
      heldUnitId = null;
      mode = 'none';
      armedDie = null;
      dragDie = null;
      turnFlag.classList.remove('is-on');
      cue.dispose();
    },

    frame(): void {
      const b = currentBattle();
      if (!b) return;
      const combat =
        b.phase === 'rolling' || b.phase === 'assign' || b.phase === 'acting';
      const liveClock = combat && !cine.live;
      const remaining = b.turnEndsAt - nowMs();
      hud.setTimer(remaining, BATTLE.turnMs, liveClock);

      if (
        liveClock &&
        b.turn === mySide &&
        remaining <= 0 &&
        !autoPassing &&
        !busy &&
        queueDepth === 0
      ) {
        autoPassing = true;
        toast({
          title: 'CLOCK EXPIRED',
          body: 'The turn auto-passed. Three missed timers in a row resolves as a concession.',
          kind: 'warn',
        });
        // Must be `timeoutPass`, never `endTurn`. `endTurn` is a deliberate act
        // and clears the missed-timer tally, so auto-passing through it would
        // quietly make the disconnect rule (GDD §7.3) unreachable — while this
        // very toast promises the player it is being enforced.
        void call(backend.timeoutPass(), 'AUTO-PASS FAILED');
      }
    },
  };
}
