/**
 * TERRA BELLUM — tactical board geometry (GDD §7.1, §12.3).
 *
 * Builds the 6×6 … 8×8 battle grid from `BattleState.grid`. Every TileKind gets
 * its own silhouette + emissive language so the board reads instantly on a
 * 390px-wide phone: floor plates with holo seams, jagged obstacles, scree,
 * barricades, hazard vents, teleport pads, cracked walls, raised platforms and
 * flickering unstable plating.
 *
 * Everything is instanced — one draw call per tile family — and every colour is
 * derived from `config/visual` PALETTE, every rule number from `config/balance`.
 *
 * SHADER NOTE: fragment shaders here must NOT `#include
 * <colorspace_pars_fragment>`. three's WebGLProgram injects that chunk into
 * every non-raw ShaderMaterial's fragment prefix unconditionally, so including
 * it again redefines LinearTransferOETF / sRGBTransferEOTF / sRGBTransferOETF
 * and the shader fails to link — silently, as an invisible mesh. `#include
 * <colorspace_fragment>` (the statement, not the pars) is still required.
 */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { BattleState, Tile, TileKind } from '../../game/types';
import { BATTLE } from '../../config/balance';
import { BATTLE_VIEW, PALETTE } from '../../config/visual';
import { makeHoloLineMaterial, makeEnergyFieldMaterial } from '../core/materials';
import { InstancedBatch, buildRibbon, lightColumnGeometry } from '../core/geometry';

// ─────────────────────────────────────────────────────────────────────────────
// Board metrics
// ─────────────────────────────────────────────────────────────────────────────

export const TILE_PITCH = BATTLE_VIEW.tileSize + BATTLE_VIEW.tileGap;
export const PLATE_H = BATTLE_VIEW.tileHeight;
export const ELEVATION_RISE = BATTLE_VIEW.tileHeight * 2.5;
export const BLOCK_H = BATTLE_VIEW.obstacleHeight;
export const WALL_H = BATTLE_VIEW.obstacleHeight * 0.72;
export const COVER_H = BATTLE_VIEW.obstacleHeight * 0.34;
/** How far above its tile a gravitic chassis floats. */
export const HOVER_H = BATTLE_VIEW.tileSize * 0.42;

export const tileWorldX = (x: number, w: number): number => (x - (w - 1) / 2) * TILE_PITCH;
export const tileWorldZ = (y: number, h: number): number => (y - (h - 1) / 2) * TILE_PITCH;

/** Deterministic per-tile jitter so the board never looks stamped. */
export function tileHash(x: number, y: number, salt: number): number {
  let n = (x * 374761393 + y * 668265263 + salt * 1274126177) | 0;
  n = Math.imul(n ^ (n >>> 13), 1274126177);
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared "hull" shader — the material language of the whole battle layer.
// Custom lit shader (no default Three.js look): key/fill/rim + holo seam grid +
// scanlines + emissive trim + a global desaturation channel for the 0-0-0
// cinematic (GDD §7.2).
// ─────────────────────────────────────────────────────────────────────────────

const HULL_VERT = /* glsl */ `
#ifdef USE_INSTANCING
attribute vec3 aTint;
attribute vec4 aParam;
#endif
uniform vec3 uTint;
uniform vec4 uParam;
uniform float uReveal;
varying vec3 vN;
varying vec3 vW;
varying vec3 vL;
varying vec3 vTint;
varying vec4 vP;

void main() {
  vec3 p = position;
  vec3 n = normal;
  #ifdef USE_INSTANCING
    vTint = aTint;
    vP = aParam;
    p = (instanceMatrix * vec4(p, 1.0)).xyz;
    n = mat3(instanceMatrix) * n;
  #else
    vTint = uTint;
    vP = uParam;
  #endif
  vL = position;
  float rv = clamp(uReveal * 2.1 - vP.y * 1.1, 0.0, 1.0);
  rv = rv * rv * (3.0 - 2.0 * rv);
  p.y -= (1.0 - rv) * 2.2;
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vW = wp.xyz;
  vN = normalize(mat3(modelMatrix) * n);
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const HULL_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>

uniform float uTime;
uniform float uDrain;
uniform float uOpacity;
uniform float uSeam;
uniform float uSeamScale;
uniform float uScan;
uniform float uFresnel;
uniform vec3 uAmbient;
uniform vec3 uKeyDir;
uniform vec3 uKeyColor;
uniform vec3 uFillDir;
uniform vec3 uFillColor;
uniform vec3 uRimColor;
uniform vec3 uEmissive;

varying vec3 vN;
varying vec3 vW;
varying vec3 vL;
varying vec3 vTint;
varying vec4 vP;

float bar(float v, float w) { return 1.0 - smoothstep(0.0, w, abs(v)); }

void main() {
  vec3 N = normalize(vN);
  vec3 V = normalize(cameraPosition - vW);
  float emi = vP.x;
  float phase = vP.y;
  float dmg = clamp(vP.z, 0.0, 1.0);
  float flash = clamp(vP.w, 0.0, 1.0);

  vec3 tint = mix(vTint, vTint * 0.18, dmg * 0.85);

  float key = max(dot(N, uKeyDir), 0.0);
  float fill = max(dot(N, uFillDir), 0.0);
  float rim = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.6) * uFresnel;

  vec3 col = tint * (uAmbient + uKeyColor * key + uFillColor * fill * 0.62);
  vec3 H = normalize(uKeyDir + V);
  col += uKeyColor * pow(max(dot(N, H), 0.0), 46.0) * 0.32;
  col += uRimColor * rim * 0.75;

  // holographic seam lattice, top faces only
  float top = smoothstep(0.45, 0.94, N.y);
  vec2 g = fract(vW.xz * uSeamScale + 0.5) - 0.5;
  float seam = max(bar(g.x, 0.045), bar(g.y, 0.045));
  float pulse = 0.6 + 0.4 * sin(uTime * 1.6 - vW.x * 0.7 - vW.z * 0.5);
  col += uEmissive * seam * top * uSeam * pulse;

  // faint holo checker
  float chk = mod(floor(vW.x * uSeamScale) + floor(vW.z * uSeamScale), 2.0);
  col += uEmissive * top * chk * uSeam * 0.16 * (0.7 + 0.3 * sin(uTime * 0.9 + phase * 6.2831));

  // emissive trim / crack glow
  col += uEmissive * emi * (0.78 + 0.22 * sin(uTime * 2.6 + phase * 6.2831));

  // damage cracks widen with damage
  if (dmg > 0.01) {
    float cx = bar(fract(vL.x * 3.1 + vL.y * 1.7 + phase) - 0.5, 0.06 + dmg * 0.16);
    col += uEmissive * cx * dmg * 1.6;
  }

  // console scanlines
  col *= 1.0 - uScan * (0.5 + 0.5 * sin(vW.y * 78.0 - uTime * 2.4));

  col = mix(col, vec3(2.6, 2.7, 3.0), flash);

  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, vec3(lum) * vec3(0.80, 0.86, 1.0) * 0.82, uDrain);

  gl_FragColor = vec4(col, uOpacity);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export interface HullOptions {
  tint?: number;
  emissive?: number;
  emissiveMul?: number;
  seam?: number;
  seamScale?: number;
  scan?: number;
  fresnel?: number;
  opacity?: number;
  transparent?: boolean;
  depthWrite?: boolean;
  side?: THREE.Side;
}

export interface HullEnvironment {
  ambient: THREE.ColorRepresentation;
  key: THREE.ColorRepresentation;
  fill: THREE.ColorRepresentation;
  rim: THREE.ColorRepresentation;
}

const hulls = new Set<THREE.ShaderMaterial>();
const envAmbient = new THREE.Color(0x141d2e);
const envKey = new THREE.Color(0x7fc6ff);
const envFill = new THREE.Color(0x2b3f6b);
const envRim = new THREE.Color(PALETTE.cyan);

export function makeHullMaterial(o: HullOptions = {}): THREE.ShaderMaterial {
  const m = new THREE.ShaderMaterial({
    vertexShader: HULL_VERT,
    fragmentShader: HULL_FRAG,
    transparent: o.transparent ?? false,
    depthWrite: o.depthWrite ?? true,
    side: o.side ?? THREE.FrontSide,
    uniforms: {
      uTime: { value: 0 },
      uDrain: { value: 0 },
      uReveal: { value: 1 },
      uOpacity: { value: o.opacity ?? 1 },
      uSeam: { value: o.seam ?? 0 },
      uSeamScale: { value: o.seamScale ?? 1 / TILE_PITCH },
      uScan: { value: o.scan ?? 0.05 },
      uFresnel: { value: o.fresnel ?? 1 },
      uAmbient: { value: envAmbient.clone() },
      uKeyDir: { value: new THREE.Vector3(0.42, 0.83, 0.36).normalize() },
      uKeyColor: { value: envKey.clone() },
      uFillDir: { value: new THREE.Vector3(-0.55, 0.28, -0.72).normalize() },
      uFillColor: { value: envFill.clone() },
      uRimColor: { value: envRim.clone() },
      uEmissive: { value: new THREE.Color(o.emissive ?? PALETTE.cyan) },
      uTint: { value: new THREE.Color(o.tint ?? PALETTE.plate) },
      uParam: { value: new THREE.Vector4(o.emissiveMul ?? 0, 0, 0, 0) },
    },
  });
  hulls.add(m);
  return m;
}

/** Push the frame clock + the 0-0-0 colour-drain amount into every hull shader. */
export function updateHulls(time: number, drain: number): void {
  for (const m of hulls) {
    m.uniforms.uTime.value = time;
    m.uniforms.uDrain.value = drain;
  }
}

/** Terrain-tinted ambient light for the whole battle layer (GDD §7.1 templates). */
export function setHullEnvironment(env: HullEnvironment): void {
  envAmbient.set(env.ambient);
  envKey.set(env.key);
  envFill.set(env.fill);
  envRim.set(env.rim);
  for (const m of hulls) {
    (m.uniforms.uAmbient.value as THREE.Color).copy(envAmbient);
    (m.uniforms.uKeyColor.value as THREE.Color).copy(envKey);
    (m.uniforms.uFillColor.value as THREE.Color).copy(envFill);
    (m.uniforms.uRimColor.value as THREE.Color).copy(envRim);
  }
}

export function disposeHull(m: THREE.ShaderMaterial): void {
  hulls.delete(m);
  m.dispose();
}

// ─────────────────────────────────────────────────────────────────────────────
// Glyph atlas — shield / arrow / hatch / pips / crack, drawn once to a canvas
// and sampled by one instanced quad mesh (a single draw call for every decal).
// ─────────────────────────────────────────────────────────────────────────────

export const GLYPH = {
  shield: 0,
  arrow: 1,
  hatch: 2,
  warning: 3,
  pips0: 4,
  pips1: 5,
  pips2: 6,
  teleport: 7,
  crack: 8,
  bracket: 9,
  crosshair: 10,
  chevrons: 11,
} as const;

const GLYPH_COLS = 4;
const GLYPH_CELL = 128;
let glyphTexture: THREE.CanvasTexture | null = null;

function drawGlyphCell(ctx: CanvasRenderingContext2D, index: number): void {
  const cx = (index % GLYPH_COLS) * GLYPH_CELL;
  const cy = Math.floor(index / GLYPH_COLS) * GLYPH_CELL;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.strokeStyle = '#ffffff';
  ctx.fillStyle = '#ffffff';
  ctx.lineWidth = 7;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  const C = GLYPH_CELL / 2;

  switch (index) {
    case GLYPH.shield: {
      ctx.beginPath();
      ctx.moveTo(C, 20);
      ctx.lineTo(C + 34, 38);
      ctx.lineTo(C + 34, 70);
      ctx.quadraticCurveTo(C + 34, 96, C, 110);
      ctx.quadraticCurveTo(C - 34, 96, C - 34, 70);
      ctx.lineTo(C - 34, 38);
      ctx.closePath();
      ctx.stroke();
      ctx.globalAlpha = 0.32;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(C - 14, C + 2);
      ctx.lineTo(C - 2, C + 16);
      ctx.lineTo(C + 17, C - 12);
      ctx.stroke();
      break;
    }
    case GLYPH.arrow: {
      ctx.beginPath();
      ctx.moveTo(C - 32, C + 16);
      ctx.lineTo(C, C - 24);
      ctx.lineTo(C + 32, C + 16);
      ctx.stroke();
      ctx.globalAlpha = 0.55;
      ctx.beginPath();
      ctx.moveTo(C - 32, C + 42);
      ctx.lineTo(C, C + 2);
      ctx.lineTo(C + 32, C + 42);
      ctx.stroke();
      ctx.globalAlpha = 1;
      break;
    }
    case GLYPH.hatch: {
      ctx.lineWidth = 9;
      ctx.globalAlpha = 0.7;
      for (let i = -3; i <= 6; i++) {
        ctx.beginPath();
        ctx.moveTo(i * 24 - 10, 8);
        ctx.lineTo(i * 24 + 100, 120);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      ctx.lineWidth = 6;
      ctx.strokeRect(12, 12, GLYPH_CELL - 24, GLYPH_CELL - 24);
      break;
    }
    case GLYPH.warning: {
      ctx.beginPath();
      ctx.moveTo(C, 18);
      ctx.lineTo(C + 46, 104);
      ctx.lineTo(C - 46, 104);
      ctx.closePath();
      ctx.stroke();
      ctx.lineWidth = 10;
      ctx.beginPath();
      ctx.moveTo(C, 48);
      ctx.lineTo(C, 78);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(C, 92, 5, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case GLYPH.pips0:
    case GLYPH.pips1:
    case GLYPH.pips2: {
      const filled = index - GLYPH.pips0;
      for (let i = 0; i < 2; i++) {
        const px = C - 26 + i * 52;
        ctx.beginPath();
        ctx.moveTo(px, C - 22);
        ctx.lineTo(px + 20, C);
        ctx.lineTo(px, C + 22);
        ctx.lineTo(px - 20, C);
        ctx.closePath();
        if (i < filled) ctx.fill();
        else ctx.stroke();
      }
      break;
    }
    case GLYPH.teleport: {
      ctx.lineWidth = 6;
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI * 2;
        const r0 = 30;
        const r1 = 52;
        ctx.beginPath();
        ctx.moveTo(C + Math.cos(a) * r0, C + Math.sin(a) * r0);
        ctx.lineTo(C + Math.cos(a + 0.28) * r1, C + Math.sin(a + 0.28) * r1);
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.arc(C, C, 18, 0, Math.PI * 2);
      ctx.stroke();
      break;
    }
    case GLYPH.crack: {
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.moveTo(20, 16);
      ctx.lineTo(52, 54);
      ctx.lineTo(34, 74);
      ctx.lineTo(70, 112);
      ctx.stroke();
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(52, 54);
      ctx.lineTo(96, 40);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(34, 74);
      ctx.lineTo(8, 96);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(70, 112);
      ctx.lineTo(112, 92);
      ctx.stroke();
      break;
    }
    case GLYPH.bracket: {
      ctx.lineWidth = 9;
      const m = 16;
      const l = 34;
      const pts: [number, number, number, number][] = [
        [m, m + l, m, m],
        [m, m, m + l, m],
        [GLYPH_CELL - m, GLYPH_CELL - m - l, GLYPH_CELL - m, GLYPH_CELL - m],
        [GLYPH_CELL - m, GLYPH_CELL - m, GLYPH_CELL - m - l, GLYPH_CELL - m],
        [GLYPH_CELL - m - l, m, GLYPH_CELL - m, m],
        [GLYPH_CELL - m, m, GLYPH_CELL - m, m + l],
        [m, GLYPH_CELL - m - l, m, GLYPH_CELL - m],
        [m, GLYPH_CELL - m, m + l, GLYPH_CELL - m],
      ];
      for (const p of pts) {
        ctx.beginPath();
        ctx.moveTo(p[0], p[1]);
        ctx.lineTo(p[2], p[3]);
        ctx.stroke();
      }
      break;
    }
    case GLYPH.crosshair: {
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.arc(C, C, 36, 0.35, Math.PI / 2 - 0.35);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(C, C, 36, Math.PI / 2 + 0.35, Math.PI - 0.35);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(C, C, 36, Math.PI + 0.35, Math.PI * 1.5 - 0.35);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(C, C, 36, Math.PI * 1.5 + 0.35, Math.PI * 2 - 0.35);
      ctx.stroke();
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(C - 54, C);
      ctx.lineTo(C - 40, C);
      ctx.moveTo(C + 40, C);
      ctx.lineTo(C + 54, C);
      ctx.moveTo(C, C - 54);
      ctx.lineTo(C, C - 40);
      ctx.moveTo(C, C + 40);
      ctx.lineTo(C, C + 54);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(C, C, 6, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case GLYPH.chevrons: {
      ctx.lineWidth = 8;
      for (let i = 0; i < 3; i++) {
        ctx.globalAlpha = 1 - i * 0.28;
        ctx.beginPath();
        ctx.moveTo(C - 30, C + 6 + i * 24);
        ctx.lineTo(C, C - 18 + i * 24);
        ctx.lineTo(C + 30, C + 6 + i * 24);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      break;
    }
    default:
      break;
  }
  ctx.restore();
}

export function getGlyphAtlas(): THREE.CanvasTexture {
  if (glyphTexture) return glyphTexture;
  const size = GLYPH_COLS * GLYPH_CELL;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.clearRect(0, 0, size, size);
    for (let i = 0; i < 12; i++) drawGlyphCell(ctx, i);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  tex.needsUpdate = true;
  glyphTexture = tex;
  return tex;
}

// ─────────────────────────────────────────────────────────────────────────────
// Small geometry helpers
// ─────────────────────────────────────────────────────────────────────────────

function mergeParts(parts: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const flat: THREE.BufferGeometry[] = [];
  for (const p of parts) flat.push(p.index ? p.toNonIndexed() : p);
  const merged = mergeGeometries(flat, false);
  for (let i = 0; i < flat.length; i++) {
    if (flat[i] !== parts[i]) flat[i].dispose();
    parts[i].dispose();
  }
  merged.computeVertexNormals();
  return merged;
}

function roundedRect(size: number, r: number): THREE.Shape {
  const h = size / 2;
  const s = new THREE.Shape();
  s.moveTo(-h + r, -h);
  s.lineTo(h - r, -h);
  s.quadraticCurveTo(h, -h, h, -h + r);
  s.lineTo(h, h - r);
  s.quadraticCurveTo(h, h, h - r, h);
  s.lineTo(-h + r, h);
  s.quadraticCurveTo(-h, h, -h, h - r);
  s.lineTo(-h, -h + r);
  s.quadraticCurveTo(-h, -h, -h, -h + r);
  return s;
}

/** Bevelled plate: the base unit of the whole board. */
function makePlateGeometry(size: number, height: number, bevel: number): THREE.BufferGeometry {
  const shape = roundedRect(size - bevel * 2, size * 0.09);
  const g = new THREE.ExtrudeGeometry(shape, {
    depth: Math.max(0.002, height - bevel * 2),
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 1,
    curveSegments: 2,
    steps: 1,
  });
  g.rotateX(-Math.PI / 2);
  g.translate(0, bevel, 0);
  g.computeVertexNormals();
  return g;
}

function makeJaggedBlock(size: number, height: number): THREE.BufferGeometry {
  const a = new THREE.BoxGeometry(size * 0.74, height, size * 0.68);
  a.rotateY(0.18);
  a.translate(0, height * 0.5, 0);
  const b = new THREE.BoxGeometry(size * 0.5, height * 0.78, size * 0.82);
  b.rotateY(-0.52);
  b.translate(size * 0.06, height * 0.39, -size * 0.05);
  const c = new THREE.ConeGeometry(size * 0.36, height * 0.46, 5, 1);
  c.rotateZ(0.14);
  c.rotateY(0.7);
  c.translate(-size * 0.06, height * 1.02, size * 0.05);
  const d = new THREE.BoxGeometry(size * 0.28, height * 0.3, size * 0.28);
  d.rotateY(0.9);
  d.rotateZ(0.28);
  d.translate(size * 0.24, height * 0.14, size * 0.2);
  return mergeParts([a, b, c, d]);
}

function makeScree(size: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  for (let i = 0; i < 6; i++) {
    const s = size * (0.09 + (i % 3) * 0.035);
    const g = new THREE.DodecahedronGeometry(s, 0);
    g.rotateY(i * 1.1);
    g.rotateX(i * 0.7);
    const a = (i / 6) * Math.PI * 2 + 0.4;
    const r = size * (0.16 + (i % 2) * 0.14);
    g.translate(Math.cos(a) * r, s * 0.45, Math.sin(a) * r);
    parts.push(g);
  }
  return mergeParts(parts);
}

function makeBarricade(size: number, height: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const wall = new THREE.BoxGeometry(size * 0.82, height, size * 0.17);
  wall.translate(0, height * 0.5, -size * 0.3);
  parts.push(wall);
  for (let i = -1; i <= 1; i++) {
    const post = new THREE.BoxGeometry(size * 0.09, height * 1.24, size * 0.1);
    post.translate(i * size * 0.32, height * 0.62, -size * 0.3);
    parts.push(post);
  }
  const brace = new THREE.BoxGeometry(size * 0.07, height * 0.9, size * 0.07);
  brace.rotateX(-0.7);
  brace.translate(-size * 0.32, height * 0.34, -size * 0.14);
  parts.push(brace);
  const brace2 = brace.clone();
  brace2.translate(size * 0.64, 0, 0);
  parts.push(brace2);
  return mergeParts(parts);
}

function makeWall(size: number, height: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const main = new THREE.BoxGeometry(size * 0.86, height, size * 0.5);
  main.translate(0, height * 0.5, 0);
  parts.push(main);
  const cap = new THREE.BoxGeometry(size * 0.92, height * 0.1, size * 0.58);
  cap.translate(0, height * 1.02, 0);
  parts.push(cap);
  for (let i = 0; i < 3; i++) {
    const b = new THREE.BoxGeometry(size * 0.24, height * 0.28, size * 0.56);
    b.rotateZ((i - 1) * 0.06);
    b.translate((i - 1) * size * 0.28, height * (0.2 + i * 0.24), 0);
    parts.push(b);
  }
  return mergeParts(parts);
}

function makePlatform(size: number, height: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const body = new THREE.CylinderGeometry(size * 0.46, size * 0.5, height, 8, 1);
  body.rotateY(Math.PI / 8);
  body.translate(0, height * 0.5, 0);
  parts.push(body);
  const lip = new THREE.TorusGeometry(size * 0.45, size * 0.022, 4, 8);
  lip.rotateX(Math.PI / 2);
  lip.rotateY(Math.PI / 8);
  lip.translate(0, height, 0);
  parts.push(lip);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
    const strut = new THREE.BoxGeometry(size * 0.06, height * 1.1, size * 0.06);
    strut.translate(Math.cos(a) * size * 0.4, height * 0.55, Math.sin(a) * size * 0.4);
    parts.push(strut);
  }
  return mergeParts(parts);
}

function makePadGeometry(size: number, depth: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const rim = new THREE.CylinderGeometry(size * 0.46, size * 0.46, depth, 16, 1, true);
  rim.translate(0, depth * 0.5, 0);
  parts.push(rim);
  const floor = new THREE.CylinderGeometry(size * 0.44, size * 0.4, depth * 0.35, 16, 1);
  floor.translate(0, depth * 0.18, 0);
  parts.push(floor);
  return mergeParts(parts);
}

// ─────────────────────────────────────────────────────────────────────────────
// Per-kind art direction (all colours traced back to config PALETTE)
// ─────────────────────────────────────────────────────────────────────────────

function mixHex(a: number, b: number, t: number): number {
  const ca = new THREE.Color();
  ca.setHex(a, THREE.SRGBColorSpace);
  const cb = new THREE.Color();
  cb.setHex(b, THREE.SRGBColorSpace);
  ca.lerp(cb, t);
  return ca.getHex(THREE.SRGBColorSpace);
}

interface KindStyle {
  plate: number;
  emissive: number;
  emi: number;
}

const KIND_STYLE: Record<TileKind, KindStyle> = {
  floor: { plate: PALETTE.plate, emissive: PALETTE.cyan, emi: 0.02 },
  obstacle: { plate: mixHex(PALETTE.hull, PALETTE.void, 0.45), emissive: PALETTE.cyanDeep, emi: 0.05 },
  rough: { plate: mixHex(PALETTE.plate, PALETTE.amber, 0.14), emissive: PALETTE.amber, emi: 0.05 },
  cover: { plate: mixHex(PALETTE.plate, PALETTE.teal, 0.12), emissive: PALETTE.teal, emi: 0.09 },
  hazard: { plate: mixHex(PALETTE.hull, PALETTE.ember, 0.3), emissive: PALETTE.ember, emi: 0.42 },
  teleport: { plate: mixHex(PALETTE.hull, PALETTE.violet, 0.16), emissive: PALETTE.violet, emi: 0.24 },
  destructible: { plate: mixHex(PALETTE.steel, PALETTE.gold, 0.08), emissive: PALETTE.gold, emi: 0.05 },
  elevation: { plate: mixHex(PALETTE.plate, PALETTE.cyan, 0.1), emissive: PALETTE.cyan, emi: 0.14 },
  unstable: { plate: mixHex(PALETTE.plate, PALETTE.magenta, 0.16), emissive: PALETTE.magenta, emi: 0.18 },
};

const TELEPORT_HUES: number[] = [PALETTE.violet, PALETTE.teal, PALETTE.gold, PALETTE.magenta, PALETTE.cyan];

export function teleportHue(pairId: number | undefined): number {
  const idx = Math.abs(pairId ?? 0) % TELEPORT_HUES.length;
  return TELEPORT_HUES[idx];
}

// ─────────────────────────────────────────────────────────────────────────────
// Overlay shaders (highlights, hazard bloom, unstable flicker, glyphs, zones)
// ─────────────────────────────────────────────────────────────────────────────

const OVERLAY_VERT = /* glsl */ `
attribute vec3 aColor;
attribute vec4 aParam;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;
void main() {
  vUv = uv;
  vCol = aColor;
  vP = aParam;
  vec3 p = position;
  #ifdef USE_INSTANCING
    p = (instanceMatrix * vec4(p, 1.0)).xyz;
  #endif
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}
`;

const HIGHLIGHT_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;

float ringMask(vec2 uv, float inner, float outer, float soft) {
  vec2 d = abs(uv - 0.5) * 2.0;
  float m = max(d.x, d.y);
  return smoothstep(inner - soft, inner, m) * (1.0 - smoothstep(outer, outer + soft, m));
}

void main() {
  float mode = vP.x;
  float phase = vP.y;
  float pulse = 0.55 + 0.45 * sin(uTime * 3.2 + phase * 6.2831);
  vec2 d = abs(vUv - 0.5) * 2.0;
  float sq = max(d.x, d.y);

  float a = 0.0;
  if (mode < 0.5) {
    // reachable move tile: soft fill + breathing border
    a = (1.0 - smoothstep(0.55, 1.0, sq)) * 0.16;
    a += ringMask(vUv, 0.76, 0.94, 0.06) * (0.42 + 0.42 * pulse);
    float corner = step(0.72, d.x) * step(0.72, d.y);
    a += corner * 0.35 * pulse;
  } else if (mode < 1.5) {
    // attackable tile: hard crimson frame + hatching
    a = ringMask(vUv, 0.78, 1.0, 0.03) * (0.55 + 0.45 * pulse);
    float hatch = step(0.72, fract((vUv.x + vUv.y) * 7.0 - uTime * 0.6));
    a += hatch * (1.0 - smoothstep(0.55, 0.98, sq)) * 0.13;
  } else {
    // selection ring: bright double stroke with corner brackets
    a = ringMask(vUv, 0.84, 1.0, 0.02) * 0.95;
    a += ringMask(vUv, 0.62, 0.68, 0.02) * 0.35;
    float corner = step(0.68, d.x) * step(0.68, d.y);
    a += corner * (0.5 + 0.5 * pulse) * 0.5;
  }
  a *= vP.z;
  if (a < 0.004) discard;
  vec3 col = vCol * (1.1 + pulse * 0.5);
  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, vec3(lum) * 0.85, uDrain);
  gl_FragColor = vec4(col, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const HAZARD_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;

float hash(vec2 p) { return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p); vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0)), f.x), f.y);
}

void main() {
  float phase = vP.y;
  vec2 uv = vUv - 0.5;
  float r = length(uv) * 2.0;
  float core = 1.0 - smoothstep(0.1, 1.05, r);
  // molten cracks
  float n = noise(vUv * 6.0 + vec2(0.0, uTime * 0.35 + phase * 8.0));
  float n2 = noise(vUv * 13.0 - vec2(uTime * 0.22, 0.0));
  float veins = smoothstep(0.52, 0.78, n * 0.65 + n2 * 0.45);
  float breathe = 0.55 + 0.45 * sin(uTime * 2.1 + phase * 6.2831);
  // heat shimmer bands
  float shimmer = 0.5 + 0.5 * sin(vUv.y * 24.0 - uTime * 4.6 + n * 6.0);
  float a = core * (0.22 + veins * 0.75) * (0.55 + 0.45 * breathe);
  a += core * shimmer * 0.06;
  if (a < 0.005) discard;
  vec3 col = vCol * (0.7 + veins * 2.2 + breathe * 0.5);
  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, vec3(lum) * 0.8, uDrain);
  gl_FragColor = vec4(col, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const UNSTABLE_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;
void main() {
  float phase = vP.y;
  float crossings = vP.z;
  vec2 d = abs(vUv - 0.5) * 2.0;
  float sq = max(d.x, d.y);
  float flick = step(0.35, fract(sin(floor(uTime * 11.0 + phase * 30.0) * 12.9898) * 43758.5453));
  float edge = (1.0 - smoothstep(0.72, 0.99, sq)) * step(0.6, sq);
  float diag = step(0.86, fract((vUv.x - vUv.y) * 5.0 + uTime * 0.25));
  float a = edge * (0.35 + 0.45 * flick) + diag * 0.1 * (1.0 - smoothstep(0.6, 1.0, sq));
  a *= 0.5 + crossings * 0.42;
  if (a < 0.005) discard;
  vec3 col = vCol * (1.0 + flick * 0.9 + crossings * 0.5);
  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, vec3(lum) * 0.8, uDrain);
  gl_FragColor = vec4(col, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const GLYPH_VERT = /* glsl */ `
attribute vec3 aColor;
attribute vec4 aParam;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;
void main() {
  vUv = uv;
  vCol = aColor;
  vP = aParam;
  vec3 p = position;
  #ifdef USE_INSTANCING
    p = (instanceMatrix * vec4(p, 1.0)).xyz;
  #endif
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}
`;

const GLYPH_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform sampler2D uMap;
uniform float uTime;
uniform float uDrain;
uniform float uCols;
varying vec2 vUv;
varying vec3 vCol;
varying vec4 vP;
void main() {
  float idx = vP.x;
  float col = mod(idx, uCols);
  float row = floor(idx / uCols);
  vec2 uv = (vec2(col, uCols - 1.0 - row) + vUv) / uCols;
  vec4 tex = texture2D(uMap, uv);
  float a = tex.a * vP.z * (0.75 + 0.25 * sin(uTime * 1.9 + vP.y * 6.2831));
  if (a < 0.006) discard;
  vec3 c = vCol * (1.0 + vP.w);
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3(lum) * 0.85, uDrain);
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const ZONE_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const ZONE_FRAG = /* glsl */ `
#include <common>
#include <tonemapping_pars_fragment>
uniform float uTime;
uniform float uDrain;
uniform float uOpacity;
uniform float uFlip;
uniform vec3 uColor;
varying vec2 vUv;
void main() {
  float y = mix(vUv.y, 1.0 - vUv.y, uFlip);
  float hatch = step(0.6, fract((vUv.x * 26.0 + vUv.y * 26.0) - uTime * 0.35));
  float edge = 1.0 - smoothstep(0.0, 0.13, y);
  float grad = pow(1.0 - y, 1.6);
  float a = (hatch * 0.1 + grad * 0.16 + edge * 0.5) * uOpacity;
  if (a < 0.004) discard;
  vec3 c = uColor * (0.9 + edge * 1.6);
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = mix(c, vec3(lum) * 0.85, uDrain);
  gl_FragColor = vec4(c, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

function overlayMaterial(frag: string, blending: THREE.Blending): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader: OVERLAY_VERT,
    fragmentShader: frag,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending,
    side: THREE.DoubleSide,
    uniforms: { uTime: { value: 0 }, uDrain: { value: 0 } },
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// BattleBoard
// ─────────────────────────────────────────────────────────────────────────────

export interface BoardHighlights {
  moves: { x: number; y: number }[];
  attacks: { x: number; y: number }[];
  selected?: { x: number; y: number };
  path?: { x: number; y: number }[];
}

interface InstancedGroup {
  mesh: THREE.InstancedMesh;
  tint: THREE.InstancedBufferAttribute;
  param: THREE.InstancedBufferAttribute;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _e = new THREE.Euler();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _c = new THREE.Color();
const _plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
const _hit = new THREE.Vector3();

const HIGHLIGHT_CAP = 96;
const PATH_CAP = 128;

export class BattleBoard {
  readonly group = new THREE.Group();

  private low: boolean;
  private w = 0;
  private h = 0;
  private layoutKey = '';
  private tiles: Tile[][] = [];

  private groups: InstancedGroup[] = [];
  private plateGroup: InstancedGroup | null = null;
  private wallGroup: InstancedGroup | null = null;
  private glyphGroup: InstancedGroup | null = null;
  private hazardGroup: InstancedGroup | null = null;
  private unstableGroup: InstancedGroup | null = null;
  private ringA: InstancedGroup | null = null;
  private ringB: InstancedGroup | null = null;

  private plateIndex = new Map<number, number>();
  private wallIndex = new Map<number, number>();
  private glyphIndex = new Map<number, number>();
  private unstableIndex = new Map<number, number>();
  private ringTiles: { x: number; y: number }[] = [];
  private beamBatch: InstancedBatch | null = null;

  private highlightMesh: THREE.InstancedMesh | null = null;
  private highlightTint: THREE.InstancedBufferAttribute | null = null;
  private highlightParam: THREE.InstancedBufferAttribute | null = null;
  private highlightCount = 0;

  private pathMesh: THREE.Mesh | null = null;
  private pathMat: THREE.ShaderMaterial | null = null;
  private pathKey = '';

  private zones: THREE.Mesh[] = [];
  private seamLines: THREE.Mesh | null = null;

  private overlayMaterials: THREE.ShaderMaterial[] = [];
  private disposables: { dispose(): void }[] = [];
  private drain = 0;
  private reveal = 1;
  private flashing = false;

  constructor(opts: { low?: boolean } = {}) {
    this.low = opts.low ?? false;
    this.group.name = 'battle-board';
  }

  // ── public API ────────────────────────────────────────────────────────────

  get width(): number {
    return this.w;
  }

  get height(): number {
    return this.h;
  }

  setLow(low: boolean): void {
    this.low = low;
  }

  worldOf(x: number, y: number, out?: THREE.Vector3): THREE.Vector3 {
    const v = out ?? new THREE.Vector3();
    return v.set(tileWorldX(x, this.w), this.surfaceY(x, y), tileWorldZ(y, this.h));
  }

  surfaceY(x: number, y: number): number {
    const t = this.tileAtCoord(x, y);
    if (!t) return PLATE_H;
    if (t.kind === 'elevation') return PLATE_H + ELEVATION_RISE;
    if (t.kind === 'rough') return PLATE_H * 0.86;
    if (t.kind === 'teleport') return PLATE_H * 0.62;
    return PLATE_H;
  }

  tileAtCoord(x: number, y: number): Tile | null {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return null;
    const row = this.tiles[y];
    if (!row) return null;
    return row[x] ?? null;
  }

  sync(state: BattleState): void {
    const key = layoutKeyOf(state);
    this.tiles = state.grid;
    if (key !== this.layoutKey) {
      this.layoutKey = key;
      this.w = state.w;
      this.h = state.h;
      this.rebuild(state);
    }
    this.updateDynamic(state);
  }

  setHighlights(h: BoardHighlights): void {
    const mesh = this.highlightMesh;
    const tint = this.highlightTint;
    const param = this.highlightParam;
    if (!mesh || !tint || !param) return;

    let i = 0;
    const push = (x: number, y: number, mode: number, color: number, strength: number): void => {
      if (i >= HIGHLIGHT_CAP) return;
      const yTop = this.surfaceY(x, y) + 0.012 + mode * 0.004;
      _m.compose(
        _p.set(tileWorldX(x, this.w), yTop, tileWorldZ(y, this.h)),
        _q.identity(),
        _s.set(BATTLE_VIEW.tileSize, 1, BATTLE_VIEW.tileSize),
      );
      mesh.setMatrixAt(i, _m);
      _c.setHex(color, THREE.SRGBColorSpace);
      tint.setXYZ(i, _c.r, _c.g, _c.b);
      param.setXYZW(i, mode, tileHash(x, y, 7), strength, 0);
      i++;
    };

    for (const t of h.moves) push(t.x, t.y, 0, PALETTE.cyan, 1);
    for (const t of h.attacks) push(t.x, t.y, 1, PALETTE.crimson, 1);
    if (h.selected) push(h.selected.x, h.selected.y, 2, PALETTE.white, 1);

    this.highlightCount = i;
    mesh.count = i;
    mesh.instanceMatrix.needsUpdate = true;
    tint.needsUpdate = true;
    param.needsUpdate = true;
    mesh.visible = i > 0;

    this.setPath(h.path ?? []);
  }

  /** Pick a tile from a screen ray. Elevated plates are tested first. */
  tileAt(raycaster: THREE.Raycaster): { x: number; y: number } | null {
    if (this.w === 0) return null;
    const high = this.castPlane(raycaster, PLATE_H + ELEVATION_RISE);
    if (high) {
      const t = this.tileAtCoord(high.x, high.y);
      if (t && t.kind === 'elevation') return high;
    }
    return this.castPlane(raycaster, PLATE_H);
  }

  update(dt: number, time: number): void {
    for (const m of this.overlayMaterials) {
      m.uniforms.uTime.value = time;
      m.uniforms.uDrain.value = this.drain;
    }
    // counter-rotating teleport rings
    if (this.ringA && this.ringB && this.ringTiles.length) {
      for (let i = 0; i < this.ringTiles.length; i++) {
        const t = this.ringTiles[i];
        const bx = tileWorldX(t.x, this.w);
        const bz = tileWorldZ(t.y, this.h);
        const ph = tileHash(t.x, t.y, 11) * 6.2831;
        const lift = Math.sin(time * 1.4 + ph) * 0.02;
        _e.set(0, time * 0.9 + ph, 0);
        _q.setFromEuler(_e);
        _m.compose(_p.set(bx, PLATE_H * 0.5 + 0.04 + lift, bz), _q, _s.set(1, 1, 1));
        this.ringA.mesh.setMatrixAt(i, _m);
        _e.set(0, -time * 1.35 - ph, 0);
        _q.setFromEuler(_e);
        _m.compose(_p.set(bx, PLATE_H * 0.5 + 0.12 - lift, bz), _q, _s.set(0.72, 0.72, 0.72));
        this.ringB.mesh.setMatrixAt(i, _m);
      }
      this.ringA.mesh.instanceMatrix.needsUpdate = true;
      this.ringB.mesh.instanceMatrix.needsUpdate = true;
    }

    // decay impact flashes on the plates
    const pg = this.plateGroup;
    if (pg && this.flashing) {
      let any = false;
      const k = Math.exp(-dt * 5.5);
      for (let i = 0; i < pg.mesh.count; i++) {
        const v = pg.param.getW(i);
        if (v > 0.002) {
          pg.param.setW(i, v * k);
          any = true;
        } else if (v !== 0) {
          pg.param.setW(i, 0);
        }
      }
      pg.param.needsUpdate = true;
      this.flashing = any;
    }
  }

  setDrain(v: number): void {
    this.drain = v;
  }

  setReveal(v: number): void {
    this.reveal = v;
    for (const g of this.groups) {
      const mat = g.mesh.material;
      if (mat instanceof THREE.ShaderMaterial && mat.uniforms.uReveal) mat.uniforms.uReveal.value = v;
    }
    if (this.seamLines) this.seamLines.visible = v > 0.98;
  }

  getReveal(): number {
    return this.reveal;
  }

  setDeployZones(bottomColor: number, topColor: number, visible: boolean): void {
    if (this.zones.length !== 2) return;
    for (const z of this.zones) z.visible = visible;
    const mb = this.zones[0].material;
    const mt = this.zones[1].material;
    if (mb instanceof THREE.ShaderMaterial) (mb.uniforms.uColor.value as THREE.Color).setHex(bottomColor, THREE.SRGBColorSpace);
    if (mt instanceof THREE.ShaderMaterial) (mt.uniforms.uColor.value as THREE.Color).setHex(topColor, THREE.SRGBColorSpace);
  }

  /** Flash a plate (used by fx for wall hits and obstacle placement). */
  pulseTile(x: number, y: number, amount: number): void {
    const g = this.plateGroup;
    const idx = this.plateIndex.get(x + y * this.w);
    if (!g || idx === undefined) return;
    g.param.setW(idx, amount);
    g.param.needsUpdate = true;
    this.flashing = true;
  }

  dispose(): void {
    this.clearBuilt();
    for (const d of this.disposables) d.dispose();
    this.disposables.length = 0;
    this.group.clear();
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private castPlane(raycaster: THREE.Raycaster, y: number): { x: number; y: number } | null {
    _plane.set(_p.set(0, 1, 0), -y);
    const hit = raycaster.ray.intersectPlane(_plane, _hit);
    if (!hit) return null;
    const tx = Math.round(hit.x / TILE_PITCH + (this.w - 1) / 2);
    const ty = Math.round(hit.z / TILE_PITCH + (this.h - 1) / 2);
    if (tx < 0 || ty < 0 || tx >= this.w || ty >= this.h) return null;
    return { x: tx, y: ty };
  }

  /** Path preview: a tapered holo ribbon rebuilt only when the path changes. */
  private setPath(path: { x: number; y: number }[]): void {
    let key = '';
    for (const p of path) key += `${p.x},${p.y};`;
    if (key === this.pathKey) return;
    this.pathKey = key;

    if (this.pathMesh) {
      this.group.remove(this.pathMesh);
      this.pathMesh.geometry.dispose();
      this.pathMesh = null;
    }
    if (path.length < 2 || !this.pathMat) return;

    const pts: THREE.Vector3[] = [];
    const n = Math.min(path.length, PATH_CAP);
    for (let i = 0; i < n; i++) {
      const t = path[i];
      pts.push(
        new THREE.Vector3(
          tileWorldX(t.x, this.w),
          this.surfaceY(t.x, t.y) + 0.045,
          tileWorldZ(t.y, this.h),
        ),
      );
    }
    const geo = buildRibbon(pts, BATTLE_VIEW.tileSize * 0.2, { taper: 0.42 });
    const mesh = new THREE.Mesh(geo, this.pathMat);
    mesh.renderOrder = 7;
    mesh.frustumCulled = false;
    this.pathMesh = mesh;
    this.group.add(mesh);
  }

  private clearBuilt(): void {
    const overlay = new Set<THREE.Material>(this.overlayMaterials);
    for (const g of this.groups) {
      this.group.remove(g.mesh);
      g.mesh.geometry.dispose();
      const mat = g.mesh.material;
      if (!Array.isArray(mat) && !overlay.has(mat)) {
        if (mat instanceof THREE.ShaderMaterial) disposeHull(mat);
        else mat.dispose();
      }
      g.mesh.dispose();
    }
    this.groups.length = 0;
    this.plateGroup = null;
    this.wallGroup = null;
    this.glyphGroup = null;
    this.hazardGroup = null;
    this.unstableGroup = null;
    this.ringA = null;
    this.ringB = null;
    this.plateIndex.clear();
    this.wallIndex.clear();
    this.glyphIndex.clear();
    this.unstableIndex.clear();
    this.ringTiles.length = 0;
    if (this.beamBatch) {
      this.beamBatch.dispose();
      this.beamBatch = null;
    }
    if (this.seamLines) {
      this.group.remove(this.seamLines);
      this.seamLines.geometry.dispose();
      this.seamLines = null;
    }
    for (const z of this.zones) {
      this.group.remove(z);
      z.geometry.dispose();
      const m = z.material;
      if (!Array.isArray(m)) m.dispose();
    }
    this.zones.length = 0;
    if (this.highlightMesh) {
      this.group.remove(this.highlightMesh);
      this.highlightMesh.geometry.dispose();
      this.highlightMesh.dispose();
      this.highlightMesh = null;
    }
    if (this.pathMesh) {
      this.group.remove(this.pathMesh);
      this.pathMesh.geometry.dispose();
      this.pathMesh = null;
    }
    if (this.pathMat) {
      this.pathMat.dispose();
      this.pathMat = null;
    }
    this.pathKey = '';
    for (const m of this.overlayMaterials) m.dispose();
    this.overlayMaterials.length = 0;
  }

  private makeInstanced(
    geo: THREE.BufferGeometry,
    mat: THREE.Material,
    count: number,
    renderOrder = 0,
  ): InstancedGroup {
    const mesh = new THREE.InstancedMesh(geo, mat, Math.max(1, count));
    mesh.count = count;
    mesh.frustumCulled = false;
    mesh.renderOrder = renderOrder;
    const tint = new THREE.InstancedBufferAttribute(new Float32Array(Math.max(1, count) * 3), 3);
    const param = new THREE.InstancedBufferAttribute(new Float32Array(Math.max(1, count) * 4), 4);
    geo.setAttribute('aTint', tint);
    geo.setAttribute('aParam', param);
    geo.setAttribute('aColor', tint);
    const g: InstancedGroup = { mesh, tint, param };
    this.groups.push(g);
    this.group.add(mesh);
    return g;
  }

  private rebuild(state: BattleState): void {
    this.clearBuilt();
    const w = state.w;
    const h = state.h;
    const size = BATTLE_VIEW.tileSize;

    // ── classify ──
    const plates: Tile[] = [];
    const blocks: Tile[] = [];
    const scree: Tile[] = [];
    const barricades: Tile[] = [];
    const walls: Tile[] = [];
    const platforms: Tile[] = [];
    const pads: Tile[] = [];
    const hazards: Tile[] = [];
    const unstables: Tile[] = [];
    const glyphs: Tile[] = [];

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const t = state.grid[y][x];
        plates.push(t);
        const collapsed = t.kind === 'unstable' && t.collapsed === true;
        if (t.kind === 'obstacle' || collapsed) blocks.push(t);
        else if (t.kind === 'rough') {
          scree.push(t);
          glyphs.push(t);
        } else if (t.kind === 'cover') {
          barricades.push(t);
          glyphs.push(t);
        } else if (t.kind === 'destructible') {
          walls.push(t);
          glyphs.push(t);
        } else if (t.kind === 'elevation') {
          platforms.push(t);
          glyphs.push(t);
        } else if (t.kind === 'teleport') {
          pads.push(t);
          glyphs.push(t);
        } else if (t.kind === 'hazard') {
          hazards.push(t);
          glyphs.push(t);
        } else if (t.kind === 'unstable') {
          unstables.push(t);
          glyphs.push(t);
        }
      }
    }

    const setInstance = (
      g: InstancedGroup,
      i: number,
      x: number,
      y: number,
      yOff: number,
      yaw: number,
      scale: number,
      color: number,
      emi: number,
      dmg: number,
    ): void => {
      _e.set(0, yaw, 0);
      _q.setFromEuler(_e);
      _m.compose(
        _p.set(tileWorldX(x, w), yOff, tileWorldZ(y, h)),
        _q,
        _s.set(scale, scale, scale),
      );
      g.mesh.setMatrixAt(i, _m);
      _c.setHex(color, THREE.SRGBColorSpace);
      g.tint.setXYZ(i, _c.r, _c.g, _c.b);
      g.param.setXYZW(i, emi, tileHash(x, y, 3), dmg, 0);
    };

    // ── plates (every tile) ──
    {
      const geo = makePlateGeometry(size, PLATE_H, size * 0.045);
      const mat = makeHullMaterial({
        emissive: PALETTE.cyan,
        seam: 0.85,
        seamScale: 1 / TILE_PITCH,
        scan: 0.06,
        fresnel: 0.9,
      });
      const g = this.makeInstanced(geo, mat, plates.length);
      this.plateGroup = g;
      for (let i = 0; i < plates.length; i++) {
        const t = plates[i];
        const style = KIND_STYLE[t.kind];
        const checker = (t.x + t.y) % 2 === 0 ? 1.0 : 0.86;
        const jitter = 0.92 + tileHash(t.x, t.y, 1) * 0.16;
        _c.setHex(style.plate, THREE.SRGBColorSpace).multiplyScalar(checker * jitter);
        const col = _c.getHex(THREE.SRGBColorSpace);
        const drop =
          t.kind === 'rough' ? PLATE_H * 0.14 : t.kind === 'teleport' ? PLATE_H * 0.38 : 0;
        setInstance(g, i, t.x, t.y, -drop, 0, 1, col, style.emi * 0.5, 0);
        this.plateIndex.set(t.x + t.y * w, i);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── obstacle blocks ──
    if (blocks.length) {
      const geo = makeJaggedBlock(size, BLOCK_H);
      const mat = makeHullMaterial({
        emissive: PALETTE.cyanDeep,
        seam: 0.12,
        scan: 0.09,
        fresnel: 1.35,
      });
      const g = this.makeInstanced(geo, mat, blocks.length);
      for (let i = 0; i < blocks.length; i++) {
        const t = blocks[i];
        const yaw = tileHash(t.x, t.y, 5) * Math.PI * 2;
        const sc = 0.9 + tileHash(t.x, t.y, 9) * 0.2;
        const collapsed = t.kind === 'unstable';
        setInstance(
          g,
          i,
          t.x,
          t.y,
          PLATE_H,
          yaw,
          collapsed ? sc * 0.7 : sc,
          collapsed ? KIND_STYLE.unstable.plate : KIND_STYLE.obstacle.plate,
          collapsed ? 0.18 : 0.07,
          collapsed ? 0.45 : 0,
        );
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── rough scree ──
    if (scree.length) {
      const geo = makeScree(size);
      const mat = makeHullMaterial({ emissive: PALETTE.amber, seam: 0, scan: 0.04, fresnel: 1.1 });
      const g = this.makeInstanced(geo, mat, scree.length);
      for (let i = 0; i < scree.length; i++) {
        const t = scree[i];
        setInstance(
          g,
          i,
          t.x,
          t.y,
          PLATE_H * 0.86,
          tileHash(t.x, t.y, 13) * Math.PI * 2,
          0.9 + tileHash(t.x, t.y, 17) * 0.25,
          KIND_STYLE.rough.plate,
          0.03,
          0,
        );
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── cover barricades ──
    if (barricades.length) {
      const geo = makeBarricade(size, COVER_H);
      const mat = makeHullMaterial({ emissive: PALETTE.teal, seam: 0.2, scan: 0.05, fresnel: 1.2 });
      const g = this.makeInstanced(geo, mat, barricades.length);
      for (let i = 0; i < barricades.length; i++) {
        const t = barricades[i];
        // face the barricade wall away from the nearest board edge
        const towardCenter = Math.atan2(tileWorldX(t.x, w), tileWorldZ(t.y, h));
        setInstance(g, i, t.x, t.y, PLATE_H, towardCenter + Math.PI, 1, KIND_STYLE.cover.plate, 0.22, 0);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── destructible walls ──
    if (walls.length) {
      const geo = makeWall(size, WALL_H);
      const mat = makeHullMaterial({ emissive: PALETTE.gold, seam: 0.15, scan: 0.05, fresnel: 1.1 });
      const g = this.makeInstanced(geo, mat, walls.length);
      this.wallGroup = g;
      for (let i = 0; i < walls.length; i++) {
        const t = walls[i];
        const yaw = ((t.x + t.y) % 2 === 0 ? 0 : Math.PI / 2) + (tileHash(t.x, t.y, 19) - 0.5) * 0.2;
        setInstance(g, i, t.x, t.y, PLATE_H, yaw, 1, KIND_STYLE.destructible.plate, 0.1, 0);
        this.wallIndex.set(t.x + t.y * w, i);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── elevation platforms ──
    if (platforms.length) {
      const geo = makePlatform(size, ELEVATION_RISE);
      const mat = makeHullMaterial({
        emissive: PALETTE.cyan,
        seam: 0.5,
        seamScale: 1 / TILE_PITCH,
        scan: 0.05,
        fresnel: 1.2,
      });
      const g = this.makeInstanced(geo, mat, platforms.length);
      for (let i = 0; i < platforms.length; i++) {
        const t = platforms[i];
        setInstance(g, i, t.x, t.y, PLATE_H, 0, 1, KIND_STYLE.elevation.plate, 0.3, 0);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── teleport pads + counter-rotating rings + beams ──
    if (pads.length) {
      const geo = makePadGeometry(size, PLATE_H * 0.62);
      const mat = makeHullMaterial({
        emissive: PALETTE.violet,
        seam: 0.3,
        scan: 0.04,
        fresnel: 1.4,
        side: THREE.DoubleSide,
      });
      const g = this.makeInstanced(geo, mat, pads.length);
      for (let i = 0; i < pads.length; i++) {
        const t = pads[i];
        setInstance(g, i, t.x, t.y, -PLATE_H * 0.38, 0, 1, KIND_STYLE.teleport.plate, 0.35, 0);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;

      const ringGeo = () => {
        const r = new THREE.TorusGeometry(size * 0.34, size * 0.022, 3, 18);
        r.rotateX(Math.PI / 2);
        const notches: THREE.BufferGeometry[] = [r];
        for (let i = 0; i < 4; i++) {
          const a = (i / 4) * Math.PI * 2;
          const n = new THREE.BoxGeometry(size * 0.05, size * 0.05, size * 0.13);
          n.rotateY(-a);
          n.translate(Math.cos(a) * size * 0.34, 0, Math.sin(a) * size * 0.34);
          notches.push(n);
        }
        return mergeParts(notches);
      };
      const ringMatA = makeHullMaterial({ emissive: PALETTE.violet, seam: 0, scan: 0, fresnel: 2.2 });
      const ringMatB = makeHullMaterial({ emissive: PALETTE.teal, seam: 0, scan: 0, fresnel: 2.2 });
      this.ringA = this.makeInstanced(ringGeo(), ringMatA, pads.length, 1);
      this.ringB = this.makeInstanced(ringGeo(), ringMatB, pads.length, 1);
      for (let i = 0; i < pads.length; i++) {
        const t = pads[i];
        const hue = teleportHue(t.pairId);
        this.ringTiles.push({ x: t.x, y: t.y });
        _c.setHex(hue, THREE.SRGBColorSpace);
        this.ringA.tint.setXYZ(i, _c.r, _c.g, _c.b);
        this.ringA.param.setXYZW(i, 0.9, tileHash(t.x, t.y, 23), 0, 0);
        _c.setHex(mixHex(hue, PALETTE.white, 0.35), THREE.SRGBColorSpace);
        this.ringB.tint.setXYZ(i, _c.r, _c.g, _c.b);
        this.ringB.param.setXYZW(i, 1.2, tileHash(t.x, t.y, 29), 0, 0);
      }
      this.ringA.tint.needsUpdate = true;
      this.ringA.param.needsUpdate = true;
      this.ringB.tint.needsUpdate = true;
      this.ringB.param.needsUpdate = true;

      // vertical energy beam per pad — one instanced draw call, hue per pair
      const beamMat = makeEnergyFieldMaterial(PALETTE.white);
      this.disposables.push(beamMat);
      const batch = new InstancedBatch(
        this.group,
        lightColumnGeometry(size * 0.19, size * 2.2, 12),
        beamMat,
        pads.length,
        [
          { name: 'aIntensity', size: 1, fill: [1] },
          { name: 'aTint', size: 3, fill: [1, 1, 1] },
        ],
      );
      batch.setRenderOrder(3);
      batch.begin();
      for (const t of pads) {
        _m.compose(
          _p.set(tileWorldX(t.x, w), PLATE_H * 0.1, tileWorldZ(t.y, h)),
          _q.identity(),
          _s.set(1, 1, 1),
        );
        const idx = batch.add(_m);
        _c.setHex(teleportHue(t.pairId), THREE.SRGBColorSpace);
        batch.set(idx, 'aIntensity', 0.85);
        batch.set(idx, 'aTint', _c.r, _c.g, _c.b);
      }
      batch.end();
      this.beamBatch = batch;
    }

    // ── hazard bloom overlays ──
    if (hazards.length) {
      const geo = new THREE.PlaneGeometry(size * 1.02, size * 1.02);
      geo.rotateX(-Math.PI / 2);
      const mat = overlayMaterial(HAZARD_FRAG, THREE.AdditiveBlending);
      this.overlayMaterials.push(mat);
      const g = this.makeInstanced(geo, mat, hazards.length, 3);
      this.hazardGroup = g;
      for (let i = 0; i < hazards.length; i++) {
        const t = hazards[i];
        setInstance(g, i, t.x, t.y, PLATE_H + 0.008, 0, 1, PALETTE.ember, 0, 0);
        g.param.setXYZW(i, 0, tileHash(t.x, t.y, 31), 0, 0);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── unstable flicker overlays ──
    if (unstables.length) {
      const geo = new THREE.PlaneGeometry(size * 1.0, size * 1.0);
      geo.rotateX(-Math.PI / 2);
      const mat = overlayMaterial(UNSTABLE_FRAG, THREE.AdditiveBlending);
      this.overlayMaterials.push(mat);
      const g = this.makeInstanced(geo, mat, unstables.length, 3);
      this.unstableGroup = g;
      for (let i = 0; i < unstables.length; i++) {
        const t = unstables[i];
        setInstance(g, i, t.x, t.y, PLATE_H + 0.01, 0, 1, PALETTE.magenta, 0, 0);
        g.param.setXYZW(i, 0, tileHash(t.x, t.y, 37), (t.crossings ?? 0) / BATTLE.unstableCrossings, 0);
        this.unstableIndex.set(t.x + t.y * w, i);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── glyph decals ──
    if (glyphs.length) {
      const geo = new THREE.PlaneGeometry(size * 0.62, size * 0.62);
      geo.rotateX(-Math.PI / 2);
      const mat = new THREE.ShaderMaterial({
        vertexShader: GLYPH_VERT,
        fragmentShader: GLYPH_FRAG,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        uniforms: {
          uMap: { value: getGlyphAtlas() },
          uTime: { value: 0 },
          uDrain: { value: 0 },
          uCols: { value: GLYPH_COLS },
        },
      });
      this.overlayMaterials.push(mat);
      const g = this.makeInstanced(geo, mat, glyphs.length, 4);
      this.glyphGroup = g;
      for (let i = 0; i < glyphs.length; i++) {
        const t = glyphs[i];
        this.glyphIndex.set(t.x + t.y * w, i);
        const yOff = this.glyphHeight(t);
        _m.compose(
          _p.set(tileWorldX(t.x, w), yOff, tileWorldZ(t.y, h)),
          _q.identity(),
          _s.set(1, 1, 1),
        );
        g.mesh.setMatrixAt(i, _m);
        const style = KIND_STYLE[t.kind];
        _c.setHex(t.kind === 'teleport' ? teleportHue(t.pairId) : style.emissive, THREE.SRGBColorSpace);
        g.tint.setXYZ(i, _c.r, _c.g, _c.b);
        g.param.setXYZW(i, this.glyphIndexFor(t), tileHash(t.x, t.y, 41), 0.85, 0);
      }
      g.mesh.instanceMatrix.needsUpdate = true;
      g.tint.needsUpdate = true;
      g.param.needsUpdate = true;
    }

    // ── seam lattice: glowing holo ribbons running down the plate gaps ──
    {
      const yy = PLATE_H + 0.005;
      const x0 = tileWorldX(0, w) - TILE_PITCH / 2;
      const z0 = tileWorldZ(0, h) - TILE_PITCH / 2;
      const x1 = tileWorldX(w - 1, w) + TILE_PITCH / 2;
      const z1 = tileWorldZ(h - 1, h) + TILE_PITCH / 2;
      const width = BATTLE_VIEW.tileGap * 0.95;
      const ribbons: THREE.BufferGeometry[] = [];
      for (let i = 0; i <= w; i++) {
        const x = x0 + i * TILE_PITCH;
        ribbons.push(
          buildRibbon([new THREE.Vector3(x, yy, z0), new THREE.Vector3(x, yy, z1)], width),
        );
      }
      for (let i = 0; i <= h; i++) {
        const z = z0 + i * TILE_PITCH;
        ribbons.push(
          buildRibbon([new THREE.Vector3(x0, yy, z), new THREE.Vector3(x1, yy, z)], width),
        );
      }
      const geo = mergeGeometries(ribbons, false);
      for (const r of ribbons) r.dispose();
      const mat = makeHoloLineMaterial(PALETTE.cyan, { opacity: 0.42 });
      this.disposables.push(mat);
      const lattice = new THREE.Mesh(geo, mat);
      lattice.frustumCulled = false;
      lattice.renderOrder = 2;
      this.seamLines = lattice;
      this.group.add(lattice);

      this.pathMat = makeHoloLineMaterial(PALETTE.teal, {
        opacity: 0.85,
        dash: true,
        dashSize: 0.34,
        gapSize: 0.22,
        dashSpeed: 1.6,
      });
    }

    // ── deploy zones ──
    {
      const zw = w * TILE_PITCH;
      const zh = BATTLE.deployRows * TILE_PITCH;
      for (let i = 0; i < 2; i++) {
        const geo = new THREE.PlaneGeometry(zw, zh, 1, 1);
        geo.rotateX(-Math.PI / 2);
        const mat = new THREE.ShaderMaterial({
          vertexShader: ZONE_VERT,
          fragmentShader: ZONE_FRAG,
          transparent: true,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          side: THREE.DoubleSide,
          uniforms: {
            uTime: { value: 0 },
            uDrain: { value: 0 },
            uOpacity: { value: 1 },
            uFlip: { value: i === 0 ? 0 : 1 },
            uColor: { value: new THREE.Color(PALETTE.cyan) },
          },
        });
        this.overlayMaterials.push(mat);
        const mesh = new THREE.Mesh(geo, mat);
        const rowCenter = i === 0 ? h - BATTLE.deployRows / 2 - 0.5 : BATTLE.deployRows / 2 - 0.5;
        mesh.position.set(0, PLATE_H + 0.006, tileWorldZ(rowCenter, h));
        mesh.renderOrder = 2;
        mesh.visible = false;
        this.zones.push(mesh);
        this.group.add(mesh);
      }
    }

    // ── highlight overlay ──
    {
      const geo = new THREE.PlaneGeometry(1, 1);
      geo.rotateX(-Math.PI / 2);
      const mat = overlayMaterial(HIGHLIGHT_FRAG, THREE.AdditiveBlending);
      this.overlayMaterials.push(mat);
      const mesh = new THREE.InstancedMesh(geo, mat, HIGHLIGHT_CAP);
      mesh.count = 0;
      mesh.frustumCulled = false;
      mesh.renderOrder = 6;
      const tint = new THREE.InstancedBufferAttribute(new Float32Array(HIGHLIGHT_CAP * 3), 3);
      const param = new THREE.InstancedBufferAttribute(new Float32Array(HIGHLIGHT_CAP * 4), 4);
      geo.setAttribute('aColor', tint);
      geo.setAttribute('aParam', param);
      this.highlightMesh = mesh;
      this.highlightTint = tint;
      this.highlightParam = param;
      this.group.add(mesh);
    }

    this.setReveal(this.reveal);
  }

  private glyphHeight(t: Tile): number {
    if (t.kind === 'elevation') return PLATE_H + ELEVATION_RISE + 0.012;
    if (t.kind === 'destructible') return PLATE_H + WALL_H + 0.02;
    if (t.kind === 'cover') return PLATE_H + 0.014;
    if (t.kind === 'teleport') return PLATE_H * 0.24;
    return PLATE_H + 0.014;
  }

  private glyphIndexFor(t: Tile): number {
    switch (t.kind) {
      case 'cover':
        return GLYPH.shield;
      case 'elevation':
        return GLYPH.arrow;
      case 'rough':
        return GLYPH.hatch;
      case 'hazard':
        return GLYPH.warning;
      case 'teleport':
        return GLYPH.teleport;
      case 'destructible':
        return GLYPH.crack;
      case 'unstable':
        return GLYPH.pips0 + Math.min(BATTLE.unstableCrossings, t.crossings ?? 0);
      default:
        return GLYPH.bracket;
    }
  }

  /** Per-frame-cheap state refresh: wall damage, crossings, collapse. */
  private updateDynamic(state: BattleState): void {
    const wg = this.wallGroup;
    if (wg) {
      let dirty = false;
      for (let y = 0; y < state.h; y++) {
        for (let x = 0; x < state.w; x++) {
          const t = state.grid[y][x];
          if (t.kind !== 'destructible') continue;
          const idx = this.wallIndex.get(x + y * state.w);
          if (idx === undefined) continue;
          const hp = t.hp ?? BATTLE.wallHp;
          const dmg = 1 - Math.max(0, Math.min(1, hp / BATTLE.wallHp));
          if (Math.abs(wg.param.getZ(idx) - dmg) > 0.001) {
            wg.param.setZ(idx, dmg);
            wg.param.setX(idx, 0.1 + dmg * 0.9);
            dirty = true;
          }
        }
      }
      if (dirty) wg.param.needsUpdate = true;
    }

    const ug = this.unstableGroup;
    const gg = this.glyphGroup;
    if (ug || gg) {
      let dirtyU = false;
      let dirtyG = false;
      for (let y = 0; y < state.h; y++) {
        for (let x = 0; x < state.w; x++) {
          const t = state.grid[y][x];
          if (t.kind !== 'unstable') continue;
          const cross = Math.min(BATTLE.unstableCrossings, t.crossings ?? 0);
          if (ug) {
            const idx = this.unstableIndex.get(x + y * state.w) ?? -1;
            if (idx >= 0) {
              const v = cross / BATTLE.unstableCrossings;
              if (Math.abs(ug.param.getZ(idx) - v) > 0.001) {
                ug.param.setZ(idx, v);
                dirtyU = true;
              }
            }
          }
          if (gg) {
            const gi = this.glyphIndex.get(x + y * state.w);
            if (gi !== undefined) {
              const want = GLYPH.pips0 + cross;
              if (gg.param.getX(gi) !== want) {
                gg.param.setX(gi, want);
                dirtyG = true;
              }
            }
          }
        }
      }
      if (dirtyU && ug) ug.param.needsUpdate = true;
      if (dirtyG && gg) gg.param.needsUpdate = true;
    }
  }

}

function layoutKeyOf(state: BattleState): string {
  let s = `${state.boardId}:${state.w}x${state.h}|`;
  for (let y = 0; y < state.h; y++) {
    for (let x = 0; x < state.w; x++) {
      const t = state.grid[y][x];
      s += t.kind[0];
      if (t.kind === 'teleport') s += String(t.pairId ?? 0);
      if (t.collapsed) s += '!';
    }
    s += '/';
  }
  return s;
}
