/**
 * TERRA BELLUM — first-battle coach (GDD §7.2, §13 step 8).
 *
 * The dice engine is the one system in this game nobody can guess. Post-roll
 * assignment inverts what a player expects from dice — the roll is not an
 * outcome, it is a budget you get to allocate after you see it — and a commander
 * who does not know that spends their first battle thinking the game rolled
 * badly for them. So it is explained once, in front of the board, before the
 * first turn a human is asked to play.
 *
 * Shown automatically exactly once (localStorage latch, same pattern as the drop
 * briefing in screens/staging.ts) and reopenable for ever after from the HUD's
 * `?` key. Every number is read from `BATTLE` config, so the coach cannot drift
 * away from the rules it is describing.
 */
import { BATTLE } from '../../config/balance';
import { openModal, type ModalHandle } from '../components';
import { el, haptic } from '../dom';

const COACH_KEY = 'tb.coach.battle.v1';

export function coachSeen(): boolean {
  try {
    return window.localStorage.getItem(COACH_KEY) === '1';
  } catch {
    // Private mode: the coach simply offers itself again next battle. Better
    // than swallowing the one explanation the game genuinely needs to give.
    return false;
  }
}

function markSeen(): void {
  try {
    window.localStorage.setItem(COACH_KEY, '1');
  } catch {
    /* ignore */
  }
}

interface Step {
  idx: string;
  title: string;
  body: string;
}

/**
 * Four steps, and they are the dice engine — nothing else.
 *
 * This used to be seven steps and 300 words, which on a 390×844 phone is a card
 * covering 79% of the screen with 40% of its own text below the fold. Two thirds
 * of it (action costs, damage arithmetic, the concede rules, the turn clock)
 * describe decisions the commander cannot make until several screens later, and
 * every one of those is already taught in place at the moment it matters: the
 * action bar prints MOV/RNG/ATK and the exact predicted damage of every shot,
 * and the concede flow has its own confirm sheet. A rule you read here and use
 * in four minutes is a rule you read twice.
 *
 * What survives is the part nothing else can teach, because it inverts what a
 * player expects from dice: the roll is a budget you allocate AFTER you see it,
 * not an outcome. Numbers come from `BATTLE` so the coach cannot drift.
 */
function steps(): Step[] {
  return [
    {
      idx: 'I',
      title: `${BATTLE.diceCount} DICE, ${BATTLE.diceMin}–${BATTLE.diceMax} EACH`,
      body: 'Rolled in the open at the start of your turn. The only randomness in the battle.',
    },
    {
      idx: 'II',
      title: 'YOU ASSIGN THEM AFTER YOU SEE THEM',
      body:
        'Drag each die onto one of your chassis, one die each. That number is the unit’s action ' +
        'points — move, fire or brace, one point apiece.',
    },
    {
      idx: 'III',
      title: 'A ZERO SITS THAT UNIT OUT',
      body: 'Give the 0 to whoever has least to do. All three zero and the whole turn is forfeit.',
    },
    {
      idx: 'IV',
      title: 'DAMAGE IS FLAT',
      body: 'No rolls to hit. Once the dice are down you can count the turn out exactly.',
    },
  ];
}

export interface CoachOpts {
  /** True when the player asked for it via the `?` key; skips the seen-latch. */
  manual: boolean;
  onClose?: () => void;
}

/**
 * Open the coach. Returns null when it was an automatic offer and the commander
 * has already read it, so callers can treat "not shown" as a normal outcome.
 */
export function openBattleCoach(opts: CoachOpts): ModalHandle | null {
  if (!opts.manual && coachSeen()) return null;

  const body = el('div', { class: 'coach' });
  body.appendChild(
    el('p', {
      class: 'coach__lede',
      text: 'Chess with a randomised action budget.',
    }),
  );
  for (const step of steps()) {
    body.appendChild(
      el(
        'div',
        { class: 'coach__step' },
        el('span', { class: 'coach__idx display', text: step.idx }),
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'coach__title display', text: step.title }),
          el('p', { class: 'coach__body', text: step.body }),
        ),
      ),
    );
  }
  body.appendChild(
    el('p', {
      class: 'coach__foot mono',
      text: 'REOPEN ANY TIME FROM ?',
    }),
  );

  const handle = openModal({
    title: 'HOW A BATTLE WORKS',
    body,
    accent: 'var(--cyan)',
    class: 'modal--coach',
    actions: [
      {
        label: opts.manual ? 'CLOSE' : 'GOT IT',
        variant: 'primary',
        onClick: () => {
          markSeen();
          haptic(12);
        },
      },
    ],
    onClose: () => {
      // Dismissing by scrim or Escape still counts as read — nagging a player
      // who closed it deliberately is worse than them missing a rule.
      markSeen();
      opts.onClose?.();
    },
  });

  return handle;
}
