/**
 * TERRA BELLUM — the dice tray (GDD §7.2). The signature mechanic.
 *
 * Three machined dice sit in a bottom tray. `rollAnimation()` tumbles real CSS
 * 3D cubes — six pip faces covering 0-4 plus a blank — and settles them with a
 * bounce over `FX.diceRollMs` before the value is legible.
 *
 * AFTER the reveal the commander assigns each die to a unit. Two input paths,
 * because this has to work one-handed on a phone:
 *   1. DRAG   — pointer drag with a ghost die under the finger; drop targets are
 *               resolved by the screen (unit-bar chips carry `data-drop-unit`),
 *               and the 3D board lights up its eligible chassis at the same time.
 *   2. TAP    — tap a die to arm it, then tap any unit (bar or board). Tapping a
 *               docked die, or dragging it into empty space, unassigns it.
 *
 * LAYOUT: the dice rail and the commit button share one row rather than stacking,
 * and the tray's own headline is gone — the HUD order row already names the
 * phase, and printing it twice cost the board 40 px. Once the dice are locked in
 * (`acting`) they are a read-only receipt, so they shrink and hand the room back.
 *
 * Surplus dice are visibly discarded when the roster is under three chassis, and
 * the 0-0-0 roll gets the humiliation it is owed: the tray flashes, the dice
 * crack, and a TOTAL SYSTEMS FAILURE stamp slams down.
 */
import { BATTLE } from '../../config/balance';
import { FX } from '../../config/visual';
import { emitFx } from '../../game/store';
import type { DieIndex, UnitId } from '../../game/types';
import { clear, el, haptic } from '../dom';

// ─────────────────────────────────────────────────────────────────────────────
// Cube geometry
// ─────────────────────────────────────────────────────────────────────────────

type FaceKey = 'front' | 'right' | 'back' | 'left' | 'top' | 'bottom';

/** Which value lives on which face, and the cube rotation that fronts it. */
const FACES: { key: FaceKey; value: number; rx: number; ry: number }[] = [
  { key: 'front', value: 1, rx: 0, ry: 0 },
  { key: 'right', value: 3, rx: 0, ry: -90 },
  { key: 'back', value: 4, rx: 0, ry: -180 },
  { key: 'left', value: 2, rx: 0, ry: 90 },
  { key: 'top', value: 0, rx: -90, ry: 0 },
  { key: 'bottom', value: -1, rx: 90, ry: 0 },
];

/** Which of the nine pip cells are inked for a face value. */
const PIPS: Record<number, number[]> = {
  0: [],
  1: [4],
  2: [0, 8],
  3: [0, 4, 8],
  4: [0, 2, 6, 8],
};

const DIE_INDICES: readonly DieIndex[] = [0, 1, 2];

function reduced(): boolean {
  return document.body.classList.contains('reduce-motion');
}

function faceFor(value: number): { rx: number; ry: number } {
  const f = FACES.find((x) => x.value === value) ?? FACES[0];
  return { rx: f.rx, ry: f.ry };
}

function buildFace(value: number): HTMLElement {
  const face = el('div', {
    class: `die__face die__face--${value < 0 ? 'blank' : `v${value}`}`,
    data: { v: String(value) },
  });
  face.appendChild(el('div', { class: 'die__bevel', aria: { hidden: 'true' } }));

  if (value < 0) {
    face.appendChild(el('div', { class: 'die__mark', text: '⌬' }));
    return face;
  }

  const grid = el('div', { class: 'die__pipgrid' });
  const on = new Set(PIPS[value] ?? []);
  for (let i = 0; i < 9; i++) {
    grid.appendChild(el('i', { class: on.has(i) ? 'pip is-on' : 'pip' }));
  }
  face.appendChild(grid);
  if (value === 0) face.appendChild(el('div', { class: 'die__void', text: '0' }));
  face.appendChild(el('div', { class: 'die__num mono', text: String(value) }));
  return face;
}

// ─────────────────────────────────────────────────────────────────────────────
// One die
// ─────────────────────────────────────────────────────────────────────────────

class DieView {
  readonly el: HTMLElement;
  readonly slot: HTMLElement;
  readonly dock: HTMLElement;
  private cube: HTMLElement;
  private settleTimer = 0;
  value: number | null = null;

  constructor(readonly index: DieIndex) {
    this.cube = el('div', { class: 'die__cube' });
    for (const f of FACES) {
      const node = buildFace(f.value);
      node.classList.add(`die__face--${f.key}`);
      this.cube.appendChild(node);
    }

    this.slot = el(
      'div',
      { class: 'die__slot', attrs: { role: 'button', tabindex: 0 } },
      el('div', { class: 'die__socket', aria: { hidden: 'true' } }),
      this.cube,
      el('div', { class: 'die__crack', aria: { hidden: 'true' } }, el('i'), el('i'), el('i')),
      el('div', { class: 'die__shadow', aria: { hidden: 'true' } }),
    );

    this.dock = el('div', { class: 'die__dock' });

    // The ordinal is a corner badge on the cube rather than a row of its own —
    // the hint line still says "DIE 2 ARMED" and the chassis chips still read
    // "D2", so the mapping has to stay visible without costing 9 px of height.
    this.el = el(
      'div',
      { class: 'die', data: { die: String(index) } },
      el('div', { class: 'die__ordinal mono', text: `D${index + 1}`, aria: { hidden: 'true' } }),
      this.slot,
      this.dock,
    );
    this.setValue(null);
  }

  /** Snap to a value with no animation. */
  setValue(v: number | null): void {
    this.value = v;
    if (v === null) {
      this.el.classList.remove('is-revealed');
      this.el.removeAttribute('data-value');
      this.cube.style.transition = 'none';
      this.cube.style.transform = 'rotateX(-26deg) rotateY(38deg)';
      return;
    }
    const { rx, ry } = faceFor(v);
    this.cube.style.transition = 'none';
    this.cube.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`;
    this.el.classList.add('is-revealed');
    this.el.setAttribute('data-value', String(v));
  }

  /** Tumble to `v`, land, and bounce. Resolves when the die has settled. */
  spinTo(v: number, ms: number, delay: number): Promise<void> {
    return new Promise<void>((resolve) => {
      const { rx, ry } = faceFor(v);
      const spinX = 2 + Math.floor(Math.random() * 2);
      const spinY = 3 + Math.floor(Math.random() * 3);

      this.el.classList.remove('is-settled', 'is-cracked');
      this.el.classList.add('is-rolling');
      this.el.removeAttribute('data-value');
      this.el.classList.remove('is-revealed');

      this.cube.style.transition = 'none';
      this.cube.style.transform =
        `rotateX(${rx - 360 * spinX + 143}deg) rotateY(${ry - 360 * spinY + 217}deg)`;
      // force a reflow so the browser takes the start orientation as read
      void this.cube.offsetWidth;

      window.setTimeout(() => {
        this.cube.style.transition = `transform ${ms}ms cubic-bezier(0.12, 0.72, 0.16, 1)`;
        this.cube.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`;
      }, delay);

      window.clearTimeout(this.settleTimer);
      this.settleTimer = window.setTimeout(() => {
        this.value = v;
        this.el.classList.remove('is-rolling');
        this.el.classList.add('is-revealed', 'is-settled');
        this.el.setAttribute('data-value', String(v));
        haptic(v === 0 ? [4, 26, 4] : 10);
        window.setTimeout(() => this.el.classList.remove('is-settled'), 520);
        resolve();
      }, delay + ms);
    });
  }

  crack(): void {
    this.el.classList.add('is-cracked');
  }

  dispose(): void {
    window.clearTimeout(this.settleTimer);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tray
// ─────────────────────────────────────────────────────────────────────────────

export type TrayMode = 'hidden' | 'await_roll' | 'assign' | 'acting' | 'enemy';

export interface DiceTrayState {
  mode: TrayMode;
  dice: [number, number, number] | null;
  assignments: Partial<Record<DieIndex, UnitId>>;
  /** Living chassis on the acting side — drives surplus-die discarding. */
  livingUnits: number;
  /** Who owns this roll ("YOU" / the hostile call-sign). */
  ownerLabel: string;
  /** A backend call is in flight; freeze the controls. */
  busy: boolean;
}

export interface DiceTrayOpts {
  onRoll(): void;
  onConfirm(): void;
  onEndTurn(): void;
  onAssign(die: DieIndex, unitId: UnitId): void;
  onUnassign(die: DieIndex): void;
  /** Armed die changed (tap-then-tap flow). `null` clears the arm. */
  onArmedChange(die: DieIndex | null): void;
  /** Drag started / ended, so the screen can light valid targets. */
  onDragChange(die: DieIndex | null): void;
  /** Resolve a viewport point to a droppable unit id. */
  resolveDrop(clientX: number, clientY: number): UnitId | null;
  /** Short label docked beneath an assigned die. */
  labelOf(unitId: UnitId): string;
}

export class DiceTray {
  readonly el: HTMLElement;

  private dice: DieView[];
  private summary: HTMLElement;
  private apTotal: HTMLElement;
  private note: HTMLElement;
  private actions: HTMLElement;
  private stamp: HTMLElement;
  private ghost: HTMLElement | null = null;

  private state: DiceTrayState = {
    mode: 'hidden',
    dice: null,
    assignments: {},
    livingUnits: 0,
    ownerLabel: '',
    busy: false,
  };

  private rolling = false;
  private armed: DieIndex | null = null;
  private dragDie: DieIndex | null = null;
  private dragStart = { x: 0, y: 0 };
  private dragging = false;
  private pointerId = -1;
  private disposed = false;

  constructor(private opts: DiceTrayOpts) {
    this.dice = DIE_INDICES.map((i) => new DieView(i));

    this.summary = el('div', { class: 'tray__summary mono truncate' });
    this.apTotal = el('div', { class: 'tray__ap' });
    this.note = el('div', { class: 'tray__note truncate' });
    this.actions = el('div', { class: 'tray__actions' });
    this.stamp = el('div', { class: 'tray__stamp display', text: 'TOTAL SYSTEMS FAILURE' });

    const rail = el('div', { class: 'tray__rail' });
    for (const d of this.dice) rail.appendChild(d.el);

    this.el = el(
      'div',
      { class: 'tray' },
      el('div', { class: 'tray__glow', aria: { hidden: 'true' } }),
      el('div', { class: 'tray__grille', aria: { hidden: 'true' } }),
      el('div', { class: 'tray__body' }, rail, el('div', { class: 'tray__side' }, this.apTotal, this.actions)),
      el('div', { class: 'tray__foot' }, this.summary, this.note),
      this.stamp,
    );

    for (const d of this.dice) this.attachDie(d);
    this.render();
  }

  // ── public API ────────────────────────────────────────────────────────────

  sync(next: DiceTrayState): void {
    this.state = next;
    if (next.mode !== 'assign') {
      this.armed = null;
    }
    if (!this.rolling) {
      if (next.dice === null) {
        for (const d of this.dice) d.setValue(null);
      } else {
        for (const d of this.dice) {
          if (d.value !== next.dice[d.index]) d.setValue(next.dice[d.index]);
        }
      }
    }
    this.render();
  }

  /** Tumble the dice and reveal. Resolves once all three have settled. */
  async rollAnimation(dice: [number, number, number]): Promise<void> {
    if (this.disposed) return;
    this.rolling = true;
    this.el.classList.add('is-rolling');
    this.el.classList.remove('is-tz');
    this.stamp.classList.remove('is-on');
    emitFx({ type: 'dice_roll' });

    const ms = reduced() ? 220 : FX.diceRollMs;
    const stagger = reduced() ? 0 : 110;
    await Promise.all(this.dice.map((d, i) => d.spinTo(dice[i], ms, i * stagger)));

    this.rolling = false;
    this.el.classList.remove('is-rolling');
    this.state = { ...this.state, dice };
    this.render();
  }

  /** The tray flashes, the dice crack, the stamp slams down. */
  async tripleZero(): Promise<void> {
    if (this.disposed) return;
    this.el.classList.add('is-tz');
    haptic([60, 50, 60, 50, 140]);
    await new Promise<void>((r) => window.setTimeout(r, reduced() ? 40 : 240));
    for (const d of this.dice) d.crack();
    this.stamp.classList.add('is-on');
    await new Promise<void>((r) => window.setTimeout(r, reduced() ? 60 : 1500));
  }

  clearTripleZero(): void {
    this.el.classList.remove('is-tz');
    this.stamp.classList.remove('is-on');
    for (const d of this.dice) d.el.classList.remove('is-cracked');
  }

  get armedDie(): DieIndex | null {
    return this.armed;
  }

  /** Clear the armed die without firing the callback again. */
  disarm(): void {
    if (this.armed === null) return;
    this.armed = null;
    this.render();
  }

  dispose(): void {
    this.disposed = true;
    this.killGhost();
    for (const d of this.dice) d.dispose();
  }

  // ── rendering ─────────────────────────────────────────────────────────────

  private assignedCount(): number {
    let n = 0;
    for (const d of DIE_INDICES) if (this.state.assignments[d] !== undefined) n++;
    return n;
  }

  private assignableSlots(): number {
    return Math.min(BATTLE.diceCount, Math.max(0, this.state.livingUnits));
  }

  private committedAp(): number {
    const dice = this.state.dice;
    if (!dice) return 0;
    let total = 0;
    for (const d of DIE_INDICES) {
      if (this.state.assignments[d] !== undefined) total += dice[d];
    }
    return total;
  }

  private render(): void {
    const s = this.state;
    this.el.classList.toggle('is-hidden', s.mode === 'hidden');
    this.el.classList.toggle('is-enemy', s.mode === 'enemy');
    this.el.classList.toggle('is-assign', s.mode === 'assign');
    this.el.classList.toggle('is-acting', s.mode === 'acting');
    this.el.classList.toggle('is-await', s.mode === 'await_roll');
    this.el.classList.toggle('is-busy', s.busy);
    if (s.mode === 'hidden') return;

    const slots = this.assignableSlots();
    const assigned = this.assignedCount();
    const interactive = s.mode === 'assign' && !s.busy && !this.rolling;

    // per-die state
    for (const d of this.dice) {
      const unitId = s.assignments[d.index];
      const isAssigned = unitId !== undefined;
      const surplus = !isAssigned && assigned >= slots && s.dice !== null;
      d.el.classList.toggle('is-assigned', isAssigned);
      d.el.classList.toggle('is-armed', this.armed === d.index);
      d.el.classList.toggle('is-discarded', surplus && s.mode !== 'await_roll');
      d.el.classList.toggle('is-live', interactive && !surplus);
      d.el.classList.toggle('is-zero', s.dice !== null && s.dice[d.index] === 0);
      d.slot.setAttribute('aria-disabled', String(!interactive));
      d.slot.setAttribute(
        'aria-label',
        s.dice === null
          ? `die ${d.index + 1}, not rolled`
          : `die ${d.index + 1}, value ${s.dice[d.index]}${isAssigned ? ', assigned' : ''}`,
      );

      clear(d.dock);
      if (isAssigned && unitId !== undefined) {
        const ap = s.dice ? s.dice[d.index] : 0;
        d.dock.appendChild(
          el('span', { class: 'die__docklabel', text: this.opts.labelOf(unitId).split(' · ')[0] }),
        );
        d.dock.appendChild(
          el('span', {
            class: ap === 0 ? 'die__dockap is-null' : 'die__dockap',
            text: ap === 0 ? 'SKIP' : `${ap} AP`,
          }),
        );
        d.dock.classList.add('is-on');
      } else if (surplus) {
        d.dock.appendChild(el('span', { class: 'die__discard', text: 'DISCARDED' }));
        d.dock.classList.add('is-on');
      } else if (s.dice !== null && s.mode !== 'enemy') {
        d.dock.appendChild(el('span', { class: 'die__discard', text: 'LOOSE' }));
        d.dock.classList.add('is-on');
      } else {
        d.dock.classList.remove('is-on');
      }
    }

    // summary + AP readout
    clear(this.apTotal);
    if (s.dice === null) {
      this.summary.textContent =
        s.mode === 'enemy'
          ? `${s.ownerLabel} IS ROLLING`
          : 'THREE DICE · 0–4 EACH';
    } else {
      const total = this.committedAp();
      const roll = `${s.dice[0]}·${s.dice[1]}·${s.dice[2]}`;
      this.summary.textContent =
        s.mode === 'assign'
          ? `ROLL ${roll} · ${assigned}/${slots} ASSIGNED`
          : `ROLL ${roll} · ${total} AP`;
      if (s.mode === 'assign') {
        this.apTotal.appendChild(el('span', { class: 'tray__ap-k', text: 'AP' }));
        this.apTotal.appendChild(el('span', { class: 'tray__ap-v mono tnum', text: `${total}` }));
      }
    }

    // note line — the one sentence that says what to do next
    clear(this.note);
    if (s.mode === 'await_roll') {
      this.note.appendChild(
        el('span', { class: 'tray__hint', text: 'YOU ASSIGN THEM AFTER YOU SEE THEM' }),
      );
    } else if (s.mode === 'assign') {
      if (slots < BATTLE.diceCount) {
        this.note.appendChild(
          el('span', {
            class: 'tray__warn',
            text: `${BATTLE.diceCount - slots} DIE DISCARDED — ${slots} CHASSIS LEFT`,
          }),
        );
      } else {
        this.note.appendChild(
          el('span', {
            class: 'tray__hint',
            text:
              this.armed !== null
                ? `DIE ${this.armed + 1} ARMED — TAP A CHASSIS`
                : 'DRAG A DIE ONTO A CHASSIS',
          }),
        );
      }
    } else if (s.mode === 'enemy') {
      this.note.appendChild(el('span', { class: 'tray__hint', text: 'OBSERVING HOSTILE COMMAND' }));
    } else if (s.mode === 'acting') {
      this.note.appendChild(
        el('span', { class: 'tray__hint', text: 'TAP A CHASSIS TO SPEND ITS AP' }),
      );
    }

    // actions
    clear(this.actions);
    if (s.mode === 'await_roll') {
      const roll = el(
        'button',
        {
          class: 'tray-btn tray-btn--roll',
          attrs: { type: 'button', disabled: s.busy || this.rolling },
        },
        el('span', { class: 'tray-btn__label display', text: 'ROLL 3 DICE' }),
        el('span', { class: 'tray-btn__sub mono', text: '0–4 · SERVER ROLLED' }),
      );
      roll.addEventListener('click', () => {
        if (s.busy || this.rolling) return;
        haptic([8, 20, 8]);
        this.opts.onRoll();
      });
      this.actions.appendChild(roll);
    } else if (s.mode === 'assign') {
      const none = assigned === 0;
      const confirm = el(
        'button',
        {
          class: `tray-btn tray-btn--confirm${none ? ' is-forfeit' : ''}`,
          attrs: { type: 'button', disabled: s.busy || this.rolling },
        },
        el('span', {
          class: 'tray-btn__label display',
          text: none ? 'FORFEIT TURN' : 'CONFIRM',
        }),
        el('span', {
          class: 'tray-btn__sub mono',
          text: none ? 'NO DIE ASSIGNED' : `${this.committedAp()} AP · ${assigned} CHASSIS`,
        }),
      );
      confirm.addEventListener('click', () => {
        if (s.busy || this.rolling) return;
        haptic([10, 26, 10]);
        this.opts.onConfirm();
      });
      this.actions.appendChild(confirm);
    } else if (s.mode === 'acting') {
      const end = el(
        'button',
        { class: 'tray-btn tray-btn--end', attrs: { type: 'button', disabled: s.busy } },
        el('span', { class: 'tray-btn__label display', text: 'END TURN' }),
        el('span', { class: 'tray-btn__sub mono', text: 'PASS THE BOARD' }),
      );
      end.addEventListener('click', () => {
        if (s.busy) return;
        this.opts.onEndTurn();
      });
      this.actions.appendChild(end);
    }
  }

  // ── input ─────────────────────────────────────────────────────────────────

  private canManipulate(): boolean {
    return this.state.mode === 'assign' && !this.state.busy && !this.rolling;
  }

  private attachDie(d: DieView): void {
    d.slot.addEventListener('pointerdown', (ev: PointerEvent) => {
      if (!this.canManipulate()) return;
      if (this.pointerId !== -1) return;
      ev.preventDefault();
      this.pointerId = ev.pointerId;
      this.dragDie = d.index;
      this.dragging = false;
      this.dragStart = { x: ev.clientX, y: ev.clientY };
      try {
        d.slot.setPointerCapture(ev.pointerId);
      } catch {
        /* capture is a nicety, not a requirement */
      }
    });

    d.slot.addEventListener('pointermove', (ev: PointerEvent) => {
      if (ev.pointerId !== this.pointerId || this.dragDie === null) return;
      const dx = ev.clientX - this.dragStart.x;
      const dy = ev.clientY - this.dragStart.y;
      if (!this.dragging && Math.hypot(dx, dy) > 8) {
        this.dragging = true;
        this.beginGhost(this.dragDie, ev.clientX, ev.clientY);
      }
      if (this.dragging) this.moveGhost(ev.clientX, ev.clientY);
    });

    const finish = (ev: PointerEvent): void => {
      if (ev.pointerId !== this.pointerId) return;
      try {
        d.slot.releasePointerCapture(ev.pointerId);
      } catch {
        /* ignore */
      }
      this.pointerId = -1;
      const die = this.dragDie;
      this.dragDie = null;
      if (die === null) return;

      if (this.dragging) {
        this.dragging = false;
        const target = this.opts.resolveDrop(ev.clientX, ev.clientY);
        this.killGhost();
        this.opts.onDragChange(null);
        if (target) {
          if (this.state.assignments[die] === target) {
            // dropped back where it already was — nothing to do
          } else {
            if (this.state.assignments[die] !== undefined) this.opts.onUnassign(die);
            haptic([10, 22, 10]);
            this.opts.onAssign(die, target);
          }
        } else if (this.state.assignments[die] !== undefined) {
          haptic(16);
          this.opts.onUnassign(die);
        }
        return;
      }

      // plain tap
      if (this.state.assignments[die] !== undefined) {
        haptic(14);
        this.opts.onUnassign(die);
        return;
      }
      const surplus = this.assignedCount() >= this.assignableSlots();
      if (surplus) {
        haptic([30, 20, 30]);
        return;
      }
      this.armed = this.armed === die ? null : die;
      haptic(9);
      this.opts.onArmedChange(this.armed);
      this.render();
    };

    d.slot.addEventListener('pointerup', finish);
    d.slot.addEventListener('pointercancel', (ev: PointerEvent) => {
      if (ev.pointerId !== this.pointerId) return;
      this.pointerId = -1;
      this.dragDie = null;
      this.dragging = false;
      this.killGhost();
      this.opts.onDragChange(null);
    });

    d.slot.addEventListener('keydown', (ev: KeyboardEvent) => {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      if (!this.canManipulate()) return;
      ev.preventDefault();
      if (this.state.assignments[d.index] !== undefined) {
        this.opts.onUnassign(d.index);
        return;
      }
      this.armed = this.armed === d.index ? null : d.index;
      this.opts.onArmedChange(this.armed);
      this.render();
    });
  }

  private beginGhost(die: DieIndex, x: number, y: number): void {
    const value = this.state.dice ? this.state.dice[die] : 0;
    const ghost = el('div', { class: 'die-ghost', data: { value: String(value) } });
    ghost.appendChild(buildFace(value));
    ghost.appendChild(el('div', { class: 'die-ghost__trail', aria: { hidden: 'true' } }));
    document.body.appendChild(ghost);
    this.ghost = ghost;
    this.moveGhost(x, y);
    this.dice[die].el.classList.add('is-dragging');
    haptic(8);
    this.opts.onDragChange(die);
  }

  private moveGhost(x: number, y: number): void {
    if (!this.ghost) return;
    this.ghost.style.transform = `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;
  }

  private killGhost(): void {
    if (this.ghost) {
      this.ghost.remove();
      this.ghost = null;
    }
    for (const d of this.dice) d.el.classList.remove('is-dragging');
  }
}
