/**
 * TERRA BELLUM — battle cinematics (GDD §7, §12.3).
 *
 * Full-screen overlays that own a moment and then get out of the way:
 *
 *  - `intro()`      both banners clash, the board and its twist are announced,
 *                   then a 3-2-1 drop.
 *  - `tripleZero()` the 0-0-0 humiliation: rain, desaturation, glitch, and a
 *                   mock system-failure readout. Required by GDD §7.2.
 *  - `concede()`    the exact ledger of what conceding costs, behind a hold.
 *  - `outcome()`    victory / defeat card with surviving roster and spoils.
 *
 * Every overlay flips `view.cinematic` so the 3D layer suppresses input while
 * it plays, and every timer is tracked so `dispose()` cannot leak.
 */
import { UNITS } from '../../config/units';
import { TERRAIN_META } from '../../config/balance';
import { FX } from '../../config/visual';
import { view } from '../../game/store';
import type { BattleSide, BattleState, BattleUnit } from '../../game/types';
import { allTemplates } from '../../game/board/templates';
import { clear, cssHex, el, haptic, rgba, svg as svgEl } from '../dom';
import { button, holdButton, unitSilhouette, unitAccent } from '../components';

// ─────────────────────────────────────────────────────────────────────────────

/** The hand-authored "twist" line for a board template id (GDD §7.1). */
export function boardTwistOf(boardId: string): string {
  const t = allTemplates().find((x) => x.id === boardId);
  return t ? t.twist : 'UNCHARTED HAZARD PROFILE';
}

/** The flavour blurb for a board template id. */
export function boardBlurbOf(boardId: string): string {
  const t = allTemplates().find((x) => x.id === boardId);
  return t ? t.blurb : '';
}

const SIDE_ROLE: Record<BattleSide, string> = {
  attacker: 'ATTACKING FORCE',
  defender: 'HOLDING FORCE',
};

function reduced(): boolean {
  return document.body.classList.contains('reduce-motion');
}

/** Scale a cinematic beat down to near-nothing when motion is reduced. */
function beat(ms: number): number {
  return reduced() ? Math.min(140, Math.round(ms * 0.14)) : ms;
}

function livingOf(b: BattleState, side: BattleSide): BattleUnit[] {
  return b.units.filter((u) => u.side === side && u.alive);
}

function rosterStrip(units: BattleUnit[], accent: string): HTMLElement {
  const strip = el('div', { class: 'cine-roster scroll-x no-scrollbar' });
  if (units.length === 0) {
    strip.appendChild(el('div', { class: 'cine-roster__none', text: 'NO CHASSIS RECOVERED' }));
    return strip;
  }
  for (const u of units) {
    const cell = el('div', {
      class: 'cine-roster__cell',
      style: `--accent:${unitAccent(u.type)};--rim:${accent}`,
    });
    const art = el('div', { class: 'cine-roster__art' });
    art.appendChild(svgEl(unitSilhouette(u.type)));
    cell.appendChild(art);
    cell.appendChild(el('div', { class: 'cine-roster__code', text: UNITS[u.type].codename }));
    cell.appendChild(
      el('div', { class: 'cine-roster__hp mono tnum', text: `${u.hp}/${u.maxHp}` }),
    );
    const bar = el('div', { class: 'cine-roster__bar' });
    bar.appendChild(
      el('i', { style: `width:${Math.max(0, Math.min(1, u.hp / u.maxHp)) * 100}%` }),
    );
    cell.appendChild(bar);
    strip.appendChild(cell);
  }
  return strip;
}

// ─────────────────────────────────────────────────────────────────────────────

export interface OutcomeSpoils {
  /** Headline lines under the verdict, e.g. "HEX 4,-2 SECURED". */
  lines: string[];
  /** Rendered under the roster; the salvage note after a concession. */
  footnote?: string;
}

export class Cinematics {
  readonly el: HTMLElement;

  private layer: HTMLElement | null = null;
  private timers = new Set<number>();
  private disposed = false;

  constructor() {
    this.el = el('div', { class: 'btl-cine', aria: { hidden: 'true' } });
  }

  // ── plumbing ──────────────────────────────────────────────────────────────

  private wait(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      if (this.disposed) {
        resolve();
        return;
      }
      const h = window.setTimeout(() => {
        this.timers.delete(h);
        resolve();
      }, Math.max(0, ms));
      this.timers.add(h);
    });
  }

  private mountLayer(node: HTMLElement, interactive: boolean): void {
    this.dropLayer();
    this.layer = node;
    this.el.classList.add('is-live');
    this.el.classList.toggle('is-interactive', interactive);
    this.el.setAttribute('aria-hidden', 'false');
    this.el.appendChild(node);
  }

  private dropLayer(): void {
    if (this.layer) {
      this.layer.remove();
      this.layer = null;
    }
    clear(this.el);
    this.el.classList.remove('is-live', 'is-interactive');
    this.el.setAttribute('aria-hidden', 'true');
  }

  private setCinematic(kind: 'triple_zero' | 'battle_intro' | 'victory' | 'defeat' | undefined): void {
    view.patch({ cinematic: kind });
  }

  /** Tear the current overlay down. Safe to call at any time. */
  clear(): void {
    this.dropLayer();
    if (view.get().cinematic !== undefined) this.setCinematic(undefined);
  }

  dispose(): void {
    this.disposed = true;
    for (const h of this.timers) window.clearTimeout(h);
    this.timers.clear();
    this.dropLayer();
    if (view.get().cinematic !== undefined) this.setCinematic(undefined);
  }

  // ── intro ─────────────────────────────────────────────────────────────────

  /** Both banners clash, the board is announced, then a countdown drops. */
  async intro(b: BattleState, mySide: BattleSide): Promise<void> {
    if (this.disposed) return;
    this.setCinematic('battle_intro');

    const atkColor = cssHex(b.attacker.guildColor);
    const defColorRaw = b.defender.guildColor;
    const defColor = cssHex(defColorRaw === b.attacker.guildColor ? 0xff4d5e : defColorRaw);

    const bannerFor = (side: BattleSide, color: string): HTMLElement => {
      const p = side === 'attacker' ? b.attacker : b.defender;
      const count = livingOf(b, side).length;
      const wrap = el('div', {
        class: `cine-banner cine-banner--${side === 'attacker' ? 'l' : 'r'}${
          side === mySide ? ' is-me' : ''
        }`,
        style: `--gc:${color}`,
      });
      wrap.appendChild(el('div', { class: 'cine-banner__role', text: SIDE_ROLE[side] }));
      wrap.appendChild(el('div', { class: 'cine-banner__name display', text: p.playerName }));
      wrap.appendChild(el('div', { class: 'cine-banner__tag mono', text: `[${p.guildTag}]` }));
      wrap.appendChild(
        el('div', { class: 'cine-banner__count mono tnum', text: `${count} CHASSIS` }),
      );
      if (side === mySide) wrap.appendChild(el('div', { class: 'cine-banner__you', text: 'YOU' }));
      if (p.ai) wrap.appendChild(el('div', { class: 'cine-banner__ai', text: 'AUTO-DEFENSE' }));
      return wrap;
    };

    const meta = TERRAIN_META[b.terrain];
    const countNode = el('div', { class: 'cine-count', aria: { hidden: 'true' } });

    const root = el(
      'div',
      { class: 'cine cine--intro' },
      el('div', { class: 'cine__scrim' }),
      el('div', { class: 'cine__rule cine__rule--t' }),
      el('div', { class: 'cine__rule cine__rule--b' }),
      el(
        'div',
        { class: 'cine-clash' },
        bannerFor('attacker', atkColor),
        el('div', { class: 'cine-clash__vs display', text: 'VS' }),
        bannerFor('defender', defColor),
      ),
      el(
        'div',
        { class: 'cine-board' },
        el('div', { class: 'cine-board__label', text: 'ENGAGEMENT ZONE' }),
        el('div', { class: 'cine-board__name display', text: b.boardName }),
        el('div', { class: 'cine-board__twist', text: boardTwistOf(b.boardId) }),
        el(
          'div',
          { class: 'cine-board__terrain mono' },
          el('b', { text: meta.label }),
          ` · ${b.w}×${b.h} · HEX ${b.hexId}`,
        ),
        b.fortLevel > 0
          ? el('div', {
              class: 'cine-board__fort',
              text: `DEFENDER FORTIFICATION L${b.fortLevel} ACTIVE`,
            })
          : null,
      ),
      countNode,
    );

    this.mountLayer(root, false);
    haptic([18, 40, 18]);

    await this.wait(beat(760));
    if (this.disposed) return;
    root.classList.add('is-clashed');
    haptic([30, 30, 60]);
    await this.wait(beat(760));
    if (this.disposed) return;
    root.classList.add('is-briefed');
    await this.wait(beat(880));

    for (const n of ['3', '2', '1']) {
      if (this.disposed) return;
      clear(countNode);
      const tick = el('span', { class: 'cine-count__n display', text: n });
      countNode.appendChild(tick);
      haptic(14);
      await this.wait(beat(430));
    }
    if (this.disposed) return;
    clear(countNode);
    countNode.appendChild(el('span', { class: 'cine-count__go display', text: 'ENGAGE' }));
    haptic([26, 40, 26]);
    await this.wait(beat(520));

    root.classList.add('is-out');
    await this.wait(beat(280));
    this.clear();
  }

  // ── triple zero ───────────────────────────────────────────────────────────

  /**
   * GDD §7.2 — the 0-0-0 rule, rendered as slowly as it deserves. Rain-streaked,
   * desaturated, glitching, with a system-failure readout that fails one line at
   * a time. There is no reroll and the overlay says so.
   */
  async tripleZero(mine: boolean, playerName: string): Promise<void> {
    if (this.disposed) return;
    this.setCinematic('triple_zero');

    const readout = el('div', { class: 'tz__readout mono' });
    const root = el(
      'div',
      { class: `cine cine--tz${mine ? ' is-mine' : ''}` },
      el('div', { class: 'tz__drain' }),
      el('div', { class: 'tz__rain', aria: { hidden: 'true' } }),
      el('div', { class: 'tz__rain tz__rain--near', aria: { hidden: 'true' } }),
      el('div', { class: 'tz__scan', aria: { hidden: 'true' } }),
      el(
        'div',
        { class: 'tz__core' },
        el('div', { class: 'tz__zeros display' }, el('i', { text: '0' }), el('i', { text: '0' }), el('i', { text: '0' })),
        el('div', {
          class: 'tz__title display',
          text: mine ? 'TOTAL SYSTEMS FAILURE' : 'HOSTILE SYSTEMS FAILURE',
          attrs: { 'data-glitch': mine ? 'TOTAL SYSTEMS FAILURE' : 'HOSTILE SYSTEMS FAILURE' },
        }),
        el('div', {
          class: 'tz__who mono',
          text: `${playerName.toUpperCase()} // TURN FORFEIT`,
        }),
        readout,
      ),
    );

    this.mountLayer(root, false);
    haptic(mine ? [60, 70, 60, 70, 160] : [20, 40, 20]);

    const lines: [string, string][] = mine
      ? [
          ['REACTOR HANDSHAKE', 'FAIL'],
          ['GYRO STABILISATION', 'FAIL'],
          ['TARGETING SOLUTION', 'FAIL'],
          ['FIRE CONTROL LINK', 'FAIL'],
          ['CREW MORALE', 'FAIL'],
          ['REROLL SUBSYSTEM', 'DOES NOT EXIST'],
          ['GUILD BROADCAST', 'SENT'],
        ]
      : [
          ['HOSTILE REACTOR', 'COLD'],
          ['HOSTILE FIRE CONTROL', 'OFFLINE'],
          ['THEIR TURN', 'FORFEIT'],
          ['YOUR OPPORTUNITY', 'CONSIDERABLE'],
        ];

    const step = beat(FX.tripleZeroMs / (lines.length + 3));
    for (const [k, v] of lines) {
      if (this.disposed) return;
      const row = el(
        'div',
        { class: `tz__line${v === 'SENT' ? ' is-sent' : ''}` },
        el('span', { class: 'tz__k', text: k }),
        el('span', { class: 'tz__dots', aria: { hidden: 'true' } }),
        el('span', { class: 'tz__v', text: v }),
      );
      readout.appendChild(row);
      haptic(6);
      await this.wait(step);
    }

    if (this.disposed) return;
    readout.appendChild(
      el('div', {
        class: 'tz__sig',
        text: mine
          ? 'Your entire guild has been informed.'
          : 'Their entire guild has been informed.',
      }),
    );
    await this.wait(beat(FX.tripleZeroMs * 0.28));
    if (this.disposed) return;
    root.classList.add('is-out');
    await this.wait(beat(340));
    this.clear();
  }

  // ── concede ledger ────────────────────────────────────────────────────────

  /**
   * GDD §7.3 — spells out the whole cost before anything is signed: every
   * survivor halves, the army retreats one hex, and no attack debuff follows.
   */
  concede(
    b: BattleState,
    mySide: BattleSide,
    handlers: { onConfirm: () => void; onCancel: () => void },
  ): void {
    const survivors = livingOf(b, mySide);
    const ledger = el('div', { class: 'cede__ledger' });
    for (const u of survivors) {
      const after = Math.max(1, Math.ceil(u.hp / 2));
      const row = el(
        'div',
        { class: 'cede__row', style: `--accent:${unitAccent(u.type)}` },
        el('span', { class: 'cede__art', html: unitSilhouette(u.type) }),
        el('span', { class: 'cede__name', text: UNITS[u.type].codename }),
        el('span', { class: 'cede__from mono tnum', text: `${u.hp}` }),
        el('span', { class: 'cede__arrow', text: '→' }),
        el('span', { class: 'cede__to mono tnum', text: `${after}` }),
      );
      ledger.appendChild(row);
    }
    if (survivors.length === 0) {
      ledger.appendChild(el('div', { class: 'cede__none', text: 'NOTHING LEFT TO SALVAGE' }));
    }

    const cancel = button('STAY IN THE FIGHT', {
      variant: 'ghost',
      wide: true,
      onClick: () => {
        this.clear();
        handlers.onCancel();
      },
    });

    const confirm = holdButton('CONCEDE THE FIELD', {
      variant: 'danger',
      holdMs: 1400,
      hint: 'hold — this cannot be undone',
      onComplete: () => {
        this.clear();
        handlers.onConfirm();
      },
    });

    const root = el(
      'div',
      { class: 'cine cine--cede is-interactive' },
      el('div', { class: 'cine__scrim' }),
      el(
        'div',
        { class: 'cede' },
        el('div', { class: 'cede__stamp display', text: 'WITHDRAWAL ORDER' }),
        el('div', {
          class: 'cede__lede',
          text: 'Conceding ends the engagement immediately. This is the entire cost:',
        }),
        el(
          'ul',
          { class: 'cede__terms' },
          el('li', {}, el('b', { text: 'Every surviving unit drops to half HP' }), ' (rounded up, floor of 1).'),
          el('li', {}, el('b', { text: 'The army retreats one hex' }), ' toward the ground it came from. If no lane exists, it is destroyed.'),
          el('li', {}, 'No attack penalty. No debuff. No further loss.'),
        ),
        el('div', { class: 'cede__head mono', text: `SALVAGE LEDGER — ${survivors.length} CHASSIS` }),
        ledger,
        el('div', { class: 'cede__actions' }, confirm, cancel),
      ),
    );

    this.mountLayer(root, true);
    haptic([20, 50, 20]);
  }

  // ── outcome ───────────────────────────────────────────────────────────────

  /** The victory / defeat card. Stays until the shell routes away. */
  outcome(b: BattleState, mySide: BattleSide, spoils: OutcomeSpoils, onDismiss?: () => void): void {
    const won = b.winner === mySide;
    this.setCinematic(won ? 'victory' : 'defeat');

    const survivors = livingOf(b, mySide);
    const enemy = livingOf(b, mySide === 'attacker' ? 'defender' : 'attacker');
    const mine = mySide === 'attacker' ? b.attacker : b.defender;
    const foe = mySide === 'attacker' ? b.defender : b.attacker;
    const accent = won ? 'var(--teal)' : 'var(--crimson)';

    const reasonLabel =
      b.endReason === 'wipe'
        ? 'TOTAL ANNIHILATION'
        : b.endReason === 'concede'
          ? 'FIELD CONCEDED'
          : 'COMMAND LINK LOST';

    const lines = el('div', { class: 'out__lines' });
    for (const s of spoils.lines) {
      lines.appendChild(el('div', { class: 'out__line mono', text: s }));
    }

    const root = el(
      'div',
      { class: `cine cine--out ${won ? 'is-win' : 'is-lose'} is-interactive` },
      el('div', { class: 'cine__scrim' }),
      el('div', { class: 'out__rays', aria: { hidden: 'true' } }),
      el(
        'div',
        { class: 'out', style: `--accent:${accent}` },
        el('div', { class: 'out__eyebrow mono', text: reasonLabel }),
        el('div', { class: 'out__verdict display', text: won ? 'FIELD HELD' : 'FIELD LOST' }),
        el(
          'div',
          { class: 'out__vs mono' },
          el('b', { text: mine.playerName }),
          ` [${mine.guildTag}]  ${won ? '▸' : '◂'}  `,
          el('b', { text: foe.playerName }),
          ` [${foe.guildTag}]`,
        ),
        lines,
        el('div', { class: 'out__head mono', text: `YOUR SURVIVORS — ${survivors.length}` }),
        rosterStrip(survivors, cssHex(mine.guildColor)),
        el('div', { class: 'out__head mono', text: `HOSTILE SURVIVORS — ${enemy.length}` }),
        rosterStrip(enemy, cssHex(foe.guildColor)),
        spoils.footnote ? el('div', { class: 'out__foot', text: spoils.footnote }) : null,
        el('div', { class: 'out__turns mono', text: `${b.turnNumber} TURNS · BOARD ${b.boardName.toUpperCase()}` }),
        onDismiss
          ? button('RETURN TO THE MAP', {
              variant: won ? 'primary' : 'ghost',
              wide: true,
              onClick: () => {
                this.clear();
                onDismiss();
              },
            })
          : null,
      ),
    );

    this.mountLayer(root, true);
    haptic(won ? [30, 40, 30, 40, 90] : [80, 60, 80]);
  }

  /** True while any overlay owns the screen. */
  get live(): boolean {
    return this.layer !== null;
  }
}

/** Convenience accent for a guild colour, used by the screen for banners. */
export function guildTint(color: number, alpha: number): string {
  return rgba(color, alpha);
}
